/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20141107-4","meetingId":"h26-c-settlement","date":"2014年11月7日","dateIso":"2014-11-07","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"私は民生費から１４０ページのすまいるスクール運営費、１３４ページの児童相談事業、１４０ページの子育て支援センターの確認をさせていただきたいと思います。第１に、すまいるスクール運営費についてお聞かせください。こちらの時間当たりの運営費はどのくらいになりますでしょうか。第２に、児童相談事業、子育て支援センターについてお聞かせください。","respondent":"伊崎子育て支援課長","answer":"相談件数の増加につきましては、まず児童数自体が増加をしていることもありますし、それから特に虐待につきましては、近隣の方の虐待に対する意識が高まってきたことにより、通報をもとにした相談などが増えているということが考えられます。","voiceIndex":4,"id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"すまいるスクールについてなのですけれども、こちらは委託料を時間で割ったコストということで、２,７００円ほどということでお聞きいたしました。学校がある日の登校時間は８時からです。学校がない土曜日や夏休み・冬休みのすまいるスクールの利用開始時間について、３０分から１時間早めていただくための財政的な負担と、それ以外の課題について、現時点ではどのようにお考えでいらっしゃるでしょうか。","respondent":"伊崎子育て支援課長","answer":"財政的な負担と保護者の負担との関係など、さまざまな問題がありますので、そういった問題を踏まえた上で検討する課題の一つとして考えてまいりたいと考えています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"しかしながら、保育園卒園、幼稚園卒園の後の春休みの期間、入学式までの期間というのは、やはり保護者にとっても子どもにとっても心配ですとか不安や期待が入り混じった時期です。例えば、１学期もしくは春休みの期間限定だけでも、何か前向きに考えていただけるような、今後ご検討をいただけたらと思っているのですけれども、その点をもう一度お伺いできないでしょうか。お願いいたします。","respondent":"伊崎子育て支援課長","answer":"今、委員からご指摘ございましたそういった状況も踏まえまして、検討をしてまいります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、１２８ページ、民生費、高齢福祉費から、認知症高齢者の支援とケアの充実、あわせて２２１ページ、介護保険特別会計、地域支援事業費全般から、地域包括支援システムについて伺います。２番目に、１３１ページ、障害者福祉費、障害者作品展に関しまして、障害者の芸術活動について伺います。１番目です。今回の一般質問に関連して、幾つか詳しく確認の意味でも質問させていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"日常生活圏域ニーズ調査ですけれども、国のほうで提唱しておりますのがかなりの項目の調査になっておりまして、これを高齢者の方が一つ一つ読んで正確にお答えするというのはなかなか難しいのではないかという判断があります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"第六期介護保険事業計画の策定がもう間もなく迫っているので、第六期には間に合わないと思うのですけれども、ぜひよろしくお願いしたいと思います。ただ、品川区の独自システムなものですから、国からどんどん来るいろいろな地域包括ケアシステムの指針やガイドラインなどを読んでも、そのまま当てはめることがなかなか私もできなくて、これは一筋縄ではいかないなというところがあります。","respondent":"永尾高齢者福祉課長","answer":"２年ほど前から在宅介護支援センターの連絡会等で、区も交えて今後のあり方について検討しています。その中でやはり多いのが、負担が多くなっているということが１つと、あと地域支援の仕事がなかなか難しいというような指摘が出ているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"民間との役割分担というところですけれども、私の個人的な考えでは、やはり民間イコール悪かろうということではないのですけれども、信頼できる事業者であればどんどん活用すべきというのは個人的な思いなのですが、経験や人材の面でそれほどノウハウのない事業者があるということも伺っておりますので、こうした介護の質の担保として、先ほど研修等いろいろありましたけれども。","respondent":"永尾高齢者福祉課長","answer":"やはり経験を積まなくてはいけないので、これまで培ってきた在宅介護支援センターのケースなども提示しながら、民間の方とも連携してやっていきたいと考えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"一般質問でも認知症カフェの地域支援事業への位置づけを視野に入れるというようなご答弁をいただいておりまして、また一昨日も品川歴史館の項で触れましたけれども、回想法の提案については、認知症の治療や介護予防に有効であると認識をしているので、今後品川歴史館と調整し、所蔵品の有効な活用について検討していただけるということなのですが。","respondent":"永尾高齢者福祉課長","answer":"相手から昔の楽しかった・よかった思い出というのをうまく引き出して聞いていく力が重要になりますので、そういう心理学的な勉強についてもこれから進めていきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう一点、区の組織なのですけれども、認知症対策は国家戦略的な取組みでもあります。今後、区内でのご相談もどんどん増えてくると思いますので、高齢者福祉課内にも認知症担当の冠を持つような職員を配置されることも検討されてはいかがでしょうか。これはちょっと言い過ぎかもしれませんが、こんなこともぜひご検討いただければと思いますが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"認知症に関しては、これから高齢者の数がどんどん増える中、認知症の問題というのは当然多くなってくると想定しております。区といたしましても、これから認知症施策を重視していきたいと思いますので、委員ご指摘の点についても検討してまいりたいと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"１３１ページ、障害者福祉費、障害者作品展、障害者の芸術活動について伺います。区内の福祉施設からの出品も併せて行われるということでしたけれども、これはもう呼びかけは行っていらっしゃるのでしょうか。それは新規の作品を募集されるのでしょうか、それとも、既存の作品を展示されるということなのか。もし呼びかけをしたときの反応が何かあれば教えてください。","respondent":"中山障害者福祉課長","answer":"以前、平成２１年度に行いましたアール・ブリュット展と今回の展覧会の主な違いというところですが、平成２１年度につきましては、精神障害の方を中心とした、精神障害の入院患者のそういった作品を発掘した。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"意見","question":"１点、意見だけ。障害者の芸術活動支援ということで、福祉的就労事業における作品を活用した製品化というご答弁がありました。ぜひこれはプロフェッショナルも関与させていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"松永委員","kind":"質問","question":"私からは、成果報告書の１３２ページの在宅サービスセンター運営費について、次に１３６ページの病児保育、１３８ページのオアシスルーム運営費、時間がありましたら１４１ページの生活保護総務費についてお伺いします。１３２ページの在宅サービスセンター運営費について伺います。品川区が重点的に取り組んできたところと承知しております。よろしくお願いします。","respondent":"永尾高齢者福祉課長","answer":"今、合計を出していないのですけれども、各在宅サービスセンターの延べ人数は出ていますので、大体一番少ないところで、中延在宅サービスセンターが３,０７０人なのですけれども、一番多いところでいくと、荏原在宅サービスセンターが１万５,３５０人ということです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"松永委員","kind":"意見","question":"そうしますと、希望者に対しての今後のケアというか対策というのはどういったことをとられているか、お願いします。","respondent":"永尾高齢者福祉課長","answer":"ですので、普通のお稽古事のように行きたいから行くということではなくて、あくまでも自立支援という考えで、寄り添った相談を受けているところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"今後も高齢化が進んでまいりますので、ぜひともしっかりと取り組んでいただけたらと思います。次に、１３６ページの病児保育について伺います。地域の方からも、病児保育の整備が整わないと、仕事を続けることがなかなかできないという声もありますけれども、そこで今後、需要に応じて病児保育の開設などをしていくべきだと考えておりますが、区のご見解をお願いしたいと思います。","respondent":"竹田保育課長","answer":"病児保育は、働く子育て世代にとって非常に大切なものだと考えております。区としましては、荏原地区に１カ所、それから東大井地区に１カ所、計２カ所の医療機関のご協力のもと、生後６カ月のお子さんから就学前までのお子さんが病気の際に、病児保育として実施しています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"松永委員","kind":"質問","question":"急な病気などの際に利用しにくいという声もありますけれども、その改善策というのはありますでしょうか、お伺いします。","respondent":"竹田保育課長","answer":"今後も病児保育を通して、子育て世帯の支援をしていきたいと考えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"次に１３８ページ、オアシスルームについてお伺いしたいと思います。平成２５年度の成果報告書では７カ所と載っておりますけれども、区のホームページでは８カ所と増えております。そこで、オアシスルームを年間どのくらいの方々が利用されているのか、また１日の平均として何時間預けられる方が多いのか、そして一番利用される時間帯というのは何時ごろなのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"今現在実施しているのは８園です。資料によっては、ぷりすくーるは区の歳入にならないので、７園で表示されているところもありますので、資料によって７カ所、８カ所の違いが若干あります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"利用希望があったときに断るケースというのは年間どれくらいあるのか、教えていただきたいと思います。","respondent":"竹田保育課長","answer":"断ったケースを２カ月の実績をもとに推測した値なのですが、定員に対して予約ができなかった件数が、年間で３,５３４日だと推計しております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"そうすると、約１万２,０００人という方々が利用されるということで、ニーズは結構あると思いますので、そのニーズに合った区の解決策、対策はありますでしょうか、お願いいたします。","respondent":"竹田保育課長","answer":"今、各利用施設にお電話等で予約をしていただく形になっております。それで、保育課にお電話いただければ全ての施設の空き状況が確認できますので、お近くの施設だけではなくて、ほかの施設も有効に活用していただいて、子育てに役立てていただければと考えているところです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"今後ともよろしくお願いいたします。最後に、１４１ページの生活保護総務費の専門調査員等経費についてお伺いしたいと思います。今現在マスコミ等でも報道されておりますが、生活保護を不正受給されている方が多いと言われております。そこで、品川区のこれまでの調査について、そして今後の対策についてお伺いしたいと思います。","respondent":"伊東生活福祉課長","answer":"専門調査員につきましては、資産や扶養の専門調査員がおります。そこでいろいろと調べていただきまして、それで不正受給等の発見に努めまして、それをしっかりと本人から聴取していくというような形で、非常勤の専門調査員を活用しています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１３４ページの児童福祉費、認可保育園の待機児童についてお伺いいたしますので、よろしくお願いします。お父さん・お母さんの仕事を保証するとともに、子どもたちに格差のない保育を実施してほしいと求めて質問いたします。改めてまず数字を伺いますけれども、平成２５年の認可保育園の申請数と入園数、あと平成２６年の同じく認可保育園の申請数と入園数を教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２６年度につきましては、申込み者数が２,４８３人、入園者数が１,７０６人、そして待機児童数は１２８人という数です。","voiceIndex":44,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、待機児童数は伺っていないのですけれども、私としては、認可保育園に申込みをして入れない子どもが毎年増えていて、ここ２年くらい激化をしているということで、来年はもっと厳しい状況になるということがこの間の質問でわかりました。認可保育園です、区立と私立と、それぞれ分けて教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"来年の認可保育園の開設につきましては、年度で４園を予定しておりまして、補正予算で６園という形に補正をさせていただきましたけれども、来年４月の認可保育園の開設予定につきましては現在検討中のものもありますので、今は申し上げられません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"来年の入園見込み数も伺ったので、これも教えてほしいのですけれども、先ほどの数字からすると、平成２５年度保育園を申し込んで入れなかったお子さんが４２７人、平成２６年度が７７７人で、昨年よりも今年がまた申込みが増える、２,７００人ということで大変な数で、昨年度、今年度よりもさらに保育園をつくっていかなければ、さらに入れない子どもがあふれてしまうといった状況になると思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そちらのほうも含めまして、４月の開設について周知をしていく予定ですので、認可保育園、そして家庭的保育事業を含めまして、全てその時点で周知をする予定です。","voiceIndex":48,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１２月１日の広報でご案内。今日は１１月７日です。私は区立の保育園大幅増設で、待機児童ゼロにするといった覚悟をぜひ求めていきたいと思っています。ここのところ民間で続けてつくってもらっているけれども、今、民間は引っ張りだこでなかなか来ないというところで、やはり区立をつくっていかなければ解消できないと思いますが、私は覚悟を聞かせていただきたいのですが、いかがでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区は、委員ご案内のとおり近隣に先駆けて平成２２年度から開設を始めまして、２,５２８人ということで増やしてまいりました。そして近隣の、今ご案内の大田区や世田谷区などと比較しても、待機児童数は一定の数値を示しているところは十分ご案内のとおりだと思います。","voiceIndex":50,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は覚悟を聞いたのですが、６園つくると言っても、４月にできなければ。４月ですよ。今、４月の申込みをしているのに、４月に何園できて何人解消するか全然わからなくて、これはゼロを目指していることになるのでしょうか。私はかけ声だけでは全くだめで、ぜひ緊急の対策を求めたいと思いますが、なしなのでしょうか。そこをもう一回聞きます。","respondent":"今井制度改革・待機児童対策担当課長","answer":"緊急対策というお話でしたけれども、繰り返しになりますが、６月補正の中で対策をとるとともに、また認定こども園北品川第二保育園につきましても、こちらも４月からの開設ということで開設時期を早めるなど、対策をとっているというふうに考えております。","voiceIndex":52,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、内容をもうちょっと簡単にお願いしたかったのですけれども、それは後でお願いします。たしか前に聞いたときに、２０分間の介護と決まっておりましたが、その点は変わりはないのでしょうか。この３点をそれぞれ具体的に教えていただき、平成２５年度にどのように活かしてきたのかを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで実際にやった結果というところですけれども、今までおむつをずっとしていたのが、おむつがとれたとか、あと認知症でなかなか対応が難しいという方に対しても、どういう対応の方法をとれば改善されるかというところが。","voiceIndex":57,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"詳しくありがとうあります。介護が必要になっても自分の住み慣れた地域で暮らし続けるということが、高齢者の本当の心の希望だと私も思います。これは大切な事業だと思います。最後に、先ほどちょっと医療関係との連携というお話もお聞きしました。コミュニティ、地域の方々との連携も大変必要だと思うんですけれども、今後その２つ、地域コミュニティと医療に関しての連携をもう少し詳しくお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"その中で委員の院長先生も含め、訪問看護の方々、居宅サービスの方々、福祉と医療関係の方々が顔を合わせて議論できるような場を設定しております。こういう場をさらに進めながら、これから２０２５年に向けての対応についても検討していきたいと考えているところです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ議論をなさってくださるということなので、それはやはり議論だけでなくて、密着した行動に移していただけるように、必要なタイミングで、これは本当に必要なタイミングがあると思うので２４時間という設定だと思います。認証保育所と区内私立保育園、それぞれ何園中何カ所にＡＥＤの設置が完了しているのでしょうか。設置していないところはすぐ近くにあるとか、その辺の事情を教えてください。","respondent":"竹田保育課長","answer":"ＡＥＤの設置状況ですが、まず認証保育所におきましては、２１園中１２園に設置しております。私立認可保育園については、２８園中、設置予定も含めまして２３園となっているところです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"随時設置をしていただきたいのですけれども、小児用の電極パッドというのがある、また機種によっては小児モードの切り替えというのがあるみたいなので、どんなものを設置しているのかがちょっと気になるので、お願いいたします。","respondent":"竹田保育課長","answer":"ＡＥＤはメーカーによって若干形態のほうが異なっておりまして、子ども用・大人用の使い分けはパッドを取り替えるタイプと、機械本体の操作によって切り替えるタイプの２種類があります。今、導入状況はほぼ半分半分だと認識しております。","voiceIndex":63,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"１回やって、どうなんだろう、もっとたくさん練習したいという思いがあるのですけれども、また小児において呼吸原性心停止というのですか、これは音声ガイダンスで「除細動の必要はありません」と案内する可能性もあります。その場合、心肺蘇生を行う必要があるのですけれども、どんな場合にでもやはり訓練というのは大切だと思うのですが、その訓練状況を教えてください。","respondent":"竹田保育課長","answer":"この中では、委員のお話にもありましたが、ＡＥＤを含めて研修を受けているところです。それで、機械には音声による使い方ガイドもあります。緊急時に冷静な気持ちで対応できるように、日頃から職員には心構えを持つように指導しています。","voiceIndex":65,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問・要望","question":"１２９ページのひとり暮らし高齢者等福祉費全般についてお伺いをさせていただきたいと思います。高齢者見守り事業ですけれども、ひとり暮らし高齢者はますますこれから増えていくという中で、品川区でも大変先進的にさまざまな見守り事業の取組みをされているかと思います。","respondent":"大串福祉計画課長","answer":"そういった、取組みをされた期間の関係で若干減っているといったところがあります。ただし、今年度から６年目以降こういった見守り活動をやっていただいている自治会・町会の皆様につきましても、年間２万円ということで助成をさせていただいているところです。","voiceIndex":70,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった中で、今回のプレス発表にもありましたけれども、生協とか、それから新聞配達のところと協定を結ばれているかと思いますけれども、こういった協定を拡大していくということはその地域の皆様の負担軽減にもなりますし、行政としての負担を減らしていくという大変意味があることだと思うのですけれども、現在生協や新聞、それから水道とか、その他いろいろな業態と結ばれていますけれども。","respondent":"大串福祉計画課長","answer":"先ほど、地域での見守りネットワークといったところで、町会・自治会の皆様のご協力ということをご答弁させていただきましたけれども、こういった形で民間企業の皆様とも連携をしながら、地域での高齢者見守りネットワークの網の目といったものをきめ細かく編み上げて。","voiceIndex":72,"id":"exchange-030"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に徘徊高齢者探索システム事業についてお伺いさせていただきたいと思います。品川区において高齢者の行方不明者は、今、大体何名ぐらいいらっしゃるのか。区内においてはどれだけの方が行方不明で、またこの探索システムで発見された事例とかというのはあるのでしょうか。以前の質問でもありましたけれども、この事業は大体年間１０人ほどの利用しかないという現状であります。","respondent":"永尾高齢者福祉課長","answer":"品川区においても、大井地区のほうで試行的に高齢者ＳＯＳネットワークシステムというものを始めておりまして、その中で、発見されたときにどの順番でどこに通報するかというような仕組みをつくってやっているところです。こういうものが品川区内に広まればと、今検討しています。","voiceIndex":74,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは子どもたち向けの防犯のシステムでありますけれども、こういった既存のシステムを利用すれば、またこれも徘徊されている高齢者の方にも当てはまるのではないかと思いまして、そういったところのお考えをお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"お子さんの見守りの仕組みである近隣セキュリティシステムというのが大分有効に活用されておりますので、そういうものも参考にできるかどうかというところから検討していきたいと考えています。","voiceIndex":76,"id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"一方ではこれは「お泊りデイ」という言い方で理解をいただけるのかと思いますけれども、介護保険外でやられているお泊りデイというものが、ちょっと不透明な運用ということで問題ということも記事には載っているのですけれども、まず初めにこの介護保険外のお泊りデイにつきまして、品川区内の実態、また問題点などにつきまして、どのように認識されているかお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"お泊りデイですけれども、現在区内では４カ所実施しています。それぞれ１０人規模のデイサービスで、泊まっている方は大体３人から５人と把握しております。","voiceIndex":79,"id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"この介護付有料老人ホームの規制緩和については、都市部においては実はもう利用率が非常に高くて、規制緩和してもあまり受入れ枠ができないのではないかというようなことも懸念されているみたいなのですけれども、品川区においてこの規制が緩和されたときに、今８０％の入居者率がないとそういう使い方はできないというのを規制緩和しようという方向らしいですけれども、これが撤廃されたときに。","respondent":"永尾高齢者福祉課長","answer":"ただ、区といたしましては劣悪な環境で何か事故等がありましたらやはり問題ですので、そのあたりはきちんと検査をしていきたいと考えています。","voiceIndex":81,"id":"exchange-034"},{"speaker":"塚本委員","kind":"確認","question":"一応、物理的には器はあるよというお話だったと思います。それとあわせて、これはちょっと直接お答えするのは難しいかもしれませんけれども、ショートステイ以外に介護付有料老人ホームの空きがあった場合、そういったものをほかにも利用できるかもしれないというニーズを何か捉えていらっしゃるところがあるか、その２点についてお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"一時的な入院ですとか、退所して次が入らないという場合、そういう場合は事業者のほうも運営の問題がありますので、ショートステイをできるだけ素早く受けるような態勢を整えているようですので、やはり限りある施設ですので。","voiceIndex":83,"id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に１８５ページ、国保の保険給付費に関しまして少しお伺いをしたいと思うのですが、保険給付費は、高齢化社会ということで年々増加しているという状況ですけれども、この間、私もさまざまな有識者の方とか専門家の講演等を聞いている中で、医療費の抑制というのはなかなか構造的に難しいというような話をよく聞いております。ここをまず確認させていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"平成２９年４月からの保険者の都道府県化ということで、法律はもう決まっておりまして、現在東京都と区市町村の代表でさまざまな形で検討を進めております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。そういうものがあってはいけないと思うので、やはりきちんと保健指導等をしてこれだけ医療費が下がってきたのだと、品川区においてはこれだけ抑制できたのだということがきちんと見えるような、数字のような形で「見える化」と言ってもいいと思うのですけれども、できるような形がこれから必要になってくるのではないかと思うのですけれども、どのようにお考えか、お伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"現在も実は国等からの特別調整交付金というのがあるのですけれども、この中に普通部分と特別部分というのがございまして、特別部分で、国保料の徴収率が高いところ、優良なところと申してよろしいのでしょうか。","voiceIndex":87,"id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"徴収率のことはよくわかるというか、それは見える化が多分できるのと思うのです。問題は、給付のほうの抑制を、やはりしっかり保健指導等に取り組んでいる、糖尿病重症化予防策に取り組んでいる、だからこれだけ医療費が下がったんだよというようなところもこれから見える化していく必要があるのではないかと思っての質問でしたので、その点についてもう一度お伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"失礼いたしました。委員ご指摘のとおり、さまざまな形でこれから検討の中で、意見を反映させていきたいと考えています。","voiceIndex":89,"id":"exchange-038"},{"speaker":"塚本委員","kind":"意見","question":"なかなかこの見える化というのは、やはり現状では技術的にも非常に難しいのかなというところも私も思っているのですけれども、この辺はしっかり検討していただいて、そういった形でこれだけ給付が下がったのだからということが、今度東京都に保険者が移った後でもいろいろな形で交渉の材料に使えるような形にできればと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それぞれの各施設のデータはありますでしょうか。","respondent":"竹田保育課長","answer":"病児保育ですが、平成２４年度は、酒寄医院が８３名、サンタハウスこどもクリニックが１８８名。それから平成２５年度は、酒寄医院が２８名、サンタハウスこどもクリニックが６６３名です。","voiceIndex":95,"id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育の預かり人数が、平成２４年度から平成２５年度にかけて、２７１人から６９１人に急増していることで、１施設、チャイルドサンタのほうが８月から開設したためだと、今、理由をお示しいただいたのですが、私が聞くところによれば、ある病児保育所では定員４名以上では受けてはいけないと言われて、定員いっぱいまで予約をとっても当日のキャンセルが多く、定員割れが日常的だとお聞きしましたが。","respondent":"竹田保育課長","answer":"保護者も早くから預かってくれるところを確保して安心したいという、ちょっと大人とは違った特性がありますので、子どもの特性として一定程度キャンセルが多いというのは仕方ない部分もあるものだと考えております。","voiceIndex":97,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２７１人から６９１人に利用者が急増して、今のお話だと今年度もサンタハウスのほうはすごく多いみたいなのですが、これは潜在的なニーズが強いから種々の対応策を越えて利用者が急増したというような点では、区のお考えはいかがでしょうか。","respondent":"竹田保育課長","answer":"今後の確保方策としましては、実績値を毎年検討しまして、毎年度再検討していきたいと考えております。","voiceIndex":99,"id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育所は、量ではなく数を増やすべきだと思います。「夕方子どもが熱を出した。明日はどうしても仕事を休めないので、病児保育を予約した。」このようなおそらく何百例もあるだろうキャンセル例というのは、立派な病児保育の利用者ではないでしょうか。第１回品川区子ども・子育て会議で述べられた実績とニーズから、ニーズ量を補正し、算出することについての意義をもう一度お尋ねします。","respondent":"竹田保育課長","answer":"今後もキャンセルがあった場合はどういうケースなのかということを十分に分析していきながら、今後のあり方を考えていきたいと考えております。","voiceIndex":101,"id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"意見","question":"現在、保育園・幼稚園ではここ数年、特定の感染症が爆発的に大流行しています。子どもたちの幸せとは何なのか、また品川区子ども・子育て会議でも述べられていた、誰のために何のために一番大事なことなのかという点をしっかりと踏まえて、病児・病後児保育事業の今後のご検討をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-044"},{"speaker":"大倉委員","kind":"質問・要望","question":"オアシスルームですが、先ほど、時間帯として昼が多いとか、利用者数で言えば年間約１万２,５００人の利用だということが出ましたが、これは登録制だと思うので、登録は何カ所もできると思いますが、その登録者数を教えていただきたいのと、この登録者数の推移、増えていると思うのですが、どういったような増え方をしているか、推移について確認したいのと、あと今。","respondent":"竹田保育課長","answer":"平成２４年度の登録者数が２万１,１００人、それから平成２５年度の登録者数が２万７,３８６人ということで、登録者数のほうは増加の傾向です。それから、予約方法ですが、各施設にご利用希望の方が直接電話をしていただいて、ご予約いただいているという状況です。","voiceIndex":105,"id":"exchange-045"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういった中で、予約に関してシステム的に、今こういったお子さんたちを預けようと思っている親御さんなどはスマートフォンなどを持っている方が多いと思うんですが、システムで予約をするような、例えばきゅりあんだったら予約システムで見られるとか、そういったシステムの考えがあれば、何か予約の対策の検討ができないかなと思っているのですが。","respondent":"竹田保育課長","answer":"今後より利用しやすい施設にしていくために、今検討をしています。","voiceIndex":107,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほど品川区子ども・子育て会議の中でも声が上がっているということもあります。次に、福祉団体に対する助成金について伺います。この８カ所について、助成を行っている区の考え、いつぐらいからこうしたところに助成が行われているのか、またほかの団体とはどういった違いがあるのか、この８つの団体になっている決まりですとか、そういった部分があれば教えていただきたいと思います。","respondent":"竹田保育課長、中山障害者福祉課長","answer":"実際に予約したけれども、キャンセルして利用しなかった方、あるいは予約がいっぱいで予約できなかった方等の状況を十分調査・研究しまして、実際のニーズ量を見ながら、今後の方向性は決めていきたいと考えているところです。こちらは開始年度が昭和５３年になっております。これは、主に品川区内の障害者団体の方たちが、勉強会ですとか会報を出していく、あるいは社会参加をする、そういったための支援として始まったものです。","voiceIndex":109,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"オアシスルームなのですが、先ほどちょっとご答弁で利用希望が断られるケースが、推計で３,５３４日あるということで、なかなかやはり利用できない環境があるのだろうということを先ほど確認したのですが、ぜひとも今後も検討を重ねていただいて、利用しやすい環境づくりをしていっていただきたいと、整備をしていっていただきたいと思います。要望で終わります。","respondent":"中山障害者福祉課長、白鳥高齢者いきがい課長","answer":"小さい団体がどんどん増えてきてしまうと、またこの中に入れて助成をしていくというのは難しいとは考えております。これは町会・自治会単位ではありますけれども、高齢者クラブの活動が活発で有意義なものになるように援助をするということで、助成をしているものです。","voiceIndex":112,"id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"障害者計画策定に伴って、いろいろ声を聞いていただけるということで、ぜひともさまざまな、確かに細分化されているところで言うとなかなか増やしていくのは難しいということでしたが、ぜひとも声をしっかり聞いて反映をさせていただければと思います。高齢者クラブですが、これは団体の助成の要件とか条件とかというのがどういったものがあるのか、教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"こちらの基準です。設立の基準というものですけれども、構成される会員の年齢につきましては概ね６０歳以上ということで、会員はこのクラブが円滑に行われる程度の同一地域内に居住をする。それから、高齢者クラブの規模ですけれども、概ね３０人以上という設立要件です。","voiceIndex":115,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういった中では、区としても高齢者クラブをしっかりと、なくなっていただきたくない、減っていってほしくないというところで、しっかり支援していただきたいと思って質問をさせていただきました。最後に何かあったらお願いしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"これまで、高齢者への高齢者クラブの会員増強月間ということを毎年１月から３月、これは上部組織であります東京都老人クラブ連合会では９月ということで実施しておりますけれども、そういう中で会員が１人でも多くなるように努力をしています。","voiceIndex":117,"id":"exchange-050"},{"speaker":"松澤委員","kind":"質問・要望","question":"１項社会福祉費、１目社会福祉総務費、施設整備費助成金のうち、１２７ページ、特別養護老人ホーム建設費助成と、もう一つは１３３ページ、６目社会福祉施設建設費、特別養護老人ホーム等整備費に関連してお聞きしたいと思います。このベッドというのは一体何床あるのかお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、こちらの成果報告書に書いてあるのは６カ所ですけれども、２カ所につきましてはもう助成が終了されているので、決算上載っていないということになります。それで、８カ所の全部のベッド数ですけれども、合計で７５床あります。","voiceIndex":121,"id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"６カ所のうち、もう２カ所は終わっているというお話を伺いました。今、決算書に書いてある６つのうちでも、櫻桃会、これは債務負担行為ということですけれども、２０年ですよね。平成７年からで、もう今年が平成２６年ですから、おそらく来年あたりから順次この６つともなくなっていくと思っています。どういうことでこの施策をやめてしまったのか、その辺もお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、今後やるかどうかというお話になりますけれども、区が資金を出さなくても、現状、地方の特別養護老人ホームで空きが出ている状況でありますので、ご本人のご希望も聞きながら、そういうところでのご利用というのも考えられるということで。","voiceIndex":123,"id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"ただ、こういうことはもうしないのだということですけれども、やはりニーズの多様化の中で、今、新たにこういう建設費を出してくれたならやりたいというところもあるやに聞いているのですけれども、もうこの施策はやらないのだと言い切る形でよろしいのでしょうか、その１点だけ聞いておきます。","respondent":"永尾高齢者福祉課長","answer":"先ほど言った理由もありますし、多くの方がやはり住み慣れた品川区でこのまま過ごしたいという声も聞いておりますので、現在の段階では考えておりません。","voiceIndex":125,"id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。次に行きたいと思います。１３３ページ、杜松特別養護老人ホームが１２月にできますね。来年からの３年間にこれが全部入っているということは、介護保険料の改定、３年間の間に入っているということですから、当然ながら特別養護老人ホームができれば施設費がいろいろかかるということで、これは介護保険料に影響があると思っているんですけれども、これはどれぐらい影響があるのか。","respondent":"永尾高齢者福祉課長","answer":"ユニット型で基本料金だけで計算すると、大体１人当たり７０円程度と試算しています。","voiceIndex":127,"id":"exchange-054"},{"speaker":"松澤委員","kind":"確認","question":"７０円というと、これが２３０床掛ける７０円ということですか。ちょっと確認してください。","respondent":"永尾高齢者福祉課長","answer":"ちょっと説明が不十分で申し訳ありませんでした。今の７０円程度というのは、１００人規模の特別養護老人ホームができたときに、１人当たり７０円程度はね返ってくるということなので、３施設できれば、その３倍ということになります。","voiceIndex":129,"id":"exchange-055"},{"speaker":"松澤委員","kind":"確認","question":"わかりました。介護保険料がどれぐらい上がるかということは、今後の中で明らかになってくるのでしょうから、わかりました。実は本会議の再質問の中で、さらに１つの特別養護老人ホームが検討されているやに答弁があったように聞いているんです。私は、あれ、もう一カ所つくるのかなという考えで聞いていたのですが、これの真意はどうなのでしょうか、確認しておきたいと思います。","respondent":"大串福祉計画課長","answer":"今後、高齢者が増えていくというのはもう動かしがたい事実です。そうした中で、特別養護老人ホームをはじめとするこういった高齢者施設が必要になってくるというのも、区のほうとしては認識をしています。ただ、特別養護老人ホームだけが高齢者施設というわけではございません。","voiceIndex":131,"id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。年寄りなものですから、話を聞いていて、あれ、これはまたもう一つ検討されるのかなと思ってしまいました。やはり本会議答弁というのは一番大事な答弁ですから、４０人いる人たちが理解できるようなしっかりとした答弁をしていただければと思います。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"法人に対する助成金の中の品川総合福祉センター分について、障害者福祉課のほうからご説明いたします。この７００万円につきましては、八潮の特殊性ということで、高温水にかかる経費を一部助成しているものです。三徳会につきまして、平成２４年度は、成幸ホームのナースコール整備について更新があったため、それが約４００万円あるということで、平成２５年度につきましてはその部分が終了いたしましたので、ゼロとなっております。","voiceIndex":133,"id":"exchange-057"},{"speaker":"こんの委員","kind":"確認","question":"よろしくお願いします。すまいるスクールの運営費のほうですけれども、先の一般質問に引き続いて確認も含めてお聞きしたいと思います。そこで、この時間延長も含めての検討を課題の一つとしたという考えに至った経緯、この必要性を感じてくださったと理解をするのですけれども、この点はいかがでしょうか。このことについて２点、まずお伺いしたいと思います。","respondent":"金子子ども未来事業部長","answer":"そういう意味で、この問題に関しましては今後じっくりと検討すべき課題の一つとして位置づけてまいりますというふうにご答弁申し上げたところです。","voiceIndex":137,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"そこで、もう少し具体的にそのご答弁の内容をお聞きしたいのですけれども、今、部長がおっしゃられたいわゆる財政負担、それから保護者の利用負担とか、他区とのバランスとかというご答弁をいただきましたけれども、もう少し詳しくこの点、どういった状況をお考えなのか、今いわゆるどういった状況に置かれているのか、そこら辺をお聞きしたいと思います。","respondent":"金子子ども未来事業部長","answer":"財政負担等々申し上げましたけれども、これにかかる費用、先ほど子育て支援課長も申し上げたとおり約１０億円のお金がかかっております。一方で児童センターという施設も運営しております。","voiceIndex":139,"id":"exchange-059"},{"speaker":"こんの委員","kind":"質問","question":"そこは８５名の定員に対して、約３割が大井第一小学校のお子さんが使われているということをお聞きしました。その中で、併用されているお子さんもいるという状況をお聞きしまして、確かにそうであっても、一方でお金がかかってもやはり使いたいと、預かってほしいというニーズがあるわけです。先ほどの数字もあわせて、少しお考えをお聞きしたいのですけれども、よろしくお願いします。","respondent":"伊崎子育て支援課長、金子子ども未来事業部長","answer":"そのほか勉強会がございまして、その参加費として５００円、あるいは８００円をいただくという仕組みでございまして、年間のご負担額の総額は、先ほど申し上げました総経費の１.３％となっていることが現状です。一方で、やはり公的なサービス、公の役割というのも考えなければいけないと考えています。これら課題が非常に多いものですから、こういうことにつきましてきちんと検討していかなければならないと現在考えているところです。","voiceIndex":141,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"財政負担というところで、課題の検討をしていくということですけれども、心配なのが、そのことによって預けようと思った方が預けられなくなるみたいな、一方でそれもすごく心配ですので、どうかそこら辺も踏まえていただきながら、今後の検討に全力を尽くしていただきたいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第五期介護保険事業計画が平成２４年度から平成２５年度、平成２６年度と、今回が第五期介護保険事業計画の最後の年となりますけれども、来年から第六期介護保険事業計画ということですが、第五期介護保険事業計画では、この介護給付費等準備基金が計画では１８億円余、そこから１０億円を取り崩して８億円余りが残るという計画でいいのか確認したいのと、それと。","respondent":"永尾高齢者福祉課長","answer":"一方で、財政安定化基金のほうの充当残だとか、あと基金の利子等を入れておりますので、プラスマイナスいたしますと、結果的に平成２６年５月末現在で１９億７,７３２万８,３５０円となっています。","voiceIndex":146,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"当初の計画と大分大きくずれていると思うんです。これだけ準備して使わなかったというのはあると思うのですけれども、ここまで大きく計画と差が開く、８億円残るというはずだったのが、見込みで１９億７,０００万円残るというのは、１０億円以上のこの差はどういうふうに説明するのか、これは理由を伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"高齢化率が予想よりも進みが遅かったというところも１つあります。それとあと、介護給付費自体も少し余裕をもって算定していたというところで、その両方のずれが今回のずれとなっているところです。","voiceIndex":148,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それでも１０億円以上が残っているという、高齢化率が進むのが遅かったとか、支出のほうが少なかったという説明では済まないぐらいの額だと私は思うんです。私はここに、一般質問でもさせていただきましたけれども、必要なサービスが行き届いていないのではないかと思うんです。やはりこの実態に合わせた認定とサービス提供をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"認定が軽く出るとか、低いとか、そういうのは非常に主観的なものも加味されてしまいますので、どこまでが客観的かというのは非常に難しい判断になるかと思いますけれども、実際。","voiceIndex":150,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、認識をぜひ変えていただきたいと思うのです。他区から見ても、利用者から見ても、実施している事業所から見ても厳しいのではないかという声が出ているわけですから、この実態をぜひ見ていただいて、認識を変えていただいて、実態に合った認定を進めていただきたいと思います。そして保険料の軽減、利用料の減免ということに使っていただきたいと改めて伺いますけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"品川区の場合は将来に備えてというのを一番大事に考えておりますので、そういうことも計画的にやりながら取り崩しをしています。","voiceIndex":152,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"この品川区は、これからさらに来年度から要支援者のサービスも取り上げていくような大改悪にいち早く進んでいく地域ですので、この認定率の低さ、そしてこの介護給付費等準備基金の膨大な残、これはしっかりと本当に見ていかなくてはいけないと私も思っています。１人当たり平均で４,１１８円の値上げがされました。現時点での滞納者数、短期証の発行数、あと差押えの件数を教えてください。","respondent":"高森国保医療年金課長","answer":"滞納者数ですが、平成２６年５月末現在、９９４名です。短期証のほうの発行につきましては、４４名です。差押え件数については、現在ありません。","voiceIndex":154,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"差押えはこの間ずっとないと伺っていたのですが、ほかの地域では出ているというのも聞きましたので、ちょっと改めて伺わせていただきました。この差をもうちょっと緩やかにできないかということを私たちはずっと求めてきていたのですけれども、いろいろ課長会などでも言っているところですとは言われてきていたのですが、今現在こういった認識、そして課長会等ではどうなっているのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"どうしてもこの金額につきましては、段階的に幾らから幾らまでという区切りをして上げていくものですから、そういうところも制度上あるのかなと思います。","voiceIndex":156,"id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問","question":"以前までは、これを緩やかにしていくことは必要だと思いますというような答弁もいただいていたのですけれども、いろいろ軽減率の境目でもありますので、ここら辺は差がつくのはしようがないのかなと思うのですけれども、これだけの、収入が２万円上がっただけで保険料までもが２万円上がってしまうというところに問題意識はないか、伺います。","respondent":"高森国保医療年金課長","answer":"機会がありましたら、２３区の中で話し合いを持っていきたいと思います。","voiceIndex":158,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ引き続き改善を求めていっていただきたいと思うのです。負担増になる高齢者は全国で８６５万人、加入者の半分以上が負担増になっていくわけです。保険料負担が３倍になる世帯も生まれるなど、２００８年のこの制度開始以来最大の規模の改悪になります。長生きをますますつらくさせるこういった改悪に対して、区としてはどういった認識をお持ちでしょうか。","respondent":"高森国保医療年金課長","answer":"確かに、厚生労働省のほうで保険料軽減の特例措置について、現役世代との格差の是正のために段階的に廃止するという方針を打ち出しまして、今、それが進んでいると認識しています。","voiceIndex":160,"id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問","question":"国から言われたそのままを、今、読まれたと思うんですけれども、それをやはり区として、そういった２３区の中でしっかりと発言していくという課長の認識、今回のこの特例措置が廃止されていくということへの思いや認識をちょっと伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"大変言いにくい話ですけれども、これは制度ですから、制度の中で私たちは仕事を進めていくわけでありまして、そういう意味では必要なことがあれば、当然２３区の中で検討してお話をさしあげるという状況で進めていきたいと思います。","voiceIndex":162,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"意見","question":"この問題だらけの後期高齢者医療制度をやはり廃止して、もとの老人健康保険に戻していくべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-071"},{"speaker":"井上委員","kind":"提案","question":"質問なのですが、在宅療養推進事業、これはいわゆる医療ショートステイですけれども、２０１２年に新規事業として開始されたものなので、１年目と２年目の実績をお伺いします。どんな課題があるのかということをお伺いしたいと思います。公衆衛生の観点から、生活福祉課、高齢者福祉課、健康課にとどまらない全庁的な検討が必要かと思いますが、見解を伺います。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長、伊東生活福祉課長","answer":"医療ショートステイの実績ですが、平成２４年度は利用人数が１１人で、利用日数が７１日、平成２５年度は１１人で７７日。１点といたしましては、今、ひとり暮らしの方を対象としているのですが、例えば、老障介護の方が、今後親御さんが介護ができなくなったときに。入浴券についてですけれども、平成２５年度の実績としましては、延べで３,２０９枚、人数で考えれば１,６００人ほどということで。","voiceIndex":166,"id":"exchange-072"},{"speaker":"井上委員","kind":"提案","question":"次年度に向けての見解をお願いします。それで、東京都ではＮＩＣＵ等退院支援検討部会というのが始まって、この中で在宅療養児一時受入支援事業の促進ということで、同じようなことが提案をされていると思うので、ぜひ子どものほう、児童のニーズ的にもこういった事業が必要だと思っているのですが、見解はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"アウトリーチ型というご質問もございました。このサポート２４の事業の中で、諸手続きの同行支援であったり、あるいは電話だけのご相談では不安だという方については、こちらのほうは職員が出向いているところです。医療ショートステイというお尋ねです。","voiceIndex":170,"id":"exchange-073"},{"speaker":"渡部委員","kind":"質問・要望","question":"民生委員のほうなのですけれども、平成２５年はちょうど３年任期の交代のときだったと思います。民生委員の定数というのがあるというのは前の質問でもお伺いしているのですけれども、この改選期に合わせて、民生委員の増員等が図られたのかどうか。この辺、例えばいろいろ時代が変わっていく中で、ここ数年の動きみたいなのがわかれば教えていただきたい。では、まず先に民生委員のほうをお願いします。","respondent":"永尾高齢者福祉課長","answer":"それで、あと定年ですけれども、７３歳が定年になっております。それで、定年の考え方については、国のほうの考え方にのっとっておりまして区が独自で決めることができません。そこで、区のほうといたしましては、国のほうに区から要望を出したところです。","voiceIndex":173,"id":"exchange-074"},{"speaker":"渡部委員","kind":"質問・要望","question":"よくわかりました。そして、定年は今お話はわかりました。やはり本当に優秀な方というか、本当に一生懸命やってくださる方は、その後でもまだ私は活躍いただけると思いますので、これは要望を続けていただきたいということで、仕事の軽減ができるかどうかというところをひとつお願いします。","respondent":"永尾高齢者福祉課長","answer":"地域の中で活動するにあたって、やはり民生委員が１人で活動するというのはなかなか難しいので、町会でも見守りをやっておりますので、これからはそういうところとうまくできるように、区のほうでもいろいろな支援をしていきたいと考えているところです。","voiceIndex":175,"id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"今の社会状況の中で、ややもするとダウン症のお子さんが生まれる確率というのはちょっと上がり傾向にあるのかなというところもある中で、先ほど来、障害はいろいろな種類があってということですが、もう実は生まれてきて大半がすぐわかるような形の症状だという中で、相談体制、療育体制のご相談があると思いますが、何か区でお考えがあるようでしたら、教えてください。","respondent":"中山障害者福祉課長","answer":"そうした上で、その後、必要なお子さんに応じて、ＰＴ、ＯＴの専門相談をポイントごとに入れていく、あるいは親御さん同士の集まりの場である、今、戸越ルームのほうに設けています親子ひろば、そういったものを活用する中で。","voiceIndex":177,"id":"exchange-076"},{"speaker":"渡部委員","kind":"確認","question":"よろしくお願いします。早期療育、家庭で本当に早い段階からできることが相当あるようにも確認はいたしました。ですので、その辺で何か相談業務の中でサポートできるようなところがあれば、しっかりサポートをお願いしたいと思います。１３２ページのシルバーセンターはもう時間がないのでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-077"},{"speaker":"藤原委員","kind":"確認","question":"最後に１８５ページ、国保の徴収なのですけれども、今の課長が前に税務課長のときには、徴収が２３区で１番になったということで、その手腕をこの新しい課に来て、国保の徴収、もうこれは一番大事な権利と義務の義務の部分ですから、率とか数字とかは要らないです、どういうつもりで徴収をしていくのかということをお伺いします。","respondent":"白鳥高齢者いきがい課長、大串福祉計画課長、伊崎子育て支援課長、今井制度改革・待機児童対策担当課長、高森国保医療年金課長","answer":"午前中に申し上げました高齢者クラブ対策費の中で、やはり今後、人口の高齢化が進む中で、地域のそういった高齢者の方々の活動を支える体制。こういった形でさまざまな状態に合わせて、終の住みかとしてお住まいいただけるような形での施設の整備を計画的に行っているところです。品川区としましても、児童相談所が移管された際には、児童相談所が行っている虐待対応のみならず、さまざまな児童相談所の事務がありますので。","voiceIndex":181,"id":"exchange-078"},{"speaker":"藤原委員","kind":"質問","question":"徴収率、よろしくお願いいたします。１つだけもう１回再質問しますが、高齢者生きがい対策で、多分、介護予防とか、人生８０年という形で生き方だと思うのですけれども、ここでそろそろといいますか、公がどこまでこれに関してやっていくかという線引きをしていかないといけないのではないかと私は思っているのですけれども、その辺について、担当の課長としてはどういうご意見を持っていらっしゃいますか。","respondent":"白鳥高齢者いきがい課長","answer":"委員ご指摘の線引きという問題ですけれども、区が行うべきか、あるいは自主的に地域の中で行うべきかというところ、非常に難しいところがあろうかと思います。今後の状況を見極めながら、適正に対応してまいりたいというふうに思っております。","voiceIndex":187,"id":"exchange-079"},{"speaker":"山元委員","kind":"質問・要望","question":"２年間、授業料等々で１８０万円使うような形になりますけれども、区内で３年間働くことにより、１８０万円を返済しないでいいというふうに聞いておりますけれども、実際にこれを活用している方、人数はどのぐらいいらっしゃるのか教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"貸付の内訳ですけれども、現在、在学中の方のうち貸付をしている方は３５人中２８人、平成２６年度、今年度は３５人中３１人ということで、在学中の方はほとんど貸付を申請しています。","voiceIndex":190,"id":"exchange-080"},{"speaker":"山元委員","kind":"質問・要望","question":"それとも自分たちで選択ができるのか、その辺を教えていただきたいと思います。それから、入学資格ということでいろいろあると思います。生徒を見ても、お若い方もいらっしゃれば、３０代の方もいらっしゃると思うのですけれども、ここで１つ聞きたいのは、日本に在住の外国の方が入りたいというふうになった場合は、どうなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そうしないと、なかなか定着に結びつかないので、アドバイスもしながら、そういうふうに就職に結びつけているところです。外国人の場合ですけれども、この学校で２年間勉強しなければいけないので、在留期間が２年以上ということで制限をしています。","voiceIndex":192,"id":"exchange-081"},{"speaker":"山元委員","kind":"質問・要望","question":"知り合いで外国の方がいらっしゃって、勉強したいという方もおりますので、今の課長のお話を伝えたいと思います。どうかよろしくお願いします。では、次に、要約筆記者派遣のことでお伺いしたいと思います。決算書には計上されているのですけれども、予算のところには計上されていないのです。これはどういうことなのか、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"予算書と決算書の表記の違いです。予算書のほうでは、地域活動支援センターの意思疎通支援のところでまとめられているということが挙げられると思います。","voiceIndex":194,"id":"exchange-082"},{"speaker":"山元委員","kind":"質問・要望","question":"ここに計上されているということは、この要約筆記者を活用しているということだと思うのですけれども、現実、品川区に要約筆記を活用されている方はどのくらいいらっしゃるのかということと、それから要約筆記というのはどういうことをするのかを改めて教えていただきたい。","respondent":"中山障害者福祉課長","answer":"それで、実利用人数がちょっとわからないのですが、延べで、平成２５年度は要約筆記を派遣した件数は３６件ということになっております。","voiceIndex":196,"id":"exchange-083"},{"speaker":"山元委員","kind":"質問","question":"品川区でも週２回ですか、手話通訳者の窓口相談、また、派遣を行っているということであります。そうなってくると、相手に何か伝えるというと、今おっしゃった筆記とかということになるのですけれども、現実、今、週２回やっているのは手話ということであると、途中からお耳が聞こえない方たちが来る場合、区はどういうふうな対応をしていこうと思っていらっしゃいますか。","respondent":"中山障害者福祉課長","answer":"手話というのはやはり特殊な能力が必要ですので、我々職員全員が手話をできるわけではありませんが、当然、仕事の上で必要なことを相手にわかりやすく伝える筆記ということは全職員やっておりますので、そういったことで対応しています。","voiceIndex":198,"id":"exchange-084"},{"speaker":"山元委員","kind":"質問・要望","question":"職員の方がそうやって筆記してくださるというのは大変力強いです。ここで少しお聞きしたいのは、要約筆記の派遣をされているということなのですが、報酬というのでしょうか、どのぐらいなのかということと、それから手話通訳と同じように、要約筆記なさる方がおいでかと思いますけれども、品川区では何人ぐらいの方がいらっしゃるのか教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"要約筆記と手話通訳者の金額というのは同様になっております。それで、２時間２,０００円、３０分ごとに追加で５００円ということになっております。","voiceIndex":200,"id":"exchange-085"},{"speaker":"山元委員","kind":"質問","question":"これは、ごめんなさい、しつこくお聞きしてしまうのですけれども、手話も要約筆記の方も同額の報酬になるのでしょうか。","respondent":"中山障害者福祉課長","answer":"失礼いたしました。今年度、実は要綱を改正いたしました。手話につきましては、１時間未満まで３,０００円、以降、３０分延長につき１,０００円ということにしています。","voiceIndex":202,"id":"exchange-086"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり健常者と違うので、皆様にぜひわかりやすいお話をしていただきたいと思います。シルバーセンターはご高齢の方たちが大変楽しみにしている場所であり、お風呂があったりすれば、そこでお風呂を使ってということでありますけれども、ここで少し疑問に思うのが、八潮団地の中にシルバーセンターがないのですけれども、何か理由といいますか、どうしてなのかということなのですが。","respondent":"白鳥高齢者いきがい課長","answer":"当時、八潮地域センターの設置と、それから、さまざまな文化施設、図書館等、そのようなことからしまして、また、八潮地域センター内に敬老室があります。こういったところで総合的にお使いになられるという意味合いの中で、特段そこで設置をしていないです。","voiceIndex":204,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"１３８ページの延長夜間保育、１４０ページのすまいるスクールについてお聞きします。延長夜間保育、就学前に子どもたちが大きくなっていくときの親御さんの利用の状況の変化がどうなっているのか、状況をまずお聞きしたいと思います。","respondent":"竹田保育課長","answer":"延長夜間保育の最近の傾向ですが、７時半までのご利用のほうは若干増えているのですけれども、それ以降の８時半あるいは１０時までのご利用のほうは減っている状況です。","voiceIndex":208,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"やはり保護者の考え方として、私が認識しているのは、小学校に上がるために、例えば１０時まで預けていたのを徐々に子どもたちの環境に合わせるような形で、自分たちも、親御さんのほうも考えていくというような傾向があるのだ、そこに午睡等もなくすことによって早く寝るようになったということで、準備期間が、保育園の中で就学に対しての親たちの準備もかなり進んできているのではないかと思いますが。","respondent":"竹田保育課長","answer":"委員おっしゃられるとおり、５歳児におきましては、午睡を今廃止しています。それは、あくまでも小学校への滑らかな接続を目指しているのが主な点です。延長夜間保育の使い方については、それぞれのご家庭のご事情に合わせて使っていただいているところです。","voiceIndex":210,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"延長夜間保育は、やはり就労の体系によって必要なことはありますので、これは十分にやっていただきたいところがありますが、ただ可能な限り、子どもたちの環境を整えていくのだというのは、ほぼ親御さんたちの傾向ではなかろうかと思っているのです。そこで、そういう形で捉えながら延長夜間保育の事業の展開をぜひしていただきたいということ。","respondent":"伊崎子育て支援課長","answer":"来年の４月から、子ども・子育て支援新制度が施行される予定ということに伴いまして、先般、放課後児童健全育成事業の設備および運営の基準に関する条例を提案させていただき、可決、公布したところです。","voiceIndex":212,"id":"exchange-090"},{"speaker":"西本委員","kind":"確認","question":"財源のところを確認しますが、新制度になったときにおいて、補助金、助成金等々、そういうものはあるのか。現状として何か補助が出てくるのか、出てこないのか、その辺はいかがでしょうか。","respondent":"伊崎子育て支援課長","answer":"放課後子ども教室につきましては、文部科学省の補助金として今年も出ておりますが、来年もそれに引き続き出ると見込んでおります。","voiceIndex":214,"id":"exchange-091"},{"speaker":"西本委員","kind":"意見","question":"今のところ、現状維持した形での予算立てになってくるのかと思うのですけれども、先ほどから、朝早く延長しろとか、あとそれから、午後６時までですけれども、午後７時まで延ばしてほしいという意見があります。早朝のほうです。その実態をどう考えているのか、必要性をどこまで考えているのか。それと、午後６時から午後７時ということですが、当然７時に延長すれば、今はお迎えはありません。","respondent":"伊崎子育て支援課長","answer":"ですので、今おっしゃられた件に関しましても、今後検討していく課題の中の１つと考えております。","voiceIndex":216,"id":"exchange-092"},{"speaker":"西本委員","kind":"意見","question":"ニーズはあるのです。長く保育園をやってほしい、長くすまいるスクールをやってほしい、ニーズはあります。しかしながら、ニーズがあるからといって、安易に広げてしまうと、親のやるべきことを奪ってしまうということもあるので、そこの品川区としてしなければならないこと、このニーズをどのように捉えて政策を考えていかれようとしているのか、そこをお答えください。","respondent":"伊崎子育て支援課長","answer":"今回のこの課題につきましても、子どもの最善の利益ということを考えつつ、親御さんの不安感への対応ということも想定しながら、バランスをとって政策のほうは検討していくものと考えております。","voiceIndex":218,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"何がいいのかということだと思うのです。ニーズはたくさんあります。品川区でやらなければいけないこと、親たちが責任をもってやらなければいけないことを、しっかりと根底に据えて事業の展開をぜひしていただきたい。それを踏まえて、全体的にどういう子育て、犯罪から守るということも含めて展開をしていくかということをじっくり考えて、ニーズ調査を分析し、展開をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-094"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書の１３８ページぷりすくーる西五反田、２２０ページ介護保険サービスについて伺います。その中で、検証という点で見た場合に、まず一番の売りといいますか特徴である公設民営の利点、そして当初、導入時の目標といいますか、目標設定、そして今１０年が経ち、達成度、それによる直接効果あるいは波及効果、この点をまず伺いたいと思います。","respondent":"竹田保育課長","answer":"評価としましては、第三者評価でも高い評価を得ているところです。そこで培った経験をもとに、各保育園にいい影響を及ぼした部分も多々あると思います。今後もぷりすくーるはチャレンジ的な側面も含めまして、高い目標を目指して一歩一歩進めていきたいと考えております。","voiceIndex":222,"id":"exchange-095"},{"speaker":"渡辺委員","kind":"質問","question":"年度ごともそうです。その中で、評価シートはまた後で伺うのですが、現在の年度ごとの評価のところで各論のところで伺います。これがさまざまな、あるいは待遇の問題等で、施設から、あるいは区外へ流出というのは、これはその方への評価ですから、あって然るべきかと思いますが、ここで１つ知恵が必要だと思います。その点でこの２点、伺わせてください。","respondent":"竹田保育課長","answer":"特に保育という人を扱うものについては、特段に人材の確保・育成が重要なものだと考えておりますので、今後も十分研修して、また、公設民営という公務員を採用するというのとはまた違った自由な採用ができる側面もあろうかと思いますので。","voiceIndex":224,"id":"exchange-096"},{"speaker":"渡辺委員","kind":"質問","question":"ただ、その中で算定方法のところ、あるいは管理者の裁量もありますが、その中で教育への、人への投資という項目は、ことさらこれからの時代、都市部では必要性が増していると思いますが、この点を伺いたいと思います。その中で厳選して厳選して実施していると。ただ、どうしても予算も伴いますので、施設の特色である事業が増加したとシートにもあるように、ここはいろいろなチャレンジがあって然るべき。","respondent":"竹田保育課長","answer":"独自施設としてのチャレンジ的、先進的な取組みですが、公設民営といいましても、やはり役所が設定している公設という意味合いもありますので、他の保育園とのバランスも十分加味しながら、適切な運営に努めてまいりたいと考えています。","voiceIndex":226,"id":"exchange-097"},{"speaker":"渡辺委員","kind":"質問","question":"ここは各論はもう当然、当事者間の協議になるかと思いますが、他とのバランスということであればこそ、職員の処遇、待遇改善、ここは十分期待が含まれるところかと思いますし、もう１点、最後に聞かせてください。少し総花的になってしまうのですが、その辺の今までのノウハウの蓄積等をどう生かすかという点で、総論で伺えればと思います。特に介護予防サービスのところの要支援１・２のところです。","respondent":"竹田保育課長、永尾高齢者福祉課長","answer":"それぞれの利点を生かしながら説明をしてまいる所存ですが、品川区の独自乳幼児施設という意味合いもありますので、この利点を十分生かして独自性を発揮してまいりたいと考えております。それであと、猶予期間のお話ですけれども、国といたしましては、２年間の猶予というふうに定められておりまして、品川区は、来年の平成２７年４月に移行する予定で、今動いているところです。","voiceIndex":228,"id":"exchange-098"},{"speaker":"渡辺委員","kind":"質問","question":"最後に、この要支援のところの部分、ここは今日午前からの質疑も多々ありました同じく認知症に関連してくることだと思っています。早期発見・早期対応が今や常識となっている認知症予防についても、大きく関わりのあるところだと思います。特に初期、軽度の人たちのサービスが減少することなく維持あるいは拡充できるようなものが当然ながら望ましいと思いますが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区といたしましても、早期発見・早期対応については、昨年９月から開始しておりまして、それをさらに充実させるとともに、ご利用者へのサービスが低下にならないように努力していきたいというふうに思っております。","voiceIndex":231,"id":"exchange-099"},{"speaker":"南委員","kind":"質問・要望","question":"私は、特養ホームの増設を求める質問をします。１０月２１日付の都政新報に、区長が、高齢者福祉施策は特養３カ所、老健１カ所の整備を行うとともに、さらなる土地確保を進めていく、こういうふうに発言しておられます。先だっての本会議で我が党議員の質問に、４カ所目が欲しいと適地を検討している、こういう答弁をされました。伺いたいと思います。","respondent":"大串福祉計画課長","answer":"そうした中で、施設サービスとして特養、グループホーム、あるいは小規模多機能型居宅介護、こういったさまざまな施設を活用し、なおかつ認知症の予防事業ですとかでソフト的な展開も含めながら、こういった課題に対して重層的、また複合的に対応していく。","voiceIndex":234,"id":"exchange-100"},{"speaker":"南委員","kind":"質問","question":"私が聞いているのは、区がつくったこの計画で、１０年後には１,６３２人が入所すると推計しているのです。これに今の数しかつくらないということになれば、とても対応できないではないですか。だから何カ所つくる計画なのかと聞いているのですから、きちんと答弁してください。","respondent":"大串福祉計画課長","answer":"先ほどもご答弁しましたように、そういった中で検討していくものです。何カ所といったところで具体的な数字を今この場でお話しするということはできかねます。","voiceIndex":236,"id":"exchange-101"},{"speaker":"南委員","kind":"質問・要望","question":"あまりにも無責任なこの推計ではありませんか。その認識はないのかどうかを伺いたいと思います。それで、本会議では、４カ所目が欲しいということで適地を探している、こういうふうに答弁されました。どういうふうに具体的な検討をされているのかを、わかる範囲でいいですから示していただきたいと思います。建設時期、場所、そして規模、こういう点で教えてください。","respondent":"大串福祉計画課長","answer":"繰り返しのご答弁になりますけれども、高齢者の数が増えていく、そういった中で、ある程度、こういった形での施設サービスが必要だということも認識をしております。そうした中で、高齢者施設のあり方ですとか、そういったものについての検討は行っているといったところです。","voiceIndex":238,"id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"そうしたら、部長が答弁されている、適地を検討しているという答弁でした。検討しているというのであれば、それはどんな内容で、適地はどこなのか、どういう内容での検討なのかを教えてくれとさっきから言っているのです。よろしくお願いします。","respondent":"大串福祉計画課長","answer":"施設の整備といったところの検討の中で、当然、場所、これが必要になってまいります。","voiceIndex":240,"id":"exchange-103"},{"speaker":"南委員","kind":"質問","question":"私はそれでは、本会議では適当に言っていたというふうにしか理解できないですね、今のような答弁では。４カ所目が欲しいということで適地を検討しているというのであれば、一定程度の検討をした上での答弁だと思うわけです、期待をするわけです。したがって、それはどこなのかと聞いているのですから、どういう内容で検討したのか、そこを教えてくれとさっきから言っているのです。お願いします。","respondent":"榎本健康福祉事業部長","answer":"本会議のとき答弁したのは、まず大前提としては、これからの利用者ニーズの変化というのはありますし、それから介護保険料の影響もあるということで、総合的な判断をしていくとともに、適地の選定についても検討を行ってまいりますということです。","voiceIndex":242,"id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"品川区内にはたくさんの土地が東京ドーム１個以上あるということは、かねてから言ってまいりました。そして、国有地も特養をつくれるだけの規模がある、そういう一画地があるということも当然ご存じのことと思います。あるいは、区営住宅の建替え計画がありますが、４カ所ありますけれども、そういう部分も含めて検討をされたのかどうか。そこを教えてください。","respondent":"大串福祉計画課長","answer":"適地といったところで言えば、今挙げていただいたところ、あるいは民間の土地を含めて、いろいろな土地の形が出てこようかと思います。そういった中でどこが使えるか使えないかといったところでは、俎上には上がってくるものです。","voiceIndex":244,"id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"俎上には上がってくるということだというふうにおっしゃったけれども、検討したのかどうかを聞いているので、繰り返しばかりになってしまっているので、適切に私の趣旨を酌んでいただいて、適切な答弁をしていただきたいと思います。","respondent":"大串福祉計画課長","answer":"繰り返しの答弁になって誠に申し訳ございませんが、一般的な意味での検討といった俎上の中にはさまざまな土地が上がってくる、こういったものです。","voiceIndex":246,"id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"私は早急に検討を具体化するべきだということを強く申し入れたいと思います。とりわけ４カ所目、５カ所目、この規模で言うと何カ所必要になるのでしょうか、そういう具体的な数字も明らかにして検討をする、そして計画を区民に公表する、それをはっきり一刻も早くやっていただきたいということをお願いしておきたいと思います。シルバーセンターの件について伺いたいと思います。お風呂もない。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者クラブ以外の自主グループも誕生しているということも承知しておりますし、さまざまな施設の中で、あるいはこみゅにてぃぷらざのほうをお使いになっていただくですとか、そういった利用形態がいろいろ考えられるのではないかということで思っております。","voiceIndex":248,"id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"そういう変化の大きな地域なので、ほかの地域と同じような機能のあるシルバーセンターをやっぱりしっかり位置づけてつくっていただきたいと思っているのです。そういう認識があるのかということを聞いたのですけれども、具体的に今後どうするかというところを教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"繰り返しの答弁になりますが、やはりこの八潮地区の中でシルバーセンター同様の機能の備わったこういった施設をつくるという考えは全くございません。","voiceIndex":250,"id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"１４０ページの品川児童学園についてお聞きをいたします。その中で平成２５年度は、保育所等訪問支援と土曜日療育が新規に事業開始されましたけれども、その執行状況、全体も含めて、特に土曜日療育も含めて、事業の成果等について一言お答えをいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"平成２５年度から比較しまして、平成２６年度には、保育所等訪問支援、それから、昨年度の途中から土曜併用グループをつくってまいりました。実績といたしましては、相談、通園、Ｃｏｍｐａｓｓ（コンパス）、全て昨年度よりかなり上回った数字になっております。","voiceIndex":254,"id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"４点お聞きいたしますので、またその後、重ねての再質問をしますので、よろしくお願いします。これの年齢別の人数を教えていただきたいと思います。それから、同じく、平成２５年度までは０歳から５歳が母子通園の対象年齢になっておりましたけれども、平成２６年度から１歳から３歳になったというふうに事務事業概要を見ながら感じたのですけれども、これに理由があれば教えてください。","respondent":"中山障害者福祉課長","answer":"母子通園の年齢が、昨年度は０歳から５歳になっていたが、今年は１歳から３歳という考え方ですが、母子通園はあくまで歩けないお子さんを対象としております。","voiceIndex":256,"id":"exchange-110"},{"speaker":"若林委員","kind":"提案","question":"重ねての質問です。情報提供について、提案も含めてお願いしたいと思います。こういうところのいわゆるリスト化というのは１つ可能なのかどうかということを教えていただきたいのと、また、療育の流れについての丁寧な、まずは書面化、当然、口頭ではお伝えするわけですが、書面にしてのお知らせ、そういうものが必要なのかというふうに思いましたので、この２つ。","respondent":"中山障害者福祉課長","answer":"相談はどこにしたらいいのか、療育機関でどういうところがあるのか、また学校はどういうふうになっていくのか、そういった通しでの支援をするためには情報のツールが必要だと考えました。","voiceIndex":258,"id":"exchange-111"},{"speaker":"大沢委員","kind":"質問","question":"１２６ページのボランティアセンター、それと１４１ページの生活保護費を伺います。その前に今までのやりとりの中の質問なのですけれども、先ほど認知症の高齢者の方の居場所云々という話がありました。冒頭、私が話したように、話題であったり、課題であったり、問題にするわけですから、これは大事なところだと思うのですけれども、そこのところをどのようにお考えになっていらっしゃるのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"現在、そういう定義で言いますと、品川区で行方不明になって品川区の施設に入っているという方はいらっしゃいません。","voiceIndex":261,"id":"exchange-112"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはりいなくなった方の当人たちの身になれば、本当に心配なわけでありまして、そこのところの、これは表現の話で、実際はやっていらっしゃると思うのですけれども、そこのところの心意気というか、思い方、考え方をもう１回教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そこについては、今のところ把握が難しいところがございまして、一時的にわからないのか、それともこの後もわからないのか、その時点によるというところで把握がし切れていないのですけれども、ただ、そういうこと以上に。","voiceIndex":263,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に、生活保護費、１４１ページのほうを先に聞かせていただきますけれども、４月以降から今までの間に１回、不正受給の件なのですが、５３件の３,７００万円ということで、行政側から、役所の側からそういう報告をいただきましたけれども、その後、この５３件、３,７００万円、不正受給に関してどのような取組みが行われて、不正受給が減らされたのか、それとも増えたのか。","respondent":"伊東生活福祉課長","answer":"平成２５年度ですけれども、平成２５年度末で４６件、３,７７０万円ということで、それは委員ご指摘のとおりです。","voiceIndex":265,"id":"exchange-114"},{"speaker":"大沢委員","kind":"意見","question":"今そこで７件数字が違う。私は５３件の３,７００万円ということで、この今の４６件というのは、私も３,７００万円と書いたのですけれども、５３件の３,７００万円というのは、今、課長おっしゃったのは４６件、これは７件減っているというふうに捉えていいのですね。","respondent":"伊東生活福祉課長","answer":"失礼いたしました。５３件というのは調定額ということで、実際に平成２５年度に入ってきたものが３,７７７万円余です。","voiceIndex":267,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"おそらく３,７００万円というのは、僕が３,７７０万円は概ね３,７００万円だなと書いたのだと思いますけれども、件数だけはやはり一番キーポイントで、減っているか、増えているか、これ、減らすことにやはり皆様、ご努力されているわけですから、やはり数字は一番目に見えてわかりやすい指標になるわけですから、そこのところはどうなったのでしょうかということで、もう１回お答えください。","respondent":"伊東生活福祉課長","answer":"いろいろと取り組んでいるところですけれども、すみません、５３件中７件につきましては返還されたということでの数字でございました。大変失礼いたしました。","voiceIndex":269,"id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、また新しい数字が出てきて、これ、４,６７０万円という、まあ、いいです。数字については大まかなことで、それはお任せします。ただ、正確を期すということは大事なことだと思いますので、そこのところは、これ、３,７００万円と４,６００万円では１,０００万円近く違うのです。いいですか。では、もう１回、すみませんが、そこのところ、何かありましたら、ご答弁お願いします。","respondent":"伊東生活福祉課長","answer":"先ほどの数字、返還額を含めない金額としての数字と、返還額を引いた数字ということで伝えてしまいましたので、その辺で混乱させてしまって申し訳ございません。","voiceIndex":271,"id":"exchange-117"},{"speaker":"大沢委員","kind":"質問・要望","question":"返還額を含める、含めないにしても、これ、どうしてもそろばんが合わない数字、数字のやりとりをするつもりはないですけれども、政策的にしっかりした話をしたいのですけれども、やはり正確を期すということは大事だと思いまして、私たちも、耳なり目を皿のようにあるいは吸盤のようにしっかり聞いているわけですので、これ、３,７７０万円と４,６７０万円は、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-118"},{"speaker":"あべ委員","kind":"確認","question":"幾つかお伺いしますが、どこに入るのか、１２６ページの社会福祉費、先日ふくしまつりが中小企業センターで行われましたけれども、その中で行われていた風船バレーボールについて伺いたい。それから１２９ページ、先ほどちょっとお話に出ていました高齢者の安否確認といいますか、徘徊高齢者の探索システム等についてお伺いしたいと思います。それから、１３６ページ、保育ならびに病児保育について。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"今後は、軽スポーツとしてどのように取り入れていけるかについては、スポーツ協会とも相談をしてまいりたいと考えています。それから、にじのひろばのお尋ねです。今年度から社会福祉協議会に運営者が変更になりました。それで、徘徊をする方というのは、なかなか捉えづらいところがございまして、一般的に２以上の方は徘徊をする可能性があるというふうに捉えているところです。","voiceIndex":277,"id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは款が違いますので、お答えができる方がいらっしゃればで構いません。特にお仕事をされていない方が急に使うときに少し使いづらいかなと考えていますし、その辺りのニーズというのは、今後どのような形で拾っていくかについてお考えを教えてください。今、システムの利用が９人でということ、これはやはり非常に少ないと思うのです。これについてお考えを教えてください。","respondent":"永尾高齢者福祉課長、伊崎子育て支援課長、中山障害者福祉課長","answer":"区でもやはり今までのＧＰＳの機械だと、普及したくてもなかなか普及できないという実態がありますので。風船バレーボールについて、申し訳ございません、私はそのものを見たことがございませんが、子どもたちが遊べる競技であるということであれば。確かに４月以降、一部の保護者の方から、にじのひろばが使いにくくなったというお声は区のほうにも届いております。","voiceIndex":280,"id":"exchange-120"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、例えば訪問型も併用するような形で一部料金をバウチャーなどで援助するようなことも考えてもいいのではないかと思いますが、それに対する区の見解をお伺いしたいと思います。もう１つ、保育園なのですが、待機児童がこれだけ多くて、保育園を増やしてほしい一方で、今、近隣から騒音のクレームですとか、あるいは設置そのものへの反対運動も見られるという、そういう非常に厳しい現状もあります。","respondent":"竹田保育課長","answer":"訪問型の場合、長所としましては、お子さんの慣れ親しんだご家庭でお預かりできるという長所がある一方で、仮に１人で保育した場合、１人で全てまかない切れるかというような問題等もありますので、それぞれの長所、短所を踏まえて研究していきたいと考えております。","voiceIndex":284,"id":"exchange-121"},{"speaker":"あべ委員","kind":"質問","question":"病児保育訪問型、私もいい点ばかりだとは思ってはいないのですが、やはり数、あるいは実際に使えるということも大切なことだと思いますので、研究をしていただければと思います。それから、騒音の話、確かに努力しているのはわかります。そのときの区の基本的な態度をもう一度しっかりお伺いしたいと思います。お願いします。","respondent":"竹田保育課長","answer":"ご指摘のとおり、ごく少ない園で苦情をいただいているという現実も一方ではあります。ただ、あらゆる年代が共存するまちを目指して、当事者同士の話し合いが何よりも大切だと考えていますので、接点を多く持ってご理解をいただくよう努めてまいりたいと考えております。","voiceIndex":286,"id":"exchange-122"},{"speaker":"あべ委員","kind":"質問・要望","question":"と同時に、保育園の反対運動などもありますけれども、あまりこういったことが激しくなったり、それが全国的に品川区ではこういうこともあるらしいということになると、他の法人の品川区への進出意欲までそいでしまうのではないかという危惧までするような状況に今なっているのですが、保育園の増設に対する区の態度をもう一度確認させていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長、伊東生活福祉課長","answer":"こういう観点からは、反対する方のご不安というのは十分払拭するように、区としても十分説明に努めるとともに、事業者が区民説明会等を開催しておりますので、そちらには適宜情報を提供していきたいというふうに思っております。従来からケースワーカーがいろいろとその辺の支援をしていますけれども、それを補強、強化するということでの実施です。","voiceIndex":288,"id":"exchange-123"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。１２７ページの社会福祉法人許認可・指導監査事務、１３１ページの障害者就労訓練事業についてお伺いします。順序は逆になりますが、先に１３１ページのほうの障害者就労訓練事業についてお伺いします。こちらの事業について、ご説明をお願いいたします。","respondent":"中山障害者福祉課長","answer":"障害者就労訓練事業ですが、こちらは障害者の方が民間事業所への就労機会を拡大するための相談と訓練を一体的にやっているものです。こちらを運営しているのは、社会福祉法人げんきになります。","voiceIndex":292,"id":"exchange-124"},{"speaker":"高橋委員","kind":"質問","question":"これは障害者の就労支援センターという形で運営されているものの事業で、登録３４３人、２,１６９万円余というものだと思います。障害者計画、そして障害福祉計画というものが出されまして、１２月からパブリックコメントだというふうに伺っております。その中で、一般就労に向けて就労支援の強化が中で謳われております。今お話しあったげんきのほうの１年間の実績と、それに対する評価をお願いいたします。","respondent":"中山障害者福祉課長","answer":"ここでは、生活の相談、それから就労してからの支援を一体的にやっているところです。２３件という数字をどう見るかですが、国のほうで求めている数値よりも実績としては高い数値ということになっております。","voiceIndex":294,"id":"exchange-125"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、この登録の３４３人と、あと、利用ということになるのでしょうか、その数字から見て、この２３件という数字の評価はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"登録者３４２人の方に対しまして、延べ相談支援といたしましては１,６６７件の相談を実施しております。その中で別個、企業からの相談も受けていまして、企業からは２００件の相談を受けています。","voiceIndex":296,"id":"exchange-126"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今、一般就労のお話、移行のお話が出たのですが、移行された方はどれぐらいいらっしゃったのですか。今、２３人というのは、企業にそのまま卒業して入られた方という、一般就労移行の方は何人ぐらいいらっしゃいますか。","respondent":"中山障害者福祉課長","answer":"げんきの就労移行支援のほうは、定員が２０名ということでやっております。その中の一般就労をされた方の数ですが、就労移行支援はげんきだけではございませんで、実は他区の就労移行支援ですとか、そういったところも使っているところです。","voiceIndex":298,"id":"exchange-127"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、障害福祉計画の中の平成２５年の実績が１７件と書いてあったのは、今お話にあった国の基準を超えてそれだけ一般就労に移行できたという数字でよろしいでしょうか。その一方で、区内の特別支援学級、それから都立の特別支援学校、それから企業の障害への認識というか、理解の推進、そしてあとハローワークなどとの連携、その３点についてはどのようにお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"ただし、就労継続Ｂ型の作業所に入る方につきましては、一度この就労支援センターの実習を受けていただいて適性を見ていただく、そういったことで、げんき品川は特別支援学校とも連携をとっているところです。","voiceIndex":300,"id":"exchange-128"},{"speaker":"高橋委員","kind":"質問・要望","question":"許認可、平成２５年度に幾つ例があったかわからなかったので、これは後ほどで結構です。社会福祉法人の制度の改正が見込まれています。制度の改正が今後ありますけれども、ぜひ利用する方々が使いやすいように、また社会福祉法人の適正な運営のため、平成２５年度からつくられたこの事業をしっかりと行っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-129"},{"speaker":"浅野委員","kind":"質問","question":"１９９ページの特定健康診査等事業費、時間があれば１２７ページの要介護度改善ケア奨励金について質問します。１回だけ電話をするのかについて教えてください。それと、受診勧奨通知の対象者、これは多分、受診されていない方に対して送るのでしょうけれども、３回というのは、受診しなければ最大で３回まで通知をするのか、郵送をするのかということについて教えてください。","respondent":"高森国保医療年金課長","answer":"３回通知をするということで、これについては６月に、実は５月に一斉に健診の受診券をお送りするのですけれども、そこから２週間程度後に、一斉にご案内をしております。","voiceIndex":306,"id":"exchange-130"},{"speaker":"浅野委員","kind":"確認","question":"はがきでダイレクトメールということですけれども、３回というのは、最大３回まではがきを送るということなのか、そこら辺のことを１つ確認をしておきたいと思います。受診勧奨をしなくても特定健康診査を受診された方の人数というのは、わかりますでしょうか。相乗効果も考えられると思いますので、区の判断というか、考察について教えてください。","respondent":"高森国保医療年金課長","answer":"それとあと、コストのほうの話ですけれども、特定健診におきましては、国と都からの補助金等々も出ておりますので、大体１件８,０００円を超えるような健診費用というふうな認定になっておりますので、それが安いか高いかということであれば。","voiceIndex":308,"id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"なかなか効果を測定するというのは非常に難しいかと思います。こちらの効果をどういうふうに考えるのか、はがきで送るのと、電話をかけるのと、こちらのほうは私はしっかりと分析をしていかないと、今後、平成２６年度どういうふうにやっていくのか、今後以降、特定健診を進めていくということを考えると、やはり重要な分析だと私は思っておりますので、この辺について再度お伺いします。","respondent":"高森国保医療年金課長","answer":"来年度に向けてもさまざまな形で分析をしまして、生かしていきたいというふうに考えているところです。","voiceIndex":310,"id":"exchange-132"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも進めていっていただきたいと思います。少しでもほかにいい方法があれば、ほかの自治体の例なども参考にしていっていただければと思います。次に、要介護度改善ケア奨励金ですけれども、昨年度からスタートして、改善した件数が４１件あったと、このように聞いております。そしてまた、本事業の平成２５年度の評価、どのように分析をしているのかということと、今後の取組みについて教えてください。","respondent":"永尾高齢者福祉課長","answer":"周知度がまだいま一つでありましたので、もう２年目になりましたので、もう少し施設に対して周知していきたいというふうに考えているところです。","voiceIndex":312,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"この制度もスタートするときにどうなるのかというふうに思っていたものでありまして、段階が１段階上がると月２万円ですか、報酬が出て、２段階ですと４万円ということで、かなりの金額だなということと、あと、先ほど言われた職員のモチベーションということで、上がっていく、やはりケアをする側としては、少しでも良くなってもらいたいという気持ちはたくさんあるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-134"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は、民生費の２項児童福祉費から１３５ページ保育園関係、それから１４０ページの品川児童学園運営費、この辺にかけて質問させてもらいます。それから、保育園関係ですが、区内ですと、事業所内保育所というのですか、企業が保育所を持っているところがありますね。それから、私は法的にわからないので、その施設はどういうふうに捉えればいいのか、その２点を教えてください。","respondent":"中山障害者福祉課長、今井制度改革・待機児童対策担当課長","answer":"ただ、今後、児童学園の改築に伴いまして、一旦、児童学園を仮移転する必要があります。その中におきましては、こういった本来事業を戸越ルームで行うことも検討をしていきたいと考えているところです。訪問飲料の会社ですとか、研究所、それから株式会社等、その事業所です。こちらは、６人以上の保育施設ですので、認可外保育施設という形で届け出いただいているものです。","voiceIndex":316,"id":"exchange-135"},{"speaker":"鈴木（真）委員","kind":"提案","question":"それぞれありがとうあります。それももう大分、１０年ぐらい前になるのか、提案がたしか委員長のほうからあったと思うのですが、その辺も調整していただきながらお願いしたいと思います。認可外ということで、その辺はわかってきたのですが、何を確認したかったかというと、１つの事業をやっていることは知っていたのですけれども、区としてそういうところと折衝する形ができるのかと。","respondent":"中山障害者福祉課長、今井制度改革・待機児童対策担当課長","answer":"やはり情報提供というのは、見た方がわからなければ何もならないというところになりますので、できるだけ法律用語等は工夫を凝らして、見た方がこの先の療育はどういった形で進められるのか、どういった施設があるのか。昨年も平成２５年８月の説明会以来、新制度の説明会におきまして、このような事業所内保育施設も含めましてお声かけさせていただきまして新制度の説明をいたしておりまして、１施設、区の認可事業への移行のご希望があるところです。","voiceIndex":319,"id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"パンフレットはお願いするのと同時に、今度、品川児童学園が仮移転するのが平成２８年４月ですか、その前にいろいろな説明もある。何かその辺をうまくケアしていただきたいと。それから、開設時期が平成３０年１１月だと思うのですが、時期としては非常に半端ではないかというところを感じるのです。例えば、担当する職員の方がどういう採用になるのか非常に心配しています。児童学園についてお願いします。","respondent":"中山障害者福祉課長","answer":"幸いにも今年度、戸越ルームが開設できましたので、あそこを最大限活用することを考えながら、ご利用者のご意見を伺いながら対応していきたいと考えております。それから、開設時期です。","voiceIndex":322,"id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ちょっと話が別になります。今朝一番で我が党の横山委員のほうから、児童相談で質問させていただきました。向こうの所長に出ていただいて、相当、１時間半、２時間近くお話を伺ってきたのですが、その中で品川区からも派遣して研修していただいた方がいるということも伺っております。せっかくのそういう人材を生かしていただきたいということから、確認をさせていただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"児童相談所への職員の派遣につきましては、現在、３人目です。１回につき１人を派遣しておりまして、戻ってまいりました２人につきましては、１人は子育て支援課の児童相談担当の職を経まして児童センターのほうに、もう１人は直接児童センターのほうに行っております。","voiceIndex":324,"id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ぜひそういう方を活用していただいてというと表現は悪いですけれども、せっかくの知識ですから、いろいろな部署に生かしていただきたいと思います。その辺で研修体制は十分とっていらっしゃるのでしょうけれども、現場へ出ていないという指摘が少しあったもので、その辺の今後の派遣とか研修について教えていただければと思います。","respondent":"伊崎子育て支援課長、永尾高齢者福祉課長","answer":"現場に出ていないというご指摘につきましては、児童相談所とか、相談機関という、児童相談所につきましては、そういった形で継続していきたいと考えております。それで、社会福祉士の養成講座を介護福祉専門学校のほうで通信制で行っております。その中で、区の職員にも資格取得のための助成なども行っておりますので、そういうものも含めて総合的に考えていきたいというふうに思っております。","voiceIndex":326,"id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"やっぱり専門部署というのは一番深いのではないかという気がしますので、それだけに大変な状況だということも理解はします。我々ではわからない部分が、皆様、プロとしてやっていらっしゃる部分なので、ぜひそういう人材をまた増やしていっていただいて、いつでも異動ができるような形もとっていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"私は、１３４ページ、児童福祉費と、それから１２８ページ、高齢福祉費についてお聞きしたいと思います。先ほどから保育事業の話が出ております。一生懸命やっていると思うのですが、都内で働く保育士の約２割が退職を検討している。このことに対してどのように思っているのでしょうか。そしてまた、何かそれに対してその人たちに支援をしているのでしょうか。それについてご見解をお聞かせください。","respondent":"竹田保育課長","answer":"昨年から処遇面を改善すべく、処遇改善事業を実施しております。今年度も引き続き実施しております。非常に厳しい労働条件の中で仕事を続けていくには、心の問題もあろうかと思います。","voiceIndex":331,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"結局、若い人たちが、子どもを育てていきたい、保育士になって、この子たちの未来の一部に貢献したいという気持ちで入ってくる、純粋な気持ちで。今、処遇改善しているという話がありましたが、そうなのですか。その中で品川区は、申し訳ないですけれども、年間３０億円の利益を出しているわけですね。それについてもう１回ご見解をお聞かせください。","respondent":"竹田保育課長、今井制度改革・待機児童対策担当課長","answer":"昨年度、年度の途中で補正させていただいたのですが、４月分からさかのぼって実施しておりますので、実際の処遇面は一定程度改善されたと思います。今後、平成２９年度に向けまして、またこちらのほうもアップすることも含めて検討しているということで、長く働いている方への処遇改善も含めて検討されております。","voiceIndex":333,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"今お話を聞きましたけれども、それは一人ひとりの保育士の賃金がアップしたというわけではなくて、保育園に一律渡しているので、ではお聞きいたしますけれども、実際、一人ひとりどれだけ給与が上がったか、そういうものは全部把握されているのでしょうか。","respondent":"竹田保育課長","answer":"お一人当たり月額９,０００円ということで、４月にさかのぼって支給されていますので、実際の人数もきちんとお聞きして、多い少ないがないかどうかもきちんと精算させて報告を受けていますので、必ず各保育士の手に渡っているものと考えております。","voiceIndex":336,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"わかりましたが、それでも一月９,０００円です。実際、東京都の調査ではそういうふうに辞めたいという人がいるということを、やはり私は認識していただいて、保育士の処遇はきちんと改善していただきたいと思います。そして、３カ月以内に辞めていく人も多い。これもやはり給与が低い。それについて、どう思われていますか。そして、実際にこの方たちの処遇改善はされているのでしょうか。お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"それで、区のほうでも事業所連絡会を２カ月に１回程度行っておりまして、そういう意見を各施設からお聞きしながら、どういう方向がいいかということを検討しているのですけれども、ただ、一番すぐにできることというのは、やはり人間関係を良くすることで。","voiceIndex":338,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問・要望","question":"再度申し上げます。保育士も介護職員もそうです。この金額で生活していけますか、この都会で。住宅費もどれだけ高いと思っていますか。さっき笑われていましたけれども、それは違います、違うでしょう。だって、皆さんは平均年収６６０万円たしかあるわけですよね。でも、この方たちは全然年収が増えない。私は、そういうことも考えて政策をやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２６ページの紙おむつ支給、そして１２９ページの緊急通報システムと障害者福祉手当、それから１３１ページの福祉タクシー利用券、品川区で２３区最低になっている福祉の引き上げを求めて質問をしたいと思います。２つ目に、財源の問題です。２３区で既にほかの２２区がやっているということで、最後にこれを実施するというのが今回の品川区の状況ですから、私は平均以上にしていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"紙おむつの支給の件です。現在、介護保険制度改正もございまして、第六期に向けていろいろな事業の見直しを行っております。その中で紙おむつの支給について、今検討をしています。","voiceIndex":342,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後にやるわけですから、平均を超えるということで、ぜひやっていただきたい。市町村特別給付というのは、６５歳以上の保険料ですから、保険料を押し上げることになるので、これは実施しませんというのが、私は２３区調査をこの問題でもやりましたけれども、品川区だけです、市町村特別給付をこれだけやっているというふうなことは。この３点についてお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"ただ、周知をしていきたいというところと、あと費用をもう少し安くしたいという思いは区でも持っております。今、対応している事業者とも価格について交渉しています。ですので、総合的に見て判断していきたいというふうに考えております。","voiceIndex":344,"id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、ぜひとも、これは命に関わる問題なので、お金がネックになって使えないということが命とりにならないというふうにしていただきたいのです。そのためにも住民税非課税者には無料にしていただきたいということを求めたいと思うのですけれども。これで品川区の財政からすると、全然問題のない額だと思うのですけれども、無料にするというところではどうなのか、その点についてお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"ですので、単純に今３５０万円あれば大丈夫という判断はできませんので、将来のことも考えながら設置の方法を考えていきたいと考えています。","voiceIndex":346,"id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平均でも３,３３０円ですから、平均よりも１,０００円以上少ないという状況です。どの調査をしても、調査をしても、調査するものが２３区最低というこういう状況になっているということに、私は改めて、やるたびに驚くわけですけれども、そういう中で、これをせめて他区並みにということで、額としてもこの額でできるわけですから、ぜひ引き上げていただきたいと思うのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"障害者福祉にかかる施策というのは、こういった手当やタクシー券だけではありません。品川区は総合的に進めておりまして、例えば計画相談などは２３区トップです。","voiceIndex":348,"id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"さまざまな調査の中で、なぜ品川区が最低なのかという、そういう区民の声もありますので、ぜひ他区並みへの引き上げをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":350,"id":"exchange-150"},{"speaker":"いながわ委員","kind":"質問・要望","question":"多ければバス代が１５％から２０％はね上がるということは、旅費にもはね返ってくるということでありまして、老後の生活を楽しく有意義なものにするという趣旨で補助金が出ているわけですが、１１３クラブ全てがバス旅行に行っているわけではないと思いますし、しかし、宿泊研修といいますか、何かしらの手立て、時代が流れている中でさまざまな形で。","respondent":"永尾高齢者福祉課長、白鳥高齢者いきがい課長、伊東生活福祉課長","answer":"町会・自治会からの推薦ということですけれども、やはり地域に根ざした方が対応していかなくてはいけないということになりますと。私のほうから、１１３クラブあります高齢者クラブへの支援というご質問です。実際の数字ですけれども、孤独死、孤立死というのがどういう方を差すかというと、少し難しいところはあろうかと思うのですけれども。","voiceIndex":352,"id":"exchange-151"},{"speaker":"いながわ委員","kind":"質問・要望","question":"平均年齢と理想の年齢とお伺いしました。先ほどご答弁の中で、７３歳で定年をされた後、また新たな何か、役に立つ何かを、その方に定年後もついていただきたいという話ではありました。先ほど、認知症のことで触れられたのは、民間企業との連携等いろいろ言われていましたが、こういったことも含めた中で幅広く孤独死をなくすための取組みをしていただきたいのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長、伊東生活福祉課長、白鳥高齢者いきがい課長","answer":"やはりそういうお声も出てきたりしておりますので、３年に一度の改選のときを機会に、一緒に話し合いをしながら、変更できるところは変更しています。なかなか難しい部分があるのですけれども、先ほどの見守りの話がございましたけれども、そこと連携をとりながら、異常を早めに察知しまして。クラブによりましては小規模、大規模、人数によって異なりますけれども、これは状況把握に努めてまいりたいというふうに思っております。","voiceIndex":356,"id":"exchange-152"},{"speaker":"いながわ委員","kind":"質問・要望","question":"民生委員に関しては、先ほど歴史的なということがありました。歴史を変えるのが品川区だと考えていますので、ぜひやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":360,"id":"exchange-153"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、１２５ページの職員給与費に関連してと、１４０ページのすまいるスクール運営費についてお伺いしたいと思います。後ほど、質疑の中で写真を掲示させていただきたいので、委員長、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最初に、１２５ページの職員給与費に関連してなのですけれども、高齢者、障害者の関係で、職員の方がいろいろとご相談とか手続とかをされているということで、各課の中で高齢者のご相談とか手続等で窓口に来られる高齢者が一番多い課はどこなのかということと、また、その応対の中でご苦労されていることがあればお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"福祉の現場では、高齢者の方はいろいろな部署にご相談でいらっしゃいますけれども、高齢者福祉課長としてお答えをしますと、やはり耳が遠くなったり、なかなか難しい言葉がわかりにくくなったりしますので。","voiceIndex":364,"id":"exchange-155"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実は、私事ですけれども、今年の１月に私の父が亡くなりまして、千葉なのですけれども、私も千葉の実家のほうに、母が高齢なものでいろいろな手続で千葉の市役所に伺ったときに、これはなかなかいいなというものを、それで写真を使わせていただきたいのですけれども、今この杖置きという、これは拡大したのですけれども、窓口へ高齢者の方は結構杖をついていらっしゃる、また、障害者の方も。","respondent":"永尾高齢者福祉課長","answer":"高齢者福祉課の所管のところは、全て杖置きはついておりますので、あとは、いらっしゃったときに、区のほうでお声かけをきちんとしてあげたいというふうに思っております。","voiceIndex":366,"id":"exchange-156"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それは大変失礼しました。あまり見かけないもので、非常に感動したものですから、もしまだ導入されていないようだったらぜひ導入していただければと思いました。ただ、ここでは聞けないと思うのですけれども、それ以外のところも、多分高齢者の方がいろいろな手続で来ると思うので、もしまだ導入されていないようでしたら、そのほかの部門でもまた導入していただきたいと、これは要望だけします。","respondent":"伊崎子育て支援課長","answer":"これにつきましては、自治体への説明会もございまして、こちらは品川区でやっておりますような放課後児童健全育成事業、学童クラブと放課後子ども教室、これを学校の中で一体的に進めることによって、今、学童保育の待機児童が非常に多いと言われる中。","voiceIndex":368,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区として、今ずっと子どもたちについては、保幼小連携、中学校まで入れるかもしれませんけれども、そうした滑らかにしていこう、段差をなくしていこうと、また小中一貫ということで、小学校と中学校の段差を発達に応じてなくしていこうという取組みをされている品川区として、例えばこの小１の壁という、これはどちらかというと親の面でもあるかもしれませんけれども、そういう壁に対して、取り除くのか。","respondent":"伊崎子育て支援課長","answer":"小１の壁という表現につきましては、今申し上げましたように、やはり利用できないお子さん、待機児童が多いというところで、それが親御さんの就労を継続するための壁となっているというところで使われている言葉と捉えております。","voiceIndex":370,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。品川区も何年も前から親育ちということで、親に対してのいろいろなことをやっている。ただ、全部がそうかどうかわかりませんし、もちろん費用対効果もありますので、ただ、流れとして国も今そういう流れになっておりますので、品川区も検討の課題の１つに上げたというふうに位置づけたということでしたので、ぜひ前向きに進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":372,"id":"exchange-159"},{"speaker":"伊藤委員","kind":"確認","question":"成果報告書の１４１ページ、生活保護費に関連をして。それから１２８ページ、高齢福祉費に関連して質問します。初めに、先ほど大沢委員の質疑の中の確認ですけれども、平成２５年度のいわゆる不正受給の件数は、５３件、４,６７０万円の総額なのだけれども、うち７件、９００万円が回収されて、実際の不正受給の金額は、４６件、３,７７０万円でいいのでしょうかという確認をお願いいたします。","respondent":"伊東生活福祉課長","answer":"先ほどは失礼いたしました。今、委員おっしゃったとおりです。","voiceIndex":374,"id":"exchange-160"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひお願いしたいのは、これで大沢委員が予定した質問をできなくなったのです。この生活保護は法改正があって、さまざまな行政の立ち入りが強化される、いろいろなことがあったと思うのだけれども、そういうものをどう活用して、不正受給の根絶につなげていくのかということをまずお伺いしたい。当たり前のことなのだけれども、それが実は生活保護の次の目的であると思うのですけれども、いかがでしょうか。","respondent":"伊東生活福祉課長","answer":"その結果としまして、その方々がそのまま生活保護を受けていた場合を想定して考えますと、その効果として１億円ほどの効果が出ているというふうに試算をしておるところです。","voiceIndex":376,"id":"exchange-161"},{"speaker":"伊藤委員","kind":"確認","question":"私が確認したかったのは、そういう権限が強化されたわけだから、それを活用して私たちのところに来るいろいろな不正受給のうわさに対してどう対処していくのかという具体的なところをぜひお伺いしたいと思っていますので、改めてその答弁をお願いいたします。それから、高齢福祉費のほうは、地域包括ケアシステムというものがこれから始まっていきます。お願いします。","respondent":"永尾高齢者福祉課長、伊東生活福祉課長","answer":"今、新しいいろいろなシステムなどもどんどんできているところです。国のほうもそういうものも推奨しておりますので、品川区の中でそれがどういうふうに活用できるかということを検討してまいりたいと考えています。今回の改正、いろいろと罰則の強化等々もありますので、きめ細かく受給者に対してそういうことを説明しつつ、しっかりと申告をしていただきまして、そういうことがなくなるように頑張っていきたいと考えております。","voiceIndex":378,"id":"exchange-162"},{"speaker":"伊藤委員","kind":"質問","question":"それぞれご答弁ありがとうあります。地域包括ケアシステムのところだけ指摘をしておきますけれども、これはいろいろな窓口があります。地域のこともあれば、町会のこともあれば、商店街のこともあれば、となれば、これは将来的には品川区全庁で考えていくべきではないかと思いますので、そのことのお願いと、それから北海道では統一様式をつくっていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":381,"id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1392#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":116674,"voices":382}},{"id":"h26-20141110-4","meetingId":"h26-c-settlement","date":"2014年11月10日","dateIso":"2014-11-10","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を137件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２５年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"私は、衛生費から、１４３ページの定期予防接種、１４４ページの任意予防接種、１４５ページの子宮がん検診の確認をさせていただきたいと思います。第１に、子宮頸がん検診についてお聞かせください。子宮頸がん検診の該当年に当たる対象者には、個別の受診券を郵送するなど、区民への周知を図っているかと思いますが、減少の原因はどのようなものだとお考えでしょうか。","respondent":"川島健康課長","answer":"検査で陽性であっても、１,０００人に１人か２人はがんを発症するという可能性も言われておりまして、結果として検査過剰となる懸念を私どもは考えてあります。そういったことから、もう少し、ほかの自治体と国の動向を見据えていきたいと考えています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"ＨＰＶの検診導入については、品川区としては検査過剰の懸念を現在持たれているということで、ほかの自治体や国の動向をしばらく見ていく、注視していくということだったのですけれども、それは、大体どのくらいの期間を考えていらっしゃるのですか。","respondent":"川島健康課長","answer":"今のご質問の何年くらい、研究、検討するかということですが、まず、国で評価と研究を行っているということですので、それを見させていただいてからということで、年数のお約束はできないのですが、なるべく早くやりたいと考えております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"今後、子宮頸がんの原因の１つとなるＨＰＶの検出に関して、より簡易な尿検査が注目されているかと思いますが、子宮頸がん検診の今後の品川区の展望について、簡単に教えてください。","respondent":"川島健康課長","answer":"尿検査の導入にかかわらず、最新の動向を探りながら、より区民の方に喜んでもらえるような検診にしていきたいと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"私から、１４３ページ、予防接種費、ワクチンアプリについて、１４６ページ、環境衛生費、薬事衛生で危険ドラッグ、時間があれば、１４７ページ、食育推進事業、江戸東京野菜について伺います。子どもの予防接種について伺います。すべての個別の名称は結構ですので、教えてください。","respondent":"佐藤保健予防課長","answer":"定期予防接種、任意予防接種についてのご質問です。定期予防接種ですが、現在、お子様に対する予防接種は１１疾患７種類となっております。品川区で任意接種を助成しておりますものは、おたふく風邪、Ｂ型肝炎となっております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"定期接種が１１疾患７種類、任意接種が２種類あるということでした。さまざまな機会を捉えてお知らせいただいているというご答弁をいただきました。それは理解できます。定期、任意を問わず、質問の順番として、生まれてから一番最初に受けるのは何ワクチンであるのか。これは任意、定期を問わずお伺いしたいのと、ワクチンによっては期間をあけなければいけないものがある。何か一例を教えてください。","respondent":"佐藤保健予防課長","answer":"期間や回数ですが、それぞれ期間はいろいろな定義があります。回数につきましては、４種混合ワクチンは初回３回に追加１回の４回、Ｈｉｂワクチン、小児用肺炎球菌も４回という形になっております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"Ｂ型肝炎を最初に受けて、３回、４回ということで、間隔をあけてこれを受ける。スケジュール管理が大変だということは、常々言われているところです。打ち忘れてしまった場合、未接種の場合のことも伺いたいのですけれども、再勧奨をされているのか、いないのか。再勧奨されている場合に、最終的に接種率が高いものと低いものを教えてください。","respondent":"佐藤保健予防課長","answer":"その関係で、最も高いものは、単純計算で小児用肺炎球菌の１０９％、最も低いもので、５歳になりますが、ＭＲワクチンの８７％となっております。そのほか１０歳以上で受けるものにつきましては、それ以下のものもあります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"おおむね高い接種率を得るまで再勧奨、再々勧奨されていて、低いものだとＭＲワクチンの８７％ということでした。今年も、これからインフルエンザやロタウイルスなどの流行性疾患もでてくる。こうした流行情報のお知らせはどうされているのか、教えてください。","respondent":"佐藤保健予防課長","answer":"そのほか、学校や保育園とも協力・連携をとりまして、なるべくタイムリーな感染症の予防情報を発信するように努力しております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"さまざま、るるお聞きしましたけれども、機会を捉えて、区もいろいろな発信をされているのは理解しております。該当する予防接種に対して、接種の１カ月前からカウントダウンで計５回のメールが届く。現在のお知らせとか、お問い合わせの体制に加えて、先ほどの民間アプリや自治体のこうしたワクチンアプリについて、ぜひ研究していただいて、導入も考えていただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤保健予防課長","answer":"これからのお母様は常にスマートフォンを持っているという世代ですので、そういったアプリについても私どもも検討しなくてはならないかと考えています。ただ、自前で開発するのか、その他のものをご案内するのかということもあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"続きまして、１４６ページ、環境衛生費、薬事衛生から危険ドラッグについて伺います。実は、私の友人のご兄弟も、これが原因で、３０代でお亡くなりになった方もいらっしゃいます。今、薬事法などを拡大解釈しながら規制を行っている状況と認識していますが、薬事行政を司る保健所の範囲で伺います。かつてはあったのか。品川区保健所としてどう把握しどのように対処しているのか、教えてください。","respondent":"高山生活衛生課長","answer":"品川区内における危険ドラッグの店舗の状況と、それに対する取り締まりということのご質問かと思います。店舗の特定ですが、こちらは国、東京都の麻薬取締部門、そして薬務部門から提供された情報を用いまして、現状、１店舗あると聞いております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"確認","question":"今確認しているところで１店舗というところですけれども、大都会の東京で、表に出ている氷山の一角であると思いますし、現在は店舗というよりは、インターネットで闇に潜っているというのが実態であると思います。急増した２０１１年ごろには、ドラッグの質が変わって、非常に危険なものに変化したとなっております。このあたりの広がりや危険性について、何か把握していれば、教えてください。","respondent":"高山生活衛生課長","answer":"日々報道の中でも、こういった、より多幸感の高まるものが競うように売られているということです。一方で、非常に安易に入手が可能だというところもございまして、そういったもののいたちごっこになってしまうのですが、広がりには大変懸念を抱いているところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"おっしゃるとおり、今、覚醒剤、麻薬については、いろいろな研究が進んでいるので、脳の神経がどう壊れるのか、わかっている。覚醒剤や麻薬は、１対３対３対３と言われるそうです。１割が死亡する。３割が刑務所か病院。現在、厚生労働省の麻薬取締官は全国に２６０人しかいないというところで、第３回定例会では、２３区中１１区議会が危険ドラッグの根絶に向けた対策強化を求める意見書を採択している。","respondent":"川島健康課長","answer":"直接区で周知しているわけではないのですが、都の薬物乱用防止の指導員が１４名、品川区に委嘱されております。会議室をとりまして展示とか、街頭運動のお手伝いをしていますので、引き続きそういったものをしっかり支援していきたいと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"松永委員","kind":"質問","question":"本日は、成果報告書の１４４ページの感染症予防費、そして、１４６ページの公衆便所費について伺います。時間がありましたら、１５５ページの中小企業対策費についても伺いたいと思います。感染症予防費について、予算額が約９,２００万円余、成果報告書では、約８５０万円程度下回っております。今年度の執行状況について、お伺いしたいと思います。","respondent":"佐藤保健予防課長","answer":"ここは、国庫支出金返還金というのがあります。こちらが、今回、３５５万９,０００円ほど削られておりますが、こちらの額は前年度比で国庫負担金が出てきます関係上、毎年かなり大きく違ってまいります。その関係で、今年度は少し形が変わっているです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"松永委員","kind":"確認","question":"わかりました。感染症についてですけれども、都内でもデング熱の罹患者が確認されるなど、最近になり、新たな発生が報告されております。国際化の進んだ今現在、品川区でもこのような感染症の脅威は重要な問題であると考えます。このような現状を踏まえ、品川区において現状で十分な体制がとられているのでしょうか。伺いたいと思います。","respondent":"佐藤保健予防課長","answer":"感染症の発生時の対応についてのお尋ねです。デング熱、エボラ出血熱のお話が出ましたが、エボラ出血熱についてのお話をさせていただきたいと思います。実際、流行３国からの入国の方につきましては、検疫所で１日２回の健康監視を行うということになってあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"松永委員","kind":"質問・要望","question":"平成２５年度の成果報告書を見ますと、近年、品川区では一類、二類というのは、感染症がないものですから、ゼロ件ということで、少し安心していたところです。そうしますと、品川区において、このような感染症が区内で発生したときに、国などとの連携の整備について、どのように取り組んでこられたか、お聞かせいただきたいと思います。","respondent":"佐藤保健予防課長","answer":"疾患は違いますが、一定の新興感染症、または再興感染症につきましては、この新型インフルエンザ等対策行動計画が１つの目安になると考えています。今回もエボラ出血熱の流行を受けまして、連絡会議を既に庁内でとっております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、今、大井埠頭とかは大丈夫なのかという不安もあるのです。発生した場合に備えての、関係者間での訓練といったことは行っているのでしょうか、予定はありますでしょうか。","respondent":"佐藤保健予防課長","answer":"今年度も机上訓練を行う予定で今のところはおります。港側に近いというところで、東京検疫所の持っている連絡会議に品川区も入っております。その中で、１１月２１日に検疫所の訓練がございまして、そちらに品川区保健所として参加する予定です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"公衆便所費について伺いたいと思います。公衆便所の整備については、衛生分野における隠れた重要施策と確認しております。特に私は災害時の公衆便所の役割について、十分な検討を行うことが必要と考えます。品川区においては、３６カ所が維持管理されているそうです。そうした公衆便所が使えなくなる主な原因、そして今後の品川区での対応をお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"そのようなものを発見した際、区に報告が来て、修繕する業者に直ちに発注する形で、なるべく区民の皆様にご迷惑をかけないように、迅速な対応を図っているところです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"公衆便所ですけれども、続いて、防犯上の観点から伺います。ご存じのとおり、区内の公衆便所では、現在、つい立てがある部分とない部分という箇所があります。そうした公衆便所の本来の性格を考えた場合に、やはりつい立てがあったほうがいいかと、私は思うのですけれども、区民の中からもそういう声があるのですが、これについて伺いたいと思います。","respondent":"多並公園課長","answer":"区内の公衆便所には、いわゆるつい立て、目隠しのものが、３６カ所中１０カ所設置しています。そのほかは、ない形です。","voiceIndex":40,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"そうしますと、品川区内での過去の犯罪件数とか、事件等がもしあったとしたら、教えていただきたいと思います。","respondent":"多並公園課長","answer":"公衆便所の件ではございませんが、最近の例で言いますと、小山台公園の中で放火、また器物破損という形で事件がございました。そんなところも対処しながら進めているところです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"１５６ページの商店街活性化事業費をお伺いします。地域の商店街の経営が大変な状況になっていることは、もう皆様ご存じのことと思います。個店の努力だけでは、なかなか再生しない今の実態、この点について区の認識をお伺いしたいのが１点です。数字を幾つかお伺いしますが、商店街の数、また小売店舗の数、大規模店の数、そして、それぞれの変化、傾向についてお伺いいたします。","respondent":"米田商業・観光課長","answer":"それから大規模小売店舗がおおよそ３０ということです。小売店舗の数については、残念ながら、年々減少しているという状況にありますが、大規模小売店舗については、現状のところ、ほぼ横ばいかという認識をしています。","voiceIndex":45,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域に住む人は、身近なところに品揃えがよいお店、そして買いやすいお店があればと願っています。ぜひ消費者の目線での店舗づくりの支援を求めていきたいと思います。この間、平成２３年度に商店街の実態調査が行われたと聞いています。その調査がその後どのように活かされているのか。若者、そして障害者、子連れの方々、高齢者、消費者の目線での改善が必要と考えますけれども、この点はいかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういった調査結果も、商店街、あるいは消費者とも共有しながら、区としても、種々施策に結びつけてまいりたいと思ってあります。","voiceIndex":47,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"若者参加のアンケートの中にも、ぜひ若者の目線の中身を入れていってほしいと思うのです。若者が参加できる、知恵を借りられるような取り組みをしてほしいと思うのが１点です。２点目は障害者。これを当たり前なまちにしていただきたいと思います。こういったことで、区の支援で宅配の制度、１店舗でも参加できるようなシステムをつくってほしいという声が出ていますが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"こういったものもさまざま勘案しながら、今後、区としてどういった支援が適切であるかということについて、十分考えてまいりたいと思います。","voiceIndex":49,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"イベント等で、本当に地域が元気になっているというのも感じていますけれども、日常的に商店街が元気になる。そういった面では、一過性のものではなくて、続く支援が必要と思います。そのためには、とことん住民参加、地元の若い人の力を大いに借りていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、１４５ページ、各種がん検診なのですけれども、ほかの自治体でもがん検診にすごく力を入れているところがありまして、早期発見・早期治療により将来の医療費を控えると明確にビジョンを出していたのですけれども、改めて品川区はどうでしょうか。がん検診等の考え方についてお伺いします。先細りがないようにしていただきたいと思うのですけれども、その辺の計画と決意についてお伺いします。","respondent":"高山生活衛生課長、川島健康課長、太田品川保健センター所長、山崎ものづくり・経営支援課長、米田商業・観光課長","answer":"これから何が見えてくるかですが、例えば、よく出されますのは、合計特殊出生率などと言われるようなものでありますとか。年に数回、がんに関しての特集記事も掲載しておりますので、もう少しこの取り組みを頑張っていきたいと考えています。６カ月と９カ月健診につきましては、委託しておりまして、また母子保健法で自治体に実施義務があるという健診ではなく。その結果、区内の３つの商店街の方々に、それぞれの商店街のイベントの設営費用でありますとか、あるいはポイントカードシステムの更新ということで。","voiceIndex":53,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"人口動態調査ですが、これをほかの課でもどう使っていくのかということを改めて教えてください。それと、がん検診なのですけれども、明確なビジョンをお答えくださいと言ったので、明確なビジョンをお答えください。","respondent":"柏原行財政改革担当課長、川島健康課長","answer":"その他の人口の動き、転入・転出等があります。そういうものをトータルに、我々企画部門を中心にしながら、施策にいろいろ活かしているといった現状があります。明確なビジョンです。具体的に数字は示せないのですが、少しでも受診率が上がるように頑張っていきたいと考えています。","voiceIndex":59,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"衛生費の１４４ページの感染症予防費、１４９ページの環境対策費、環境指導相談費、１５０ページの緑化活動支援事業についてお伺いします。感染症予防費で、先ほど他の委員からもありましたけれども、エボラ出血熱等の感染症予防についてお伺いさせていただきたいと思います。まさに、世界的な危機になっているエボラ出血熱ですけれども、先ほどもいろいろ説明がありましたので、そこら辺は省きます。","respondent":"佐藤保健予防課長","answer":"そのようなことで、いろいろな考え方はあると思いますが、リアルタイムで連携をとりながら、遅れないように対応できているかと考えています。","voiceIndex":63,"id":"exchange-025"},{"speaker":"沢田委員","kind":"質問・要望","question":"特に保育園以外の、保育園だけではなくて、子どもたちの声による騒音ということで、少しお伺いさせていただきたいのです。具体的にどういった事例があったのか、お聞かせください。何デシベル以上で何秒ということがあるかと思うのですが、その辺を改めて確認させてください。警察との連携という部分でも、どういった形で連携をとられているのかということも確認させてください。","respondent":"三ツ橋環境課長","answer":"環境苦情に関する騒音に対してのお問い合わせです。区の環境課に入っております騒音の苦情の中で、子どもの声に関する騒音の苦情というものは、特に保育園関係ではなく、道路で遊んでいる子どもたちの声がうるさいというものが１件入ってあります。","voiceIndex":65,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問・要望","question":"例えば、グラウンド近辺とか、学校周辺での苦情という形での区への通報はないということなのか、もしくは警察にそういった情報が入っていて、警察から区には、特にそういった情報はないということなのかというのを確認させていただきたいです。騒音全般に関してでもいいのですけれども、どういった基準をもって騒音と言っているのか、そのあたりのことを改めて確認させていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"法的な関係の連携なのですけれども、今回、子どもの声の騒音は、それぞれの施設で対応している案件が多いので、環境課に直接は入ってきておりません。基準ですけれども、住居地域によって基準が決まっております。","voiceIndex":67,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"この条項が削除されるという話もありますけれども、区として子どもたちの声に対する対応を今後どう考えられているのかということをお伺いさせていただきたいです。そういったことに対してしっかりとした対応をとっていかなくてはいけないのではないかと思うのですけれども、そのあたりのお考えも、改めてお聞かせください。","respondent":"三ツ橋環境課長","answer":"警察との連携についてですが、例えば、野球場の騒音の場合ですと、やはり野球をするということと、近隣の方への配慮ということもありますので、具体的に騒音を測って、何か施設で対応できることがあるかどうかも考えております。","voiceIndex":71,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問・要望","question":"野球で声を出すとか、公園で遊ぶというのは当たり前のことですから、子どもは地域の宝、日本の宝であるので、子どもたちの健全育成をしっかりと見守っていきたいと思います。次に、緑化活動支援のことでお伺いしたいと思います。生物多様性ということで質問させていただきたいのですけれども、先般の予算特別委員会でもお伺いしましたが、今年も小野学園のホタル園が大変な成功を収めております。","respondent":"三ツ橋環境課長","answer":"生物多様性に関するご質問です。広く大きな捉え方をして、環境部門としては、生物多様性というのは、やはり環境部門で考えなければならない問題だと考えています。","voiceIndex":73,"id":"exchange-029"},{"speaker":"沢田委員","kind":"意見","question":"そういった勉強していく段階ということで、これからも区として、行政として、都市部の行政、自治体の中で、なかなか環境の保全というところの学習する環境や自然を守っていくという取り組みを積極的に進めていくということもあるかと思います。改めて、今後具体的にビオトープを公園内に整備するという、環境課でやっていくという方向性について、もう一言お聞かせいただければと思います。","respondent":"三ツ橋環境課長","answer":"ビオトープに関するご質問かと思います。実際にどこの場所がいいのか、どのようにやっていくかなどは、関係部署と連携をとり合いながら検討させていただきたいと思います。","voiceIndex":75,"id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１４６ページのそ族昆虫防除対策費、それから、１５５ページの若者就業支援事業、１５３ページの収集運搬作業費の３つについてお伺いしたいと思います。この、そ族昆虫防除対策費の対策という事業の内容についてもう少し詳しくお伺いしたいのと、予算と決算との差につきまして、どのようなことで、こういうことになったのかということで、２点お伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"もう一つは、防疫ということで、消毒などの業務もそ族昆虫防除対策費の中で対応しておりまして、昨年度は執行の実績はあったのですが、幸いにして広範囲にわたる防疫業務が発生しなかったということから、執行率に関しては寄与していないという点です。","voiceIndex":78,"id":"exchange-031"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご説明をいただいて、予算の執行については、前年度に比べるとスズメバチや消毒のところで実績がなかったということでした。デング熱に関しては、蚊の駆除について、今年についてはいろいろな要望もあったと思いますけれども、こういう予算の執行につきまして、そ族昆虫防除対策費をもう少し拡大していくような方向性をお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"そういったご指摘もありますので、どういった形での対応が最適かということについては、引き続き検討してまいりたいと思います。","voiceIndex":80,"id":"exchange-032"},{"speaker":"塚本委員","kind":"確認","question":"わかりました。次に、１５５ページの若者就業支援事業についてなのですけれども、これは平成２５年度から始まった事業であります。特に３番目の若者就業体験事業については、契約から正規という形で、正規社員になれなかった方は、これを見るといないということでよかったのかという確認を含めて、若者就業支援事業、平成２５年度の決算を受けて、どのように評価されているか、お伺いしたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"ただ、こうした事業につきましては、さまざまな経済の環境ですとか、雇用の状況なども、いろいろ目まぐるしく変わります。そうした景気動向なども踏まえて、区としては最善の策を考えていきながら取り組んでまいりたいと考えているものです。","voiceIndex":82,"id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"今、課長の答弁でありましたところで、もう少しお伺いしたいのですけれども、確かに若者就業支援は、リーマン・ショック後の新卒での採用が非常に厳しい状況の中で、正規の職につけなかった人たちがたくさんいたというところを受けての事業もあったかと思います。こういう状況に、この事業は少し方向性を見たほうがいいのかという思いもするのですけれども、それに対してのご見解をお伺いしたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"一般就労の分野と専門的にカウンセリングが必要な部分ですとか、そこが少しグレーな部分があります。区としましては、就業分野と、そうしたさまざまな区のセクションと連携しながら対応していきたいと考えています。","voiceIndex":84,"id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。一方、自治体によっては開封調査ということを主にして、ごみ収集の分別を進めているというところもあると伺っています。時間がないので、最後に開封調査というのは、プライバシーの問題も非常に兼ねているので、その辺のところでどのようにお考えかということをお伺いしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"ごみの内容の点検ということですけれども、適切な分別がされているかどうか、概括的に見たときに、適正排出の見地から必要最小限、必要な場合は中を開封して確認しています。","voiceIndex":86,"id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成果報告書１４４ページの感染症予防費に関連して、現在問題になっているエボラ出血熱の対策についてお伺いしたいと思います。エボラ出血熱について、簡単にご説明をお願いします。","respondent":"佐藤保健予防課長","answer":"潜伏期は、文献によりますと、２日から２１日程度、突然の発熱、頭痛、倦怠感、筋肉痛、咽頭痛等の症状を呈すとされております。次いで、嘔吐、下痢、胸部痛、出血、これは吐血、下血がメーンですが、その症状があらわれるような疾患ということになっております。","voiceIndex":89,"id":"exchange-036"},{"speaker":"鈴木（博）委員","kind":"質問","question":"エボラウイルスは５種類あり、２０１４年現在、西アフリカで大流行しているのは、最も毒性が強いザイールウイルスと言われておりまして、これは死亡率が５０％から９０％と言われています。エボラ出血熱の潜伏期間は、今お話があったように、２日から最長２１日で、突然の発熱、頭痛、激しいだるさ、筋肉の痛み、のどの痛みと、インフルエンザと同じような症状で発病します。予防のワクチンはありません。","respondent":"佐藤保健予防課長","answer":"エボラ出血熱の感染経路についてのご質問ですが、エボラウイルスに感染し、症状が出ている患者の体液等、つまり血液、分泌物、吐物、排泄物や、患者の体液等に汚染された物質、これは注射針などになりますけれども、これを十分な防護なしに触れた際。","voiceIndex":91,"id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今お話があったように、症状が出た患者や、その血液、唾液、汗、精液、涙、母乳、さらには吐物や便、尿、それから、それらに汚染された注射器などに直接触れて感染すると言われています。これは空気感染は起こらないと言われています。ただし、患者が咳をした場合、その咳の飛散した分泌物から感染する可能性もあると言われています。現在、我が国では、どのような水際対策がとられているのでしょうか。","respondent":"佐藤保健予防課長","answer":"それとは、また別に、当日発熱のある方については、検疫所でしかるべき対応をしていると聞いております。自己申告していただいた３カ国から入国した方についてですが、そちらにつきましては、検疫所でおよそ１カ月間、１日２回の健康観察をされていると聞いております。","voiceIndex":93,"id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３カ国というのは、ギニアとリベリアとシエラレオネです。もしも品川区でエボラ出血熱患者が見つかるとしたら、どのようなケースが考えられるか、今のご検討の内容を教えてください。","respondent":"佐藤保健予防課長","answer":"今回の町田市のケースのように、ご本人が医療機関に行ってしまって、医療機関の先生が入国していたという経歴を問診でお聞きになって、医療機関から疑似症という発症届を出されるケースがもう一つのケースということが考えられるかと考えています。","voiceIndex":95,"id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"流行時が西アフリカ３カ国に限定されていることと、無症状の患者には感染力がないこと。実際、医療機関にこのような連絡があった場合に、救急車が到達するまでにどのぐらいの時間が想定されているのでしょうか。今回の八王子市の事例のようなことは、品川区においてはいかがなのでしょうか。これは想定されているのでしょうか。","respondent":"佐藤保健予防課長","answer":"ただ、保健所に区内の医療機関からご連絡があって、私どもが東京都に連絡をし、ほぼ救急車と同じような対応の車両になっておりますので、車の置いてある都内何カ所かの場所からそちらに行っていただくということの経路の中で、１０分、２０分では到達できないと思いますけれども。","voiceIndex":97,"id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"意見","question":"厚生労働省の通知によりますと、無症状の帰国者に関しては、２１日間、１日２回健康監視が必要だということでありますが、これは具体的にどのように、時間がない。それと、医療機関に、例えば、６０人とか１００人の患者一人一人に、インフルエンザと症状が非常に似ているので、渡航歴を聞くのは非常に難しい。その辺はどうしたらいいか、ご検討をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"公衆浴場の中に、設備等整備補助が３２件、１,２９５万円とありますけれども、区内の銭湯はたしか２９カ所のはずなのですけれども、この３２件とは何のことでしょうか。そして、整備資金、利子補助が４件、２５２万円余と記載されていますが、そうすると残りの２５カ所の銭湯では金融機関からの借り入れが全くなく営業していると理解していいのでしょうか。","respondent":"川島健康課長","answer":"少し関係ない説明ですが、平成元年には品川区に８５件浴場があったということなのですが、平成１５年になりますと４４件、平成２５年は当初３０件だったものが、この９月末で２９件になったということで、減少しているため、その辺のずれが出ているです。","voiceIndex":101,"id":"exchange-042"},{"speaker":"木村委員","kind":"質問・要望","question":"一時、ピークの平成元年には８５カ所あったということであります。新しく建設する、もしくは改装する場合、区そして都の助成金というものは、どのぐらいの割合で出るのか、教えていただきたいと思います。","respondent":"川島健康課長","answer":"健康増進型浴場ということで、例えば、ミニデイサービスなどを行う場合につきましては、そちらの改築の支援で、区から１,０００万円の補助が出るということです。あわせて、改修した場合に金融機関から借りました利子の補助をしています。","voiceIndex":103,"id":"exchange-043"},{"speaker":"木村委員","kind":"意見","question":"多分、２０分の１が補助されるということで、例えば、建築費が２億円だった場合には、区は最高で１,０００万円ぐらいだろうということであります。もしくは、これから、そういう廃業に対して歯止めをかける対策というものはあるのかどうか。そして、公衆浴場の未来をどのように考えているのか、もしお考えがあればお聞かせください。","respondent":"川島健康課長","answer":"このままなくなってしまうというのは忍びないということで、できる限り支援をして、延命ということではないのですが、できる限り長続きできるように、頑張っていただけるようにバックアップしたいと考えております。","voiceIndex":105,"id":"exchange-044"},{"speaker":"木村委員","kind":"質問・要望","question":"この事業が少しでも長く続く秘訣、秘策というのですか、それは、ずばり何かということ。そして、一人でも多くの高齢者の方に体を動かしていただいて、健康を維持してほしいという思いからだと思うのですけれども、今、国民の平均寿命が、女性は８６歳を超えておりますし、男性はようやく８０歳を超えました。週に一度ではなく、これを増やすことは無理なことなのか。もう一度お考えをお聞かせください。","respondent":"川島健康課長","answer":"大きなところもありますし、小さなところもあるというところで、一律にやるという部分については難しいかと考えています。","voiceIndex":107,"id":"exchange-045"},{"speaker":"木村委員","kind":"意見","question":"次は、１４８ページの一番上なのですけれども、保健指導費の各種健康塾、８３１万円余からです。健康塾ですけれども、延べ約３万７,０００人。なぜこのような項目を、はっきりとトリム体操と書かないのかということ。これを計算しますと１,０００回近くなるのではないかと思います。１会場あたり約２０人の高齢者が集まる計算ですけれども、これも週１回ではなくて、増やしていくことは可能なのかどうか。","respondent":"川島健康課長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-046"},{"speaker":"渡部委員","kind":"質問・要望","question":"１５７ページ、品川技術ブランドＰＲ事業のところと海外進出推進事業、１５８ページ、ものづくり地域企業ネットワーク再生支援についてです。それが平成２６年には３回に減ってしまっています。今後の展望等も、あわせてお伺いしたいです。だとすれば、商談件数が減っていったのはなぜだろうと思ったので、この辺の検証を聞かせていただきたいのと、この辺のこれからの展開。その３点を先にお願いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"今後の展開としましては、タイも含めて、ＡＳＥＡＮ諸国というのは、経済の新興国ですので、品川区内の産業の活性化のための１つの商取引のパートナーといいますか、展開する場所としては、よさもありますので、こうした企業ニーズもお聞きしながら。","voiceIndex":113,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問・要望","question":"ああいう見本市はどういうところに行ってもそうなのですけれども、大手企業が入り口のそばにあって、コンパニオンが雇われていて、どんどん袋と説明書を配ってくれる。偶然にも、その展覧会のときに、ちょうどうちの町会の人たちが、やはり出展者として、みんなばらばらに３名行っていました。何かそのようなことも商業・観光課と手を結んでいただいて進めていただきたいと思いますが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういうまちの動き、あるいはこちらの産業部門の連携等を踏まえて、品川区に誘客できるような形をいろいろ考えてまいりたいと考えています。","voiceIndex":115,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひ検討して進めていただきたいと思います。１点、１５８ページ、品川先端産業支援プロジェクトの中の品川ビジネスクラブのことを聞きます。本格的に動き出したのが平成２４年でしょうか。この辺、平成２４年度から始まって、会員はどういう状況で動いてきているのか。そして、現在の活動状況。それで、品川区との連携をどのようにしていくかを、あわせてお教えください。","respondent":"山崎ものづくり・経営支援課長","answer":"区とビジネスクラブにつきましては、平成２５年４月に区と協定を結びまして、品川区内の産業振興のために、区でベーシックな意味合いの産業の活性化を図る立場と、ビジネスクラブは、基盤事業と比較すると、比較的高度なといいますか、先端産業の支援という形ですみ分けをして。","voiceIndex":117,"id":"exchange-049"},{"speaker":"こんの委員","kind":"確認","question":"１点目の母子保健指導事業費です。ここでは、産後ケア事業、また産前サポート事業についてお聞きしていきたいと思います。周辺の地域がこうしたモデル事業を始める中で、品川区の現状の事業の確認と、また「国の動きを注視して研究していきます」という、その当時のご答弁からすると、これまでどのような研究をされ、今後どのように品川区としての産後ケアをされていくのか、お考えをお聞きしたいと思います。","respondent":"太田品川保健センター所長","answer":"しかしながら、産後ケアの強化につきましては、子育て支援、少子化対策の側面を持つ重要な課題と認識しており、子育て支援の関係各課と連携して、検討を進めてまいりたいと考えています。","voiceIndex":120,"id":"exchange-050"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区の取り組み、そして今後の考え方の確認をさせていただきました。そこで、今後検討していく旨、また産後ケアについての重要性、そのご認識は確認させていただいたところですが、現状を確認したいのですけれども、品川区の今ある事業を進めていく中で、例えば、要支援家庭相談数を見ますと、平成２３年、平成２４年、平成２５年とそれぞれ増加しております。もう一度ご答弁いただきたいと思います。","respondent":"太田品川保健センター所長","answer":"品川区で行っております要支援家庭の支援ですが、まず、すくすく赤ちゃん訪問事業で産後うつのチェックを行い、そこで特に具体的に数字を挙げますと、ＥＰＤＳで９点以上、あるいは自分を傷つけてしまうような気がするというお答えだったご家庭については、産後の４カ月健診。","voiceIndex":122,"id":"exchange-051"},{"speaker":"こんの委員","kind":"質問","question":"現状をお聞きしましたけれども、今おっしゃられた産後うつの検査ですけれども、エジンバラ産後うつ、この質問に対しての取り組みもご紹介がありました。「育児の技術を教わって、育児の不安が解消されてきた」と答えた方が６２.３％いるわけです。単発的な育児ヘルパー支援もある中ですが、継続的に支援していく、こうした体制が今後品川区でも必要ではないかと思いますが、この点いかがでしょうか。","respondent":"太田品川保健センター所長","answer":"もちろん継続的なケアは、施設で泊まることができなかったとしても、在宅のご家庭に訪問するということを継続しておりまして、できているとは思っておりますが、今後とも一層充実していきたいと考えています。","voiceIndex":124,"id":"exchange-052"},{"speaker":"こんの委員","kind":"質問","question":"訪問してくださっている今の事業を大事にするとともに、さらに充実したいというところでは、１つ可能性があるのではないかと思う点が、家庭あんしんセンター。こちらの施設を活用する、あるいはそこでの児童のショートステイもあるので、そうしたところの可能性を秘めているのではないかと思われるのですが、いかがでしょうか。","respondent":"伊崎子育て支援課長","answer":"家庭あんしんセンターの中の子育て支援センターにおきまして、養育支援訪問という形で、今、委員ご指摘のヘルパー派遣、それから訪問事業を継続的に行っているところです。今後も充実させていく方向です。","voiceIndex":126,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"成果報告書１５４ページの就業支援費にかかわって、若者就業支援事業を伺いたいと思います。区の役割は、解決につなぐ身近な相談窓口ということですけれども、この答弁の「大変重要な問題」とは、どのような問題だとお考えなのか、ここを伺いたいと思います。区の答弁、「大変重要な問題」とは、どういうお考えなのか、伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"区としましても、産業の活性化を図る観点で、企業それぞれが良好な雇用環境を整えまして、企業に勤める方々が安心して働ける環境を整備するということについては、大変重要なことだと考えているものです。","voiceIndex":129,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"安心して働くことができる環境づくりは大変重要です。もう一点、品川区でも地域若者サポートステーションを設置して、支援を強めていただきたいと思いますけれども、この点も伺いたいと思います。もう一点、就業体験事業は正規雇用につなぐという事業ですけれども、正規雇用と位置づけている理由は何か、区の考えを伺いたいと思います。正規雇用を位置づけている理由を伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"正規雇用につきましては、今ご説明の長期基本計画の考え方、多様な就業支援をするというところで、若者の自立の１つの形態として、経済的自立ということになりますと、正規雇用を目標にしようではないかということで取り組んでいるものです。","voiceIndex":131,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"若者支援にかかる事業をぜひガイドブックに整理してほしいと思うのです。とりわけ、若い世代は区役所とのかかわりがまだまだ薄いですし、そこにどんなメニューがあるのかということそのものを知る機会もなかなかないですから、こういうガイドブックの作成や配付、スマートフォンでダウンロードできるなど、そうした周知の工夫をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"区の就業の取り組みにつきましては、やはりいろいろな区の事業の中でも、スタートして３年ほどです。そうした中で、午前中にもあった雇用環境ですとか、そういったもろもろのことを勘案しながら、１つトライアル的に実施したりということでやっているものです。","voiceIndex":133,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校や大学を卒業した後の就職や、一度就職した後の再就職の労働相談など、そういった部分が、すっぽり支援や紹介が抜けていると思うのです。それだけに、まずはどんなメニューがあるのか、よく整理をして、成人式だったり、婚姻届を出すときであったり、さまざまな機会を捉えて、周知徹底を図ることに、ぜひ工夫をしていただきたいと思いますけれども、改めて伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"産業支援にかかる若者の支援の関係、それから区として、さまざまな観点で若者層へのアプローチの事業もあります。区全体の、例えば広報部門などと連携しながら、検討してまいりたいと考えています。","voiceIndex":135,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"私からは第４款衛生費、１４３ページの予防費、子宮頸がんワクチンと、１４５ページ、環境衛生費の猫の不妊・去勢手術費助成についてお伺いします。その前に、委員長に許可をお願いしたいのですが、資料の提示を後ほどしたいと思いますので、許可をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"子宮頸がんワクチンについて伺います。平成２５年第２回定例会で子宮頸がんワクチン定期接種化として、７,２００件、１億１,９４４万８,０００円の増額補正がされています。最終補正では減額ということになっていますが、子宮頸がんワクチン接種事業の決算額が幾らになっているのか伺います。積極的勧奨を中止以降の接種人数と、２０１４年の新規の接種人数、３点を伺います。","respondent":"佐藤保健予防課長","answer":"ちなみに、ＨＰＶワクチンは１人３回打つことになっております。平成２６年度の新規の方の件数ですが、平成２６年は現在までの実績でトータル１９本の本数が打たれております。そのうち、１回目ということになりますと、新規で打たれた方は６名ということになっております。","voiceIndex":140,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"子宮頸がんワクチンですが、被害者の会が東京都、千葉県をはじめとして、全国で９都県に拡大しています。区内では、２０１０年からの任意接種期間も含めて、およそ４,９００人以上が接種していると思います。ヒトパピローマウイルスワクチンは、否応なく定期接種になって、自治事務ということになっていますから、ぜひ品川区も後追い調査をしてほしいと求めたいと思います。見解を伺います。","respondent":"佐藤保健予防課長","answer":"今そういった国の動きがあるところですので、区として独自の形で調査する予定はございません。","voiceIndex":142,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"区が行う助成の増額や申請事業の適用化・効率化が担い手である区民からも大変評価されていて、区が助成をしていただいているのですが、実際には、この取り組みはお金をつけただけでは進まなくて、担い手があって初めてということだと思うので、不妊・去勢手術に取り組む市民の活動が、まさに品川が進めていく市民と行政の協働事業であり、また、公益性の高い事業だと私は思うのですけれども。","respondent":"高山生活衛生課長","answer":"委員ご指摘のとおり、まさに典型的と申しますか、非常に区と区民との協働事業ということで、大変評価されるものだと思います。献身的なボランティアに支えられての事業と捉えております。区といたしましては、可能な限りの誠意という姿勢に変わりはございません。","voiceIndex":144,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"でも、最近になって、今度は「公園内で猫に餌を与えないでください」という看板が提示されるようになりました。このために餌づけをして、去勢手術などを行おうという区民の方たちが暴力を振るわれるという事象も発生しています。ただ、クレームに対して反応するのではなくて、この公益性ある事業というのをもっとしっかりと訴えていって、改善を求めたいのですが、いかがでしょうか。","respondent":"高山生活衛生課長","answer":"公園内につきましては、公園管理上のさまざまな迷惑行為に対するという、やむにやまれぬ事情もあろうかと思います。動物愛護指導の普及という点におきましては、公園管理部門と連携をとりながら、最適な管理方法について模索してまいります。","voiceIndex":146,"id":"exchange-062"},{"speaker":"渡辺委員","kind":"確認","question":"成果報告書１５６ページ、商店街活性化事業費で伺ってまいります。これまでのさまざまな施策、観光でありシティプロモーションであるという中で、やはり品川区が発信する、そして自慢の１つとして商店街というものがいろいろな場面で挙げられているかと思います。その中で、午前のご答弁にもありましたが、もう一度確認も含めて教えてください。新規出店をどのように把握されているか、まず教えてください。","respondent":"米田商業・観光課長","answer":"商店街の店舗数ですけれども、例えば、商業統計調査ですと２,８００の小売店があるということになってあります。","voiceIndex":149,"id":"exchange-063"},{"speaker":"渡辺委員","kind":"質問","question":"それを前提に、まずそこが現状維持されることは最高の評価であると同時に、今新たな支援として何点か伺います。ホリデー・トレーニングという事業の魅力、特徴。自分が伺っている限り、これは地域力をすごく巻き込める、活用できるという評価も聞いていますが、それを１つ教えてください。その中で、現状の中で、あえて利点、特徴、行政の立場からのコメントをいただければと思います。","respondent":"米田商業・観光課長","answer":"消費者側から購入するとき、使うとき、それから商店街からのいろいろな意見がありますけれども、そういうものを全部踏まえて、あるいは経済情勢等も見きわめて、今後の商品券事業については考えてまいりたいと、このように考えてあります。","voiceIndex":151,"id":"exchange-064"},{"speaker":"渡辺委員","kind":"質問・要望","question":"次年度に向けたときには、まず、枠の拡大について強く要望したいのが１つ。は金額です。自民党としたら、１０億円のプレミアム付商品券というものを要望させていただいています。これは、インパクトも含めて、２０２０年という節目に向けても、品川区の観光施策、いろいろな施策を取りまとめる上での大きなインパクトとして、１つの中心事業として、ぜひとも要望したいと思っています。","respondent":"米田商業・観光課長","answer":"今後もさまざまなお声を踏まえて、検討を進めさせていただければと考えています。","voiceIndex":153,"id":"exchange-065"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ぜひご検討ください。理由も、今ご答弁いただいたのと、思いは一致しているかと思います。その中で、もう一つ、最後に要望になりますが、継続的に考えたときの小規模店舗支援と同時に、先ほども触れましたが、新規出店への支援。新規出店された若い方、オープニングで苦労する。これを継続して、地域の活性化につながると思っていますので、この点はまた別の機会にも伺いますが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-066"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、１４５ページの３５歳からの健康診査、それから、もう一つ、１５１ページのリサイクルショップ運営費についてお伺いしたいと思います。この中を見ますと、７８５人ということでありますが、始まったばかりなのでこれは少ないのか、多いのか、どんな思いなのか、少しその辺を教えていただきたいということです。４０歳からの同じような健康診断をなさったのか、その辺を教えていただきたいと思います。","respondent":"川島健康課長","answer":"今、委員からご説明いただいたとおりの事業として、３５歳からの健康診査を行っているものです。今お話もありましたが、４０歳からの特定健診の受診に向けまして、その前の年齢から定期的な健診受診の習慣化を促すというのが主な目的です。","voiceIndex":157,"id":"exchange-067"},{"speaker":"山元委員","kind":"質問","question":"３５歳から３９歳は、普通でいくとお仕事をなさっている方たちが受診するというのは、なかなか大変という気がするのですが、その中でも１,０００人目標だったのが７８５人ということであれば、上々ととるべきかと思います。この方たちへの周知の方法は、先ほどお医者様のところにポスターを配って張りつけたり、それ以外に周知の方法はなさったのでしょうか。","respondent":"川島健康課長","answer":"それで、先ほど私から説明させていただこうと思ったのですが、やはり周知方法というのは、私どもも課題と捉えております。３０代の方ですので、ホームページですとか、ＳＮＳ、先ほども言いましたツイッターですとか、そういったものが何か活用できないか。","voiceIndex":159,"id":"exchange-068"},{"speaker":"山元委員","kind":"質問・要望","question":"了解しました。生活習慣病、やはりある程度年齢がいってからでは遅いと思いますので、そういう意味では、３５歳から目をつけたというか、スタートしたというのは大変すごいことだと思いますし、どんどん拡大していただきたいと考えていますので、よろしくお願いいたします。リサイクルショップ運営費ということで、質問します。旗の台と大井町の２店舗であります。この内訳を教えていただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"リサイクルショップ運営費の支出内容ですけれども、今、委員からご説明いただきましたように、エコタウンしながわが実施している運営に対して、区が支援しているという支出内容です。","voiceIndex":161,"id":"exchange-069"},{"speaker":"山元委員","kind":"質問・要望","question":"この運営費４００万円というのは、もしかしたらそういう人件費等が入っているのかというのをお聞きしたいということです。２５人のスタッフの方がお仕事をされていると聞いておりますが、その内訳がもしおわかりになれば教えていただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"働いていただいている方の内訳なのですが、申しわけございません、人数構成等については、明確には把握してございませんけれども、基幹となる職員については常勤形態で、それから実際の店舗を商品管理も含めて運営してくださっている方は。","voiceIndex":163,"id":"exchange-070"},{"speaker":"山元委員","kind":"意見","question":"そのボランティアの方も大分お年を召していらっしゃって、スタート時期からずっとやっていらっしゃるのです。多少の有償で、１時間２００円ということで、平成９年からずっと変わらず、そのままいたというお話です。有償で１時間２００円が高いのか、安いのかは別として、電車で通っている方もいらっしゃるということで、大分年数がたっておりますが、何か対策というか、お考えはありますか。","respondent":"小林品川区清掃事務所長","answer":"現状ご指摘いただいたところですけれども、リサイクルの整理をお互いに助け合ってというところで、意欲を持ってボランティアとして参加していただくという点もありつつ、ご指摘のとおり、そうは言っても。","voiceIndex":165,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、少し先ほどとかぶってしまうのですけれども、１４５ページの３５歳からの健康診査と、それに関連して、同じページの成人歯科健診について伺いたいと思います。私たちも求め続けてきたものですので、これだけ受診があってよかったと思っています。１,０００人目標とおっしゃっていたのですが、そもそもの対象者というのは、何人ぐらいいたのでしょうか。","respondent":"川島健康課長","answer":"先ほどの３５歳からの健康診査の対象者数の人口ですが、３万５,５２６人ということで、こちらの人口に対して、受診者数が７８５人だったです。男女比ですが、女性の方が多く受けておりまして、受診者数は男性が９３人、女性が６９２人です。","voiceIndex":168,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、習慣化と、先ほど課長もおっしゃっていたのですけれども、４０歳手前の世代に、健康について、そして健診についてというところでの習慣化とおっしゃっていました。厚生労働省の健康についてのプランだったり、医師会からの要望の中でも、やはり健康格差をなくしていくということが、一番の問題意識だったと思います。この辺はどう考えていますか。","respondent":"川島健康課長","answer":"今お話にございました、国の国民健康づくり運動プランというものの第２次の中にも、はっきり健康格差の解消というのは書いておりますが、これは若者に限定したものではないということで認識しています。","voiceIndex":170,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、１,０００人目標で７８５人、これだけ受けてよかったと思うのですけれども、対象者も３万５,０００人を超えているというところでは、もう少し広げて、そして、健康格差、子どもから高齢者までの間で、やはり働く世代、しかも非正規雇用の部分の健診が保障されていないというところでは、区としてそこを支援していくことが必要だと思うのですけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"ただ、いろいろな施策を総合的にやっていく中でのもので、この健診の対象年齢を下げていったというところで、それが解決するかというと、なかなか難しいという認識です。","voiceIndex":172,"id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現在の成人歯科健診は、４０歳から５歳刻みで７０歳まで、これも対象者拡大を求め続けてきているのですけれども、３５歳からの健康診査に入れていただければ、対象者が拡大していくわけです。４０代からの歯科健診をしているのは、２３区でも９区しかないのです。ぜひ一緒に３５歳からの健診の対象者拡大と、ここに歯科健診も入れていただきたいと思うのですけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"この時期から歯周病の予防、進行防止を徹底していくことが、歯の喪失防止に重要であると考え、区は歯周病も生活習慣病の１つであるという考え方から、リスクの高い年齢と捉えた４０歳以上の方に成人歯科健診を実施し、あわせて、歯の健康維持についての普及啓発、それから。","voiceIndex":174,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりリスクの高くなる手前の認識が必要だと思うのです。３５歳からの健康診査も、先ほど医師会の名前も出させていただきましたけれども、医師会からも要望があって、健康格差が問題だということで言われていた、そして要望されていたものだと思います。歯科医師会では、こういった若い世代への拡大の要望や議論などはされているのでしょうか。","respondent":"川島健康課長","answer":"当然、歯科医師会とすれば、年齢を拡大したいという話はあると思います。だからといって、区でそういった施策を実施するかというのはまた別の問題になりますので、そういった考えです。","voiceIndex":176,"id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほどからずっと言っているのですけれども、やはり健康診断の機会を失っている世代に広げてもらいたい。健康格差をしっかりとなくしていくということが一番の大もとにはあるのですけれども、区民一人一人の健康をつくっていくというところでは、大きく健診というのが役割を果たすと思うのですけれども、改めてもう一回、拡大していただきたいと思うのですけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"平成２５年に３５歳まで対象年齢を下げた部分で頑張ってやっていくというのが１つだと考えています。","voiceIndex":178,"id":"exchange-077"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、午前中に少しありましたが、子どもの声の騒音について伺いたいと思います。次に、１４４ページ、これもほかの委員が質問された感染症に関して、エボラ出血熱ですが、東京都において、先日、エボラ出血熱対策連絡会議があったということで、消防庁や特別区と市から担当する主管部長なども出席したということで、品川区は参加されていないと伺いました。同じカラスということで、どこが違うのか。","respondent":"三ツ橋環境課長、佐藤保健予防課長、山崎ものづくり・経営支援課長、小林品川区清掃事務所長","answer":"実際に、この環境確保条例の第１３６条は「何人も」条例なので、特に何人も。そして３番目に、１１月１１日に行う予定です、都立病院および公社の病院におきます受入訓練についての概要説明と聞いております。残りの４名については、昨年、その時点では就職活動を継続していたということになります。こちらの外来種というのは、ハクビシンおよびアライグマです。こちらは箱罠を設置して、その後捕獲できた場合は捕獲いたします。１５３ページのカラス対策。","voiceIndex":181,"id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に住民の理解を得た合意形成についてどう考えているか、教えていただきたいと思います。カラスなのですが、勘違いしていたので、これは終わりたいと思います。感染症予防なのですが、訓練を行った自治体もあると伺っていますが、訓練を行う考えがあるかどうか。そういったとき、混乱が起きないような情報の出し方の検討をされているのかどうか、お知らせください。","respondent":"三ツ橋環境課長、佐藤保健予防課長、江部危機管理室長","answer":"今後も、引き続きしっかりと対応してまいりたいと思います。関係部署と連携をとりながら実施していきたいと考えています。本年度も直近では１０月２０日に、ほかの部署の方や保健センターの職員などもまじえまして、防護服の着脱訓練を実施したところです。実際に発生した大変な危機の場合につきましては、危機管理室が主導となります全庁の対策会議を立ち上げまして、対応に当たる予定です。","voiceIndex":187,"id":"exchange-079"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、子どもの声の騒音ですが、今までも対応してきている中で、これからもやっていくということだったのですが、保育園の子どもたちが安心して外で大きい声でめいっぱい遊べるように対応していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-080"},{"speaker":"西本委員","kind":"意見","question":"１５０ページの環境啓発・推進事業の中で、家庭ＩＳＯ、環境ＩＳＯの運用。ＩＳＯ１４００１なのですけれども、平成１３年に取得して、１２年間を終えた。これが廃止になるという形になっておりますけれども、この経緯についてお尋ねします。成果はあったのか、なかったのか。それと、商店街にぎわい創出事業には、３つほど助成金がありますけれども、それぞれの違いについてお知らせください。","respondent":"三ツ橋環境課長、米田商業・観光課長","answer":"ＩＳＯについてのご質問です。こちらは、委員ご指摘のように平成１３年９月２１日に認証を取得いたしまして、１２年間ずっと継続してまいりました。にぎわい事業といいますのは、年間で６回程度継続して、その商店街で継続的な取り組みということで、種々その商店街において、自分のところではこんなことをやる。","voiceIndex":193,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"ＩＳＯを返上しました。区の独自システムになると書いてあるのですが、どういう形で独自性を出して、それを対内、対外的に認知して、品川区としてのＰＲに至らせるのか。それをどういうふうに認知させていくのでしょうか。そうではなくて、毎回同じ事業をやっていて、今年もお金が来るからやるような状況になってくると、それは少し違うだろうと思っているのですが、どういう状況になっているでしょうか。","respondent":"三ツ橋環境課長、米田商業・観光課長","answer":"例えば、環境プログラムというものがありますが、それをもっと充実させていったり、ＰＲ方法につきましても、ホームページなどで周知してまいりたいと考えています。当然、毎年風物詩となっているイベントもありますし、新たに自分の商店街でこんなことを行ってみたい、イベント事をやってみたいということでの申請もありますので、これは新規のもの、継続のもの。","voiceIndex":196,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"それをどうカバーして、先ほどホームページ等々で品川区独自のというのでは、私は弱いと思います。それと、家庭ＩＳＯも、今後どう変えていくのか、これは大きなことだと思うのです。ＩＳＯということで、何となくみんな環境にいいという認識があるものに対して、それにとってかわる何かがないと、多分マイナスイメージのほうが非常に大きくなってしまうので、そこの工夫はいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"家庭ＩＳＯに関しましても、ＩＳＯというネーミングではなく、違うネーミングで考えておりますので、それもしっかり前向きに推進してまいります。","voiceIndex":199,"id":"exchange-083"},{"speaker":"若林委員","kind":"質問","question":"１４６ページのそ族昆虫防除対策費と、１４５ページ、猫の不妊・去勢手術費助成の２つを聞きます。１つずつ。年々増加傾向にありますけれども、相談内容というのは、今どのような内容になっているのでしょうかというのを１つお聞きします。何かメカニズムがあるようですので、可能性を聞きまして、また可能性がある場合には、来年以降の対応をどうするのかというのもお聞きしておきたいと思います。","respondent":"高山生活衛生課長","answer":"一方で、東京都でも、今般の発生を踏まえまして、年内にそういった都の対応であるとか、来年度に向けた対策について検討するというお話も伺っておりますので、そういった点も踏まえて、平成２７年度の対応については考えてまいりたいと考えております。","voiceIndex":202,"id":"exchange-084"},{"speaker":"若林委員","kind":"質問・要望","question":"下水についても認識があるということで、しっかりと感染症も含めて対応していただきたいということが、この質問の趣旨です。両者、蚊の発生を指摘した場合に、午前中では消毒という言葉もありましたけれども、いわゆる薬剤の散布がどのように対応できるか、できないか、そこら辺を確認させていただきたいと思います。","respondent":"高山生活衛生課長","answer":"公道、とりわけ区道については、例えば、ＩＧＲと言われる昆虫成長抑制剤などの投与ということも可能ではありますが、一たび大雨などが降りますと、抑制剤の効用が薄れてしまうということもありますので、そういったものの投与がふさわしいかどうかという点については。","voiceIndex":204,"id":"exchange-085"},{"speaker":"若林委員","kind":"質問・要望","question":"聞き取りにくいところがあったので、私の認識が間違っていたらすみません。いずれにしましても、先ほどの日本脳炎も含めて、１０種類程度の感染症の媒介、可能性があるということ。私も含めて、自分でふたをあけられないというのが区民の大きな１つの悩みでもありますので、そこら辺の具体的な連携についての対応も、しっかりとしたご答弁をいただきたいと思います。","respondent":"高山生活衛生課長","answer":"とりわけ公道部分につきましては、道路部門と相談しつつ、そういった薬剤の投与が最適なのかどうかという点につきまして、検討しながら連携して進めてまいりたいと思います。私道につきましては、私道というだけあって、なかなか踏み込むのも難しいところがあります。","voiceIndex":206,"id":"exchange-086"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、その場その場の状況があると思います。理由は聞きませんけれども、近年の野良猫というのでしょうか。飼い主のいない猫について、餌を与える人、それに迷惑、被害を感じる方、また、その両者の間に立つ、例えば、地域で言うと町会でありますとか、区という立場ですけれども、それぞれどういうご相談事があるのか、また、区として認識をされているのかというのを１つお聞きします。","respondent":"高山生活衛生課長","answer":"それに加えまして、定時定点給餌ということで、同じ場所で、顔ぶれを見ながら、決まった時間に餌を与えるといった活動の継続が、不幸な猫を減らしていくという考えでいるところです。","voiceIndex":208,"id":"exchange-087"},{"speaker":"南委員","kind":"質問","question":"１４９ページの公害保健費について伺いたいと思います。１つは、１８歳未満の子どもは来年４月以降は新たな認定はなくなるということ。１８歳未満の子どもと、それ以上の方の人数は、平成２５年度は何人になるかということと、１８歳未満で新規の認定がなくなるということについては、大変残念なのですけれども、経費負担がかかるということについて、区はどう捉えておられるか。そのあたりから伺います。","respondent":"川島健康課長","answer":"その辺をしっかりとやっていく必要はあると思うのですけれども、区で独自に何か手当するというところは、区の役目としてはどうなのかと考えております。","voiceIndex":211,"id":"exchange-088"},{"speaker":"南委員","kind":"質問・要望","question":"この医療費の助成制度がなくなるということについて、３年後に１８歳以上の方の負担が増えるという点についてはどうかということも聞いたつもりだったのですけれども、後で少し教えていただきたいと思います。そのあたりについての認識を伺いたいと思うのです。そこについて、品川区としてはどのように見ているのか、その見解を伺いたいと思います。そういうことも、改めて認識を伺いたいと思います。","respondent":"三ツ橋環境課長、川島健康課長","answer":"委員おっしゃったように、大気汚染の二酸化窒素、ＮＯ２に関しては、そこの場所によっては基準を達成していない。例えば、大井陸橋については、基準値を達成しておりません。１８歳未満の医療費助成がなくなるということではなく、もともと１８歳未満の方の医療費を助成する制度だったので、５年前のもとの制度に戻るという形で、都が説明しているものです。","voiceIndex":213,"id":"exchange-089"},{"speaker":"南委員","kind":"質問","question":"１８歳未満の新規が来年４月以降なくなるというつもりで質問しているのですけれども、そういうふうにとられていなかったら、そう思っていますので、訂正して、よろしくお願いしたいと思います。国に対してしっかり意見を言うべきです。そこに対して、東京都だけで助成制度を復活させているわけですから、そこについてやはり国に対して意見を言うべきだと思うので、その点についての見解を伺いたいと思います。","respondent":"川島健康課長","answer":"先ほども申しましたが、一義的には国や汚染原因者の責任と考えております。私どもは区民の視点として、こういった改正が早いのではないかという申し入れを担当者レベルではしているところです。","voiceIndex":216,"id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"もう一つ、言い切れなかったのですけれども、医療費負担のところも、非常に重たい負担がかかるわけです。したがって、必要な意見を言っていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-091"},{"speaker":"大沢委員","kind":"質問・要望","question":"１４９ページ、カラス・外来種対策事業と、１５５ページ、中小企業対策費で、融資、商店街、そしてバンコクビジネスサポートセンターを聞きます。お願いします。カラスですけれども、少なければいいと思うのですが、カラスについて寄せられた区民からの苦情というのはどのようなものがあるのか、ご披露していただきたいと考えています。","respondent":"三ツ橋環境課長","answer":"カラス対策の関係のご相談であったり、問い合わせの内容です。カラスに威嚇されて怖いとか、またカラスの声がうるさいとか、そのほかにはカラスが来るのだけれども、どうやってよけたらいいでしょうかという内容です。","voiceIndex":220,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問","question":"威嚇、あるいは声がうるさい。以前に比べまして、カラスを駆除した時期がありました。林試の森にもケージを設けてやった時期がありましたけれども、その後の都と区のカラスに対する対策の動きがあったら、今教えてください。","respondent":"三ツ橋環境課長","answer":"東京都全体的にカラスの生息数を若干下げていこうという取り組みがされております。先ほど、委員がおっしゃいましたように、カラストラップについては、林試の森でありますとか、そのほかのところにも対策をとりまして、カラスの捕獲ということをしております。","voiceIndex":222,"id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"今下げていこうというのは、いつの時点の基準に下げていかれるのか。要は、私は何年か前に、ここで活発な議論で、黄色いごみ袋にすればいいとか、先ほども、網ということでありましたけれども、これはいつに比べて下げていくのか、その基準となる年度があったら教えてください。","respondent":"三ツ橋環境課長","answer":"こちらの、基準につきましては、平成１３年度から生息数を東京都が計測しております。そちらが基準と考えております。","voiceIndex":224,"id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても、あくまでも１羽ずつ数えるわけにいかない。そこのところは、清掃事務所を含めて、環境課長はどのようにご認識をされて、今、区ではどのように扱っているのか。華々しくカラス対策といって論じられた時期がありますけれども、それが今トーンダウンしているのではないかという危惧のもとに、この質問をしています。そこの部分をお含み置きをいただいて、ご答弁いただきたいと思います。","respondent":"三ツ橋環境課長","answer":"東京都の生息数に関しまして、３万６,０００羽が平成１３年度でしたけれども、平成２５年度につきましては、１万３,０００羽となっております。こちらは捕獲等々を行った結果、大分減ってきているです。","voiceIndex":226,"id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても、総体数、確かに３.６万羽から１.３万羽に減ったということ。これは、移動するものだから、東京都内から一歩出てしまえば、東京都外になってしまい、カウントされなくなる。広域的に移動するものですから、効果を数値では捉えにくいと思うのです。この質問は終わりまして、次へいきます。それについて、もう一回説明をいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"先ほど例示で申し上げました、個人事業主で飲食店を営む方、こういったところも融資の対象に当然入ります。そういった小口向けの数多くあるメニューの中の１つで、そういったものも用意させていただいて、対応しているです。","voiceIndex":228,"id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"最終的に融資するのは銀行だと思うのですけれども、この中の法人事業主という部分で、個人事業主については、いわゆる家族経営が主たるもので、企業化しにくい性質が個人事業主ではあると思います。しかしながら、飲食業等々、小口の家族でやっているところは、事業資金がまさに生命線だと思うのですけれども、そこのところ、事業資金の融資についてどのようにお考えになりますでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした認識のもとに、区内で商売されている方から区の融資制度のご相談があった場合でも、説明した内容で柔軟にしっかり対応していただくという協力関係のもとにやらせていただいております。","voiceIndex":230,"id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"本日は駆け足でいきます。次に、創業支援センターなのですけれども、起業について伺います。バブル期においては、お金をもうけたい、いい車に乗りたい、いい家に住みたい、そういう起業マインドというか、そこの部分がありました。バブルもはじけ、経済も落ち着き、静粛化している上で、昨今の起業マインドというのはどのように変化されているのか、教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"そういった創業系の融資も用意しておりまして、個人事業主向けのものと、法人関係向けのもの、こうしたさまざまな品川区内における起業形態に対応するために、まず、お金、資金計画をつくる際の支援を重点的にやらせていただいているような状況です。","voiceIndex":232,"id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"それ以前に、そこのところのアフターフォローはされているということですけれども、最近の会社の寿命、商売の寿命のサイクルの短さを考えた場合に、起業のあり方はどうあるべきか。少し漠然としていますけれども、倒産を含めて、辞めてしまうサイクルが短くなったということも含み置きで、起業に対して区はどのように向き合っていくのか、教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"こうしたフォローを品川区では創業支援センターの場で、インキュベーション施設ということで、そうした場の提供とお金の支援と、企業の定着率というのは、起業して、一般的な統計でいきますと、生き残り率は４０％程度だそうです。","voiceIndex":234,"id":"exchange-099"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただ、ここの現実として、品川区のかかわりではないところで、起業していながら、もう既に賃貸というか、その場所については、次の不動産屋に辞めるような算段をしているところもあるやに聞いておりますし、調べておりますので、そこら辺も含み置きいただきながら、起業の支援をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-100"},{"speaker":"あべ委員","kind":"質問","question":"１４６ページ、先ほども少しお話に出ましたけれども、産後支援について、少し伺いたいと思います。それから、１５１ページからの清掃費の中で、職員採用についてと、特に東品川船舶中継所跡ならびに、その他の清掃関係の庁舎について伺います。それから、１５８ページの品川ビジネスクラブについてもお伺いしたいと思います。端的にお答えください。その点について見解をお伺いします。そこまでお願いします。","respondent":"太田品川保健センター所長、小林品川区清掃事務所長、柏原行財政改革担当課長","answer":"産後ドゥーラにつきましては、概念としてですが、産後のお母さん方を支援する人たちのことと理解しております。それで、この間、適時全体のバランスも含めて、採用等も視野に入れながら対応していますが、まずは全体の効率性を高めて。依然として２０２０年の縛りといいますか、その部分については開いていないという状況です。","voiceIndex":241,"id":"exchange-101"},{"speaker":"あべ委員","kind":"質問","question":"産後ドゥーラ、まさにそのとおりです。例えば、妊婦向けの講演をするなど、区としても少しずつ連携を図っていかれてはと思いますが、いかがでしょうか。その場合には、逆に品川区としては、東品川船舶中継所跡を含めた清掃関係の庁舎が結構たくさんありますけれども、それらについては何もいじらないままということでよろしいのでしょうか。","respondent":"太田品川保健センター所長、小林品川区清掃事務所長","answer":"品川区でも、いろいろな産前産後の学級、それから健康教育等を行っております。そこへの講師派遣については、今後の研究課題とさせていただきたいと思っています。清掃事業が安定して継続できるように、人員構成については現状の組織を主として、新たな必要な体制について、検討してまいりたいと思います。庁舎につきましては、品川、荏原の清掃事務所のほか、全部で７カ所で構成しております。","voiceIndex":245,"id":"exchange-102"},{"speaker":"あべ委員","kind":"質問・要望","question":"ただ、土木事務所跡ですとか、あそこで清掃の事業をこのまま続けているのはどうなのだろうとも思いますし、そうした短期で改善を図るべきものについては短期で、それから少し大きいものについては中期的に、ぜひ総合的に考えていただきたいと思います。もし広いものであれば、ビジネスクラブの運営などについても、人事も含めて、思い切った工夫が必要なのではないかと思いますが、いかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"新施設につきましては、いろいろな産業の業種業態の中の基本となるべく、製造業を中心とした支援という考え方はあります。そうした製造業にこだわらずに、産業の支援の観点で、広く施設は考えているものです。","voiceIndex":248,"id":"exchange-103"},{"speaker":"あべ委員","kind":"意見","question":"区内に、先ほども出ました情報通信、その他、さまざまな産業が育ってきているということですので、そういう運営にするとともに、外からもそのように誤解されないように広報や名称のあり方も含めて工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":250,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。先に、区民健康づくりプラン品川のほうからお尋ねします。そこでお尋ねしますが、今年度、このプランの第２次の策定が予算化されて、そこで前回の計画以降、平成２５年度までの１０年間で、区民の健康に対する意識の変化、健康寿命の変化などの成果について、数値としてお示しいただけるものがあれば教えていただきたいと思います。","respondent":"川島健康課長","answer":"区の健康状況ということですが、少し難しいご質問ですので、品川区の平成２５年度の死因を調べてみますと、１位ががん、２位が心疾患、３位が肺炎、４位が脳血管疾患ということで、１位のがんについてですが、２３区におけるがんの死亡者数の比較をしますと、胃がんについては。","voiceIndex":252,"id":"exchange-105"},{"speaker":"高橋委員","kind":"意見","question":"数字としてはということで、健康に関するいろいろな区民の方々の意識が地域に広がったという効果があったということ。それから、もう一つは、それらの死因の都との比較がありました。ただ、受診率等の関係で、死因とか、そういったこととの関連は、何かわかることはなかなか難しいかと思いますが、あればお願いします。","respondent":"川島健康課長","answer":"なかなか難しい質問でして、まだ詳しくは、プランに載せるという、分析して比較というのがまだ進んでいないので、ご勘弁いただければと思います。","voiceIndex":254,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問","question":"先ほど、ほかの委員からも質問がありましたが、検診率の向上に努めていただければと思います。では、次の質問に移りまして、先ほど少し触れました区民健康づくりプラン２１、第２次の策定中だと思います。厚生委員会で報告があったと思いますが、進捗状況をお伺いします。","respondent":"川島健康課長","answer":"前回の厚生委員会でご報告した内容と重複する部分がありますが、外部の委員を招いた委員会を２回開きました。それから、庁内の検討会も何度かやった中で、１２月１１日にパブリックコメントを実施するのですが、その作業に向けて今素案を作成している最中です。","voiceIndex":256,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問","question":"作業中ということで、承知いたしました。その中で、民生費のご答弁でもありましたが、品川区障害福祉計画は、項目ごとに目標値を設定しております。この健康づくりプラン品川においても、区民の方々の健康度の指標としての目標値を設定すべきではないかと思いますが、その観点での考えをお伺いします。","respondent":"川島健康課長","answer":"先ほどからのご質問にあります、具体的な数字で何か成果がわかるような形で盛り込めれば、盛り込んでいきたいと考えています。","voiceIndex":258,"id":"exchange-108"},{"speaker":"高橋委員","kind":"質問・要望","question":"数値の目標として策定していただいて、区民の方々の健康づくりの方向を具体的に定めていっていただきたいと思います。今後、計画が策定されると思いますけれども、公衆衛生という観点でよろしくお願いいたします。２番目なのですが、品川先端産業支援プロジェクトのほうです。このプロジェクト、事業の概要と、委託先とありますが、施設開設後の指定管理者との関係、そのあたりのご説明をお願いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"事業名称の品川先端産業支援プロジェクトの内容ですけれども、新施設にかかる経費の関係、それから品川ビジネスクラブへのもろもろの支援内容という内容になってあります。","voiceIndex":260,"id":"exchange-109"},{"speaker":"高橋委員","kind":"意見","question":"今、指定管理のお話で、財団法人と株式会社の共同事業体というお話がありました。この指定管理については、従来公的なところは、そういった共同事業体が認められなかった部分があると思うのですが、このように共同事業体の形で指定管理者を指定していくというのは利点で、事業が進むことと、どういう関係があるか、お願いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"指定管理者制度になりまして、法人その他、団体であればというところでございまして、今回は、品川ビジネスクラブが保有する品川区の企業の知見と、３階にはイベントホールもあわせ持つ複合施設ですので、そうした経営に実績がある、それぞれの長所を活かして組んで。","voiceIndex":262,"id":"exchange-110"},{"speaker":"浅野委員","kind":"質問","question":"影響があるということになれば、案内のパンフレットですけれども、買取価格の件について注意事項を載せる必要があると思うのですけれども、この点いかがでしょうか。地球温暖化対策地域推進計画についても一緒に伺います。平成２３年度の結果については、最近だと思いますけれども、結果が出ているかと思いますので、こちらについても、区の評価、また今後の見通しについて教えてください。","respondent":"三ツ橋環境課長","answer":"パンフレットの関係ですけれども、国の動向を見据えながら、パンフレットの中に文言を盛り込むかどうかは、検討させていただきたいと思います。次に、地球温暖化防止対策実行計画の件です。","voiceIndex":266,"id":"exchange-111"},{"speaker":"浅野委員","kind":"質問・要望","question":"課長にも、電話で早目に報告してほしいというお願いはしてあったので、こういう場で論議ができるようにしていただければと思います。地域推進計画については、前に中間見直しの要望もしていたわけですが、これも中間に見直したとしても、随分と日がたってからということで、残りはもう２年ぐらいしか残っていないという状況で、かなりフィードバックがきかないと思います。","respondent":"川島健康課長、三ツ橋環境課長","answer":"しかしながら、眼科検診を実施している自治体、先ほどおっしゃっていただいたとおり、７区あるということですが、まだ少ないようですし、実施にあたりましては、関係機関とさまざまな調整が必要になってくると思いますので。地域推進計画について、今後も引き続きしっかりと対応していきたいと思います。新しく環境マネジメントシステムも導入いたしますので、新しい気持ちでやっていきたいと思います。","voiceIndex":268,"id":"exchange-112"},{"speaker":"浅野委員","kind":"質問","question":"まだまだ少ないと言いつつ、３分の１。それを品川区として、どう見るかということだと思います。やはり目の病気というのは、私の知人も目の病気にかかりまして、ほとんど外を歩けなくなってしまったということもあります。多分、しながわ巡りアプリなどができたときには活躍をするのだろうと思っていますけれども、今後の可能性などについて教えてください。","respondent":"米田商業・観光課長","answer":"しながわ観光百科の情報ですが、７４６件ということで、それぞれ見る、遊ぶ、食べる、買う、学ぶというさまざまな細かい情報を、必ず年に一度見直していただくという作業をしております。","voiceIndex":271,"id":"exchange-113"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"リサイクル関係で資源回収事業について確認させていただきたいと思います。モデル回収に対してはどう考えているのか、その点をお聞きしたいと思います。それから、助成金関係で、薬剤師会に助成している中で、注射針の回収事業にボトルをつくってもらっているのがあると思うのですが、医療的な面からすると、注射針というのはどういう回収をすればいいのか、その辺の確認をさせてください。","respondent":"小林品川区清掃事務所長、川島健康課長","answer":"今後も、それぞれの状況に応じて、どういう収集の仕方がいいのか、生活実態に合わせた収集方法を研究してまいりたいと考えています。使用済みの家庭における注射針の処分につきましては、医療廃棄物として適正に処理する必要があるということで、普通のごみに入れて出しますと、針刺し事故がありますので、そういった針刺し事故等を防止するという観点もございまして。","voiceIndex":274,"id":"exchange-114"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"注射針の関係で、少し誤解していたらすみませんが、東京都がなくなったので、区に補助を求めてきたような気がするのです。ですから、薬局関係のほうでうまく説明してもらえればいいのですけれども、それが清掃作業員の方に影響のないような形をとってもらいたいというのが希望です。それから、清掃関係につきまして、資源回収を戸別にやると、相当費用的に負担が増えるのかどうか、その辺を教えてください。","respondent":"小林品川区清掃事務所長","answer":"２点目の注射針なのですが、ご心配ありがとうあります。そういった回収上のトラブルにならないように、清掃のほうでも針を使っている医療機関に取り扱いマニュアルを配付し、その拠点での回収等を検討方あわせて取り組んでいるところです。","voiceIndex":277,"id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"針のほうは、作業の方に影響がないような形をとっていただきたいということを要望しておきます。資源回収なのですけれども、個別に対応していただいているのはわかりました。これをステーション回収にすることによって、２,７００万円が浮いてくるのでしょうけれども、その分ステーション回収が増えてくると思うのですが、その辺は区として費用が大分減額になるのかどうか、教えてください。","respondent":"小林品川区清掃事務所長","answer":"一方、資源回収のほうは、１,３８７トンということで、区の認識としては、資源回収が十分体系化できた中で、店頭回収はもう終息できるという判断で、来年２月で廃止をするものです。その分の費用として、現在二千数百万円の回収費用につきましては、全額不用額とはできません。","voiceIndex":279,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。この通信を見ていたときに、「廃止後は各店舗が販売責任において回収する予定です」とあるのです。あれと思ったのは、その後に、「家庭から出たペットボトルはお店に持ち込まず、資源回収ステーションにお出しください」と書いてある。少し意味が伝わりにくかったような感じがしました。この前、自民党の沢田委員からも質問がありました。その辺の状況と、これからの区の方針を教えてください。","respondent":"小林品川区清掃事務所長","answer":"これは、一つの解決策として、ぜひ学んでいきたい方向性の一つです。地域の状況に応じて対応として可能であれば、それも参考にしながら、品川区に最も適した回収を今後研究してまいりたいと考えています。","voiceIndex":281,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"集団回収にすると、私の住んでいる町会もやっているのですけれども、今の私の町会は月１回だけです。町会の協力というのは、当然必要なのですけれども、その辺をよく検討していただいて、本当に町会の集団回収だけにしてしまうのかどうか。私は、かなり厳しいかと。うちの町会に関して言うと、かなり難しく感じておりますので、その辺よくご検討いただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"私は、１５５ページの中小企業対策費についてお伺いいたします。４月１日に消費税が８％に増税されてから、区内商店街の景気動向、実態はどうなっているのか。おそらく調べていると思うのですが、ものづくり、製造業のほうも、中小企業、零細企業を含めてですが、実態がどうなっているのか、まずお聞かせください。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"それで、直近の７月から９月ということでは、これもまた大幅な改善が見られたことでの持ち直しというデータが出ておりますが、実際に足を運んでお話を伺っている中でも、厳しさはなかなか脱却できていないという把握をしています。それから比べますと、消費税の部分の冷え込みについては、予測どおりといいますか、やはり反動が見受けられました。このところ、また７月から９月で盛り返すような動きというものは見えてきているところです。","voiceIndex":285,"id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"電気製品もそうですが、一部値下げに転じた。もう１０年を超えても、なかなかなかったような状況だと私は思います。そこでお聞きいたします。先ほどほかの方からも質問があったと思うのですが、区内商店と区内製造業に対する経済政策というのは、こういうふうにやらなければいけない、こうやっていくというものが、何か今まで以上にあるのでしょうか。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"今年の４月に関しては、消費税率の改定ということもございましたので、一例になりますけれども、プレミアム付共通商品券の発行額を増額いたしまして、区内の売り上げの減少が懸念されるということに対処したり。品川区の融資制度につきましては、いろいろなバラエティに富んで、資金需要に応える制度と予算を持っておりますので、これから年末にかけて、私どもの窓口も汗をかく場面があると思って、対応したいと考えています。","voiceIndex":288,"id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"原材料が上がった分、消費税の分を転嫁させるということならば、やはりある程度、一件一件、手紙でもいいですから、「実際にどうですか」「何か手助けすることはありませんか」ということを、私はやってほしい。ここまで大変な状態なら、春・秋に共通商品券を出していますけれども、それではおかしいではないですか。もう一回、商店、商業、そして、ものづくり、製造業の支援課のご見解をお聞かせください。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"やはり、自分たちが元気にして、区内の消費者の方を呼び込んでいかないと、経済も活性化しないし、自分たちも地域のにぎわいを創出できないのだということで、頑張っていらっしゃいます。そうした声に一つ一つ応えていくというのも、自治体としての活性化の担当としての職責と考えています。","voiceIndex":291,"id":"exchange-121"},{"speaker":"須貝委員","kind":"意見","question":"先ほどお話がありました。融資あっせんという話も出ました。でも、融資あっせんは、何度も言いますが、あくまでも救済策です。しかし、ここまでひどくなってしまったら、経済政策は１年でも２年でも、区民経済、区内商店街が盛り上がる。そして、もしそれがかなわないならば、何とか区民負担が少なくなるような対策も、経済対策の一環として、私は考えてほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":294,"id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公衆トイレを、ぜひ洋式に変えてほしいという要望ですとか、車椅子の方が使えるトイレがなくて困ったという要望をいただいています。そういう中で、車椅子の方たちも出られるまちづくりというのが求められていると思うのですけれども、誰でもトイレを増やしていくということで改修が進められていくのか、その点についてもお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"１つは公園の中にある公衆便所が１２カ所あります。今の駐輪場と同じような形態で併設している箇所が４カ所、あわせますと１６カ所です。このようなところは、その施設の改修や公園の改修などを踏まえながら、今後あわせて検討していくこととしています。","voiceIndex":296,"id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点をお聞かせください。１つは、その事務所に車椅子対応トイレがないということが大問題で、これはぜひ区からも言っていただきたいと思っているところです。その点が２つ目です。児童遊園も２０カ所中１カ所しか誰でもトイレはないという状況なので、私は計画的に公衆トイレ、公園トイレに誰でもトイレを設置していくということで進めていただきたいのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"全体的な公園の中のトイレですけれども、やはり公園の整備をする中で一緒に整備するということが基本となっています。これは単体の整備もありますけれども、公園の中の配置経過も含めて検討するということで、そのような考え方でやっていきたいと考えています。","voiceIndex":298,"id":"exchange-124"},{"speaker":"いながわ委員","kind":"質問・要望","question":"お願いします。そういった部分で、港湾６区というのですか。何で４０歳なのかという理由が、歯周ポケットができるとか、加齢というのですか。その予防、成人病にも予備軍があるわけでありますから、心筋梗塞にしても３０代で発症するケースもあるので、そういった部分も含めて、何歳からやってくれとか、そういう議論ではなく、そういった幅広い観点の中でお考えいただければと思いますが、いかがでしょうか。","respondent":"川島健康課長、佐藤保健予防課長","answer":"この辺もいろいろな状況がありますので、検討させてはいただくのですけれども、今のところは、これをこうしますと申すことはできないのですが、よろしくお願いいたします。今回もエボラ出血熱の話題を受けまして、また緊急にテーマを変えて、そういった喫緊の課題についても連絡会議を持っているところです。これからも連携をとりながら、防疫に努めてまいりたいと考えています。","voiceIndex":302,"id":"exchange-125"},{"speaker":"いながわ委員","kind":"質問・要望","question":"感染症に関しては、本当に連携をとっていただきたい。先ほど、別に受診率どうこうの議論ではなく、それは今後しっかりとやっていく。私の知り合いでも、数人で大変恐縮なのですが、品川区でこういうことをやっていると言ったら、本当にお金を払ってでもやりたかったので、感謝しているという方もいらっしゃるので、それをどう周知させるかというのは、品川区のほうでしっかりと進めていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"しかしながら、閉鎖、廃止工場につきましても、こちらで通知はありますけれども、どうしても移転しなければならないとか、そういう理由よりも、高齢になってしまって、次の世代になかなか継続できないということが多いと思われます。","voiceIndex":305,"id":"exchange-126"},{"speaker":"いながわ委員","kind":"質問","question":"高齢もそうなのですけれども、逆に周りの住民のパワーに押し切られてしまうとか、そこから苦情が来たらもう動かざるを得ない、何とかしてください。そこまではできない。その辺がものづくりになるのか、どういう形になるのかわからないのですけれども、もしそういうバックアップ体制があれば、これから先お考えかどうかというのを含めてお聞かせください。","respondent":"藤田都市環境事業部長、山崎ものづくり・経営支援課長","answer":"そういう中で、地域とうまくやるための施策、やはりこれは重要なことだと考えています。これからも、お住まいの方、そして工場を継続する方々の間に立ちながら、よりよい施策については検討していきたいと考えています。区役所の周辺については、工場アパートも持っていますので、今年度に入って、工場アパートを転用して創業支援センターに入っていただいているようなこともやらせていただいております。","voiceIndex":307,"id":"exchange-127"},{"speaker":"いながわ委員","kind":"質問・要望","question":"時間もないので、区長もよく言われている住工商バランスのとれた品川区という部分をおっしゃっています。いつまでも住み続けられるまち品川であって、しかも、いつまでも何かを生み出す力のある品川区にしていただきたいと思いますので、今後ともバランスのとれた産業支援をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-128"},{"speaker":"たけうち委員","kind":"質問","question":"私は、成果報告書の１４４ページの任意予防接種、それから、１４５ページの胃がんリスク検診でお伺いします。初めに、３２ページに、任意予防接種のほうですが、高齢者肺炎球菌ワクチンが、３２ページに、平成２５年度は２,２３８件と載っておりますけれども、この額が全部まざっているものですから、まずは、高齢者肺炎球菌ワクチンの決算額が幾らになるのか。","respondent":"佐藤保健予防課長","answer":"肺炎球菌ワクチンの決算額です。高齢者肺炎球菌ワクチンに関しましては、平成２５年度決算額で６９９万６,１９１円となっております。執行率については、後ほどお答え申し上げます。","voiceIndex":312,"id":"exchange-129"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。約７００万円ということで、決算額を受けとめました。もうご案内のように、第３回定例会で定期接種のための補正がありまして可決されたということで、定期接種になったわけです。今までは、都などから、助成のときに補助があったのかもしれないのですけれども、今度、財源がどうなるのかということについて教えてください。","respondent":"佐藤保健予防課長","answer":"今年度につきましては、１００歳以上の方が５年刻み以上の上積みになりますけれども、基本的にはその方々は１００人程度ですので、毎年このぐらいの金額が計上されていくものと考えています。","voiceIndex":314,"id":"exchange-130"},{"speaker":"たけうち委員","kind":"質問・要望","question":"定期接種のところを見ても、年間かなりの金額が出ていく中で、そういう面では、財源について、２３区で肺炎球菌について、４,０００円を自己負担してもらうということでお話しされたと伺っています。この財源を、制度が変わらなければしようがないと思うのですけれども、そういう財源について、何か国とか都に対して求めていくようなことが、考え方としてあるのかどうかということを教えていただきたいです。","respondent":"佐藤保健予防課長","answer":"続きまして、６６歳など、今年対象者でない方々についてのご要望です。今年度１０月から開始された制度ですので、多少わかりづらいということで混乱もあります。そういったことで、ご質問ですとか、お問い合わせのお電話やメールなどをいただいているところです。","voiceIndex":316,"id":"exchange-131"},{"speaker":"たけうち委員","kind":"質問","question":"そういった声を踏まえて、今回、定期接種になったわけなので、すぐというわけにはいかないかもしれないのですけれども、５年スパンで見ると、多分、予算としてはそれほど変わらない状況になるのかと思います。定期接種は定期接種として、６５歳以上の全員を対象にするような助成を、どこかで状況を踏まえて復活させてもらいたいという声も一方であります。それについてのご見解を教えてください。","respondent":"佐藤保健予防課長","answer":"いきなり３,０００万人の方々が打つというのは、なかなかワクチンの供給量というところも難しかろうと思いますので、私どもといたしましては、ワクチンの供給量、それから、接種率などの情報を収集いたしまして、検討していきたいと考えています。","voiceIndex":318,"id":"exchange-132"},{"speaker":"たけうち委員","kind":"質問","question":"状況をよく注視していきたいと思います。次の胃がんリスク検診ですけれども、いわゆるピロリ菌検査ということで、実は私も、今５１歳なのですけれども、５０歳のときに案内が来まして、受けましたら、ピロリ菌がおりまして、薬を飲んで退治できたということで安心しているわけです。そういった面で、５０歳ぐらいでもいるということと思います。これを５０歳以上にされた理由について教えてください。","respondent":"川島健康課長","answer":"こちらの年齢設定のご質問ですが、ピロリ菌の陽性率が高い、リスクの高い年齢層に特化したということで、５０歳以上と設定しています。","voiceIndex":320,"id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問","question":"たしか、事務事業概要を見ますと、５０代の方で受けた方の２５％、４人に１人の割合でピロリ菌がいた。例えば、そういう面で言えば、早めに検診をすることで、ピロリ菌がいなくなれば、除菌できれば、医療効果も非常に増えてくるわけなので、そういう面では、そういうことについての考え方、簡単に言うと、もう少し若い世代からこういうのをやったらどうかと思うのですけれども、ご見解を教えてください。","respondent":"川島健康課長","answer":"こちらのリスク検診につきましては、ほかのがん検診と同様に、がん年齢と言われるような年代にターゲットを絞って、今現在やっているものです。今の年齢で受診者も少しずつ伸びておりますので、様子を見させていただいてから、その辺を検討していきたいと考えております。","voiceIndex":322,"id":"exchange-134"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は１４９ページ、環境対策費に関連して質問します。その前に、１つ要望ですけれども、区民健康づくりプラン品川推進経費がありますけれども、この中に、ぜひ検討していただきたいといいましょうか、お願いしたいのが、かつて文部科学省のモデル事業として、「早寝早起き朝ごはん」というのを品川区でもやりました。進入角度を３度とした。今のところ、航空機増便に対する現状はどうなっているでしょうか。","respondent":"三ツ橋環境課長","answer":"騒音については、今までに騒音を経験された方、そして未経験の方、いろいろありますので、そちら側にも、しっかりと国が責任を持って説明してほしいということを要望しております。そのほか、例えば、新滑走路までにほかの飛行ルートの考えはないのかなど、要望してまいります。","voiceIndex":325,"id":"exchange-135"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、品川区のみならず、大田区、世田谷区、近辺の地方自治体、当然東京都もそうだけれども、これからそういうところと十分に連携なり、打ち合わせをしていく中で、例えば、ルートを変えていただくことが一番いいのだろうけれども、そういうことも含めて、さらに具体化し、前進していくと思うのですが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"委員おっしゃられましたように、関連する区とともに、国に対して要望をしてまいりたいと思います。機能強化に関しましても、まだ今のところルート案ですけれども、またいろいろなことを考えながら、進めていきたいと考えています。","voiceIndex":327,"id":"exchange-136"},{"speaker":"伊藤委員","kind":"確認","question":"確かに私たちも説明を受けたときに、「これは案なのですね」ということを、担当者に相当確認しました。改めて、濱野区長にお伺いしたいのが、こういうことを目の前にして、品川区としての態度、それからほかの区との同調、東京都の取り組みについて、どうお考えでしょうか。お答えください。","respondent":"濱野区長","answer":"この問題であります。増便そのものに反対するわけではありませんけれども、それによって影響を受けることについては、品川区として物を言わなければいけないと考えています。","voiceIndex":329,"id":"exchange-137"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":107434,"voices":332}},{"id":"h26-20141111-4","meetingId":"h26-c-settlement","date":"2014年11月11日","dateIso":"2014-11-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２５年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"私は、土木費から１５９ページの駅周辺等放置自転車対策事業、１６５ページの区民の自主的なまちづくりへの支援、そして、１６４ページの景観まちづくり推進事業の確認をさせていただきたいと思います。第一に、駅周辺等放置自転車対策事業です。現在、自転車利用のマナー向上のために、どのような対策に取り組んでいらっしゃるのでしょうか。","respondent":"田口交通安全担当課長","answer":"今現在やっておりますのは、まちの方、また警察、関係団体等を含めました、放置自転車追放のキャンペーン、こういった啓発活動を行っております。放置自転車抑止ということで、警備員、シルバー人材員を雇いまして、放置の防止活動を行っております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"放置禁止区域の２３駅のうち、西小山の事例を中心に確認させてください。西小山駅周辺の品川区と目黒区の区境の十字路において、無秩序に自転車が放置されている個所があります。西小山駅は品川区と目黒区の区境ですから、駅周辺は両区の緊急自動車が通過します。現在、駐輪駐車対策協議会等に、目黒区や東急電鉄に出席をいただいたり、合同での撤去、キャンペーン等は実施しているのでしょうか。","respondent":"田口交通安全担当課長","answer":"個々に要望等がございましたら、現場に出向きまして広報啓発活動を行っているところです。ご指摘の目黒区との境ですが、品川区と大田区もそうでありますけれども、お互いに境ということで、連携を密にしながら、放置自転車防止に取り組んでいるところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"再度確認させてください。西小山駅においての目黒区との連携について、もう少し詳細を教えていただけますでしょうか。","respondent":"田口交通安全担当課長","answer":"西小山駅ですが、隣接です。定期的にということではございませんが、適宜、目黒区とは連携を図りながら自転車の放置防止活動を行っているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"再度質問します。適宜ということなのですけれども、それは、個別の要望があった際に、という意味でよろしいのでしょうか。","respondent":"田口交通安全担当課長","answer":"先ほども言いましたように、定期的にはございませんが、例えば、放置自転車が目に見えて多くなったとかという場合に、お互いに協議をしています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"今後なのですけれども、私は本日も現場を確認してまいりましたが、まだ放置自転車が残っている状態でした。例えば、このような既存の品川区と目黒区の連携のコミュニティなどを生かして、地域の課題に取り組んだり、区民の自主的なまちづくりの支援へつなげていく可能性について、区としては、どのようにお考えでしょうか。隣接区との連携強化のための具体的なお考えを、お聞かせください。","respondent":"中村都市計画課長","answer":"こういった地域をよくしていきたいという活動に対しても、支援をしてまいりたいと考えております。これは制度についてです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"自主的な区民の発意により、まちをよくしていきたいという考えを持った人や団体に対して、区として助成するということなのですけれども、例えば西小山のような、品川区民と目黒区民の共同の団体についても、支援の制度は整っているのでしょうか。","respondent":"中村都市計画課長","answer":"事務費ですとか、あるいは、会が独自に勉強するために講師を呼んだりする費用を見込んでおります。勉強会などを開きたいといったときには、法律ですとか、あるいは不動産、まちづくりに関するふさわしい専門家を派遣するといった支援も行っております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"横山委員","kind":"質問","question":"最後に、景観まちづくり推進事業について、簡単に質問します。平成２３年４月に、品川区景観計画の運用が開始されました。品川区は、利便性、機能性に優れ、それぞれの地域によって駅舎やにぎわいなど、多様な個性、特性があるため、全体として非常にバランスがとれており、誰もが愛着を感じやすいまちではないでしょうか。こちらの景観特性と、現在の課題について、教えていただけたらと思います。","respondent":"中村都市計画課長","answer":"特に最近では、商業地域の中に住宅が建ったり、これも法律上だめというわけではございませんけれども、地域の中で、この町並みに溶け込むような景観に関する色づかいですとか、あるいは建物の形ですとか、そういったものに対して指導を行っているところです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"二つ目が、１６１ページ、道路バリアフリー事業、また１６５ページ、都市計画費、やさしいまちづくり整備費、駅エレベーター整備助成、バリアフリーの観点から伺います。１点目のゾーン３０について伺います。その地域を教えてください。３０km区域は、ここからここまでという東京都公安委員会の規制標識の数、そして品川区道路課として施されましたゾーン３０という路面表示の数を教えてください。","respondent":"田口交通安全担当課長","answer":"ゾーン３０のご質問です。設置されている地区は７地区あります。その中で、ゾーン３０の標識が設置されている個所は４５カ所となります。それから、路面表示につきましては３７カ所となります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"ゾーン３０の定義というか、根拠を教えていただきました。ちなみに東京都内では１０３カ所指定されていて、平成２６年度中に、あと５９カ所が指定されると、警視庁のほうでは言っております。これらの地域で、もともとこの生活道路は何km制限だったのか教えてください。","respondent":"田口交通安全担当課長","answer":"ゾーン３０を設定する前につきましては、法定速度の６０kmとなっておりました。","voiceIndex":21,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"交通弱者とされるような方を守るように設定したことが伺えます。二、三年前に警察庁がゾーン３０の導入に踏み切ったときに、たしか、ナビのメーカーにそのような情報提供をするというようなことが書いてあったような気もするのですけれども、これが行われているのかどうか、教えてください。ゾーン３０の効果について、何か聞いていることがあれば教えてください。","respondent":"田口交通安全担当課長","answer":"カーナビの関係ですが、実際にゾーン３０がなかなか住民に周知されていないというのが現状です。その周知方法といたしまして、警視庁のほうでは、カーナビの製造業者にゾーン３０の設置個所の情報提供をいたしまして、現在、カーナビで表示できるようにしております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"若干、質問の内容とご答弁が異なっていたようなのですけれども、ゾーン３０の効果について、何か聞いているところがあれば教えてください、というのが１点。昨年１２月、こんな報道がありました。タイヤがついているので、３人で移動できる。前任の交通安全担当課長も、「委員ご提案のとおり、まだ知られていないですので、警察と連携を取りながら周知を徹底してまいりたい」とお約束をしていただきました。","respondent":"田口交通安全担当課長","answer":"先ほど委員がおっしゃいましたように、前任から、やはりゾーン３０が周知されていないということがありましたので、私のほうも、区内の四つの警察署の交通課長にお会いして、警察だけがやればいいという話ではございませんので。","voiceIndex":25,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ、進めていただきたいと思います。先ほど、力強いご答弁をいただいたので、これは強い要望としてお伝えします。２点目に移ります。一つ目が、新馬場駅南口のエレベーター設置について、伺います。新馬場駅南口のエレベーターの設置についてですが、これは何度も取り上げさせていただいて、我が会派の私の前任者の山路議員からも、一般質問でこれを取り上げて要望しています。","respondent":"中村都市計画課長","answer":"新馬場駅は、過去に二つの駅が一つになって、北側の出口と東側の出口が非常に距離があるということで、利便性のためにも、何とかエレベーターの設置をしてくださいというお願いを、今までしてきたところです。今後も引き続き強いお願いをしてまいりたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本当によろしくお願いいたします。今ご答弁がありましたように、北馬場、南馬場という二つの駅を、山手通り、目黒川と二つ越えてつないである駅であって、バリアフリー新法でワンルート確保と言われていますけれども、実質、二つの駅が並んでいるわけですから、どうしても一つでは足りないというところはあります。次に、バリアフリーでもう一つ、すべり転倒防止の観点からお伺いします。","respondent":"中村都市計画課長","answer":"今、検討中の大井町駅周辺地区バリアフリー計画では、不特定多数の方が利用する建築物と、その建築物を結ぶ経路について、バリアフリーを図っていこうという計画です。","voiceIndex":29,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当然そういうものは盛り込んであるということでしたけれども、以前の答弁の中では、区の中にも、そういった滑り値を測るような機械があるというようなご答弁もありましたが、平成２４年に指針が出たような、この推奨値といったものが具体的に活かされているのかどうかというところを、もう一度ご答弁いただきたいと思います。","respondent":"中村都市計画課長","answer":"こちらにつきましては、実際にこのバリアフリーの計画の策定にあたりまして、まちを歩いて点検をしまして、安全性の確認をしていきたいと考えています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"段差の解消であるとか、例えば点字ブロック、点状ブロックの設置であるとか、エレベーターの設置、そういったところは、多分目に見えるところだと思うのですけれども、細かいことですけれども、高齢者、障害者の平坦地での転倒防止についても、しっかりと計画の実施に入れていただきたいと思いますが、最後にご答弁いただきたいと思います。","respondent":"中村都市計画課長","answer":"バリアフリーの策定につきましては、実際に身障者の団体の方から意見を聞き、また当事者である身体障害者の方にも、実際にまちを歩いてもらって点検などをしています。引き続き、安全性について、総合的な観点から計画を進めてまいりたいと思います。","voiceIndex":33,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"本日は、成果報告書の１６０ページの街路灯管理費、そして１６１ページの補助１６３号線の整備について、伺いたいと思います。街路灯管理費について、お伺いします。街路灯建替事業ですが、予算書では、５００基で約８,８００万円に対して、決算書では、５２５基で約８,３００万円と、１基の値段が下がっているように見えますけれども、それについて伺いたいと思います。","respondent":"稲田道路課長","answer":"街路灯です。区内には街路灯は１万３,４８５基あります。これを、実施計画に基づきまして、毎年、約５００基を建替えをやっているです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"わかりました。省エネの話になるのですけれども、以前に、品川区では、区道の街路灯を順次に省エネ型街路灯として、水銀灯から蛍光灯に切り替えていくという記事がありました。そこで、ＬＥＤの街路灯について伺います。今現在、ＬＥＤも進化してきていると思いますけれども、予算書では、平成２４年４月では１９基であります。そしてまたあわせて、今後の方向性も伺いたいと思います。","respondent":"稲田道路課長","answer":"街路灯のＬＥＤ化について、お答えいたします。ＬＥＤ化は、非常に消費電力も少なく、また明るさも十分にあるというところで、我々も随分前から検討はしてまいりました。","voiceIndex":38,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、今後は全てＬＥＤ化という形になるのでしょうか。今の水銀灯、蛍光灯、ＬＥＤの現状での数がわかりましたら、お願いしたいと思います。","respondent":"稲田道路課長","answer":"街路灯の数から申し上げます。１万３,０００基ある街路灯ですけれども、すみません、ちょっとお待ちください。数字は調べまして、後ほど、ご報告いたします。","voiceIndex":40,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"これからは全てＬＥＤ化ということでよろしいのでしょうか。","respondent":"稲田道路課長","answer":"大変申し訳ございません。基本的にはＬＥＤ化ですが、その設置場所によっては、まぶしいところもございまして、近隣の皆さんのそういうご意見のあるところもありますが、基本的にはＬＥＤ化でやっていくです。","voiceIndex":42,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"私からは、交通安全と犯罪防止を図るための照明の明るさについて、伺いたいと思います。特に公園ですが、照明の調整、または増設するような対策が必要ではないかと思いますが、いかがでしょうか。そしてまた、明るさを弱くする理由について、お聞かせください。","respondent":"多並公園課長","answer":"ただし、地元の皆様から、例えば、若者が集まって夜中にうるさいとか、いろいろな苦情なり、その地域の状況がありますので、そのような場合は、その個々の状況に応じまして、１時期、電気を消してみたり、時間に応じて消したりとか、いろいろな形で。","voiceIndex":44,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"平成２５年１年間では、犯罪件数に関しては３,６３８件と、まだまだ多いように思いますので、ぜひとも、未然に防ぐという形で進めていただければと思います。次に、補助１６３号線の整備について、伺います。東急大井町線交差部整備の詳細設計委託が、予算額１億２,０００万円ですけれども、決算額では約６,０００万円と差がありますが、その理由について、お聞かせください。","respondent":"稲田道路課長","answer":"補助１６３号線、区役所前のガード下区間の詳細設計です。これは東急電鉄に委託をしておる設計です。当初、協議している中での金額で進めておりましたが、最終的に、東急電鉄がその決算額で請求してきたです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"最後に、今後ですけれども、百反の交差点から西品川一丁目地区では、市街地再開発の事業として、道路整備が進められてきていると思いますが、今後、未整備区間におきましては、いつごろ始められるのか。そして、道路の拡幅工事はされるのか、お伺いしたいと思います。","respondent":"稲田道路課長","answer":"１６３号線です。大崎から大井町を結ぶ主要な幹線道路というところで、今後、順次に進めていきたいところですが、まずは、このガード下区間をやり遂げて、大崎駅のほうに向かって整備ができればと考えております。","voiceIndex":50,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"私からは、１６５ページの特定整備路線沿道まちづくり推進費に係わって、補助２９号線道路中止と、沿道まちづくりも、伺いたいと思います。不燃領域率を高めるには、一定以上の面積を有する公園と６ｍ以上の道路の合計面積と、建築面積の総数のうち耐火建築物等が占める割合ということですが、この中で、なぜ補助２９号線道路建設なのか、伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"したがいまして、整備後に何％になるかということですけれども、目標数値として７０％、不燃化特区で補助２９号線沿線を指定しておりますけれども、７０％を目標にやっているということで、沿道の不燃化を含めての数値ということで、ご理解いただければと思います。","voiceIndex":53,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"このことを認めるのか、ということを伺いたいと思います。補助２９号線道路でなくても、高めることはできます。このことを認めるのか、伺いたいと思います。私は、常々、首都直下型大震災の防災対策は、補助２９号線ではない別の方法があると述べてきましたけれども、なぜ不燃領域率を高めるのに、補助２９号線の建設を選ぶのか、改めて伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"補足ですが、補助２９号線につきましては、そこだけの不燃領域率が目的ではなく、特定緊急輸送道路という位置づけがありますので、災害時に、例えば消火活動、物資の搬送も含めた、そういった活用も、当然主眼にありますので、その辺も含めて。","voiceIndex":55,"id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"結局、補助２９号線が防災対策だという根拠に不燃領域率を上げながら、それが根拠だという説明ができないわけですね。そうしたら、今度は根拠に不燃領域率です。常々、防災対策は別の方法があると訴えてきましたが、補助２９号線でなければ、不燃領域率７０％は達成しない、これは間違いだということを認めますか。","respondent":"中村都市計画課長","answer":"補助２９号線は、防災に対して非常に有効であるという認識を持ってあります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"そもそも、不燃領域率という指数が、どこまで首都直下型大震災の被害を防ぐ根拠になるのかということを伺いたいと思います。そこで、不燃領域率という指数の前提を伺いたいと思います。前提となる風向き、風速、火災の発生有無、住民の消火活動の有無、道路上の車両の有無、住宅棟数の有無、品川の実際のまちなのかどうか、それぞれ前提を伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"これを否定するだけの論拠は、もちろん品川区にはありませんし、これを参考にして進めていくことが最も有効な手段だと理解しておりまして、こういった事業を展開していると、これが回答です。","voiceIndex":59,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、不燃領域率について、風向き、風速、火災の有無、住民の消火活動の有無、道路上の車両の有無、住宅の倒壊数の有無、品川の実際のまちが前提なのか、ということです。つまり、こうした前提はないということですか。","respondent":"寺嶋木密整備担当課長","answer":"こういった研究の結果は、もちろん品川区を直接モデルにしてやったものではないということは、おそらくこれは間違いないと思いますけれども、通常の想定され得る状況、または想定外も含めたもの全てを入れて一定の検証をされたものと理解しておりますので、当然。","voiceIndex":61,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"なかなか認めたがらないのですけれども、要するに、不燃領域率というのは、単純に空地の割合だけであって、先ほど指摘したものは前提にないということです。単純に空地がどれくらいあるかだけで、補助２９号線をつくっても、その道路の上には１台も車がない空地として計算する。この不燃領域率が、どうして首都直下型大震災の品川区のまちの防災対策の根拠になるのか、伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"これも繰り返しの答弁で申し訳ございませんが、先ほど申し上げましたように国交省の手法をもとに、品川区も全国と同じように、こちらの数値を最大限尊重して事業を進めているということが根拠です。","voiceIndex":65,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、答えられていないのですよね。つまり、防災を考えるときに、重要な要素がない前提で、どこが燃えないまちの根拠になるのかと伺っているんです。しっかりご説明いただきたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"不燃領域率の研究につきましては、国も総力を挙げてやったものだと理解しておりますので、これが根拠でないというところが、逆にちょっと理解できないところです。これを根拠に、これからも進めていきたいと考えております。","voiceIndex":67,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"国が言ったから根拠だと言うのが、全く根拠がないと思うのです。私が言っているのは、不燃領域率とは、実際のまちや実際に起こる風や車も倒壊もないと、これで防災の根拠になるのかと伺っているのです。しっかりご説明してください。","respondent":"中村都市計画課長","answer":"そういったシミュレーションの方法からいきますと、やはり建物は、地震がきたときには倒れない、そしてまた、燃えない、これがシミュレーション上、燃え広がらないまちとして有効な手段であるということについて間違いはないと考えています。","voiceIndex":69,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"実際に、今伺っても、防災とはごまかしだったこと、延焼シミュレーションでも、不燃領域率でも、どちらも燃えないまちになるという防災の根拠にはなりません。そのことを何で認めないのか、改めて伺いたいと思います。これでどうして、燃え広がらないまちを実現、命を守る道とは、私は荒唐無稽の根拠だと思いますので、こうした計画はやめるべきだと思いますけれども、いかがでしょうか。","respondent":"藤田都市環境事業部長","answer":"そういう中で、特定整備路線、都市計画道路だけでなく、燃えないまちをつくる、燃えないためには、不燃化だけでなく、耐震化についてもあわせて進める、そのことをやることで、しっかりとした防災性の高いまちづくりを進めていきたいと考えています。","voiceIndex":71,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"３.１１では震災関連死も大きな問題になりました。沿道についても一言伺いたいので次に移りますが、補助２９号線の沿道についてですけれども、用途容積率の変更に向け、今年１月ごろにアンケートが実施されましたが、その後のスケジュールがよくわかりません。６年後ですが、現状と、沿道の今後の都市計画審議会などスケジュールについて、現状がどうなっているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"２０２０年までに間に合うのかですが、沿道のまちづくりにつきましては、特に用途地域の変更で不燃化を誘導するということにつきましては、用途地域の変更をして、その後、実際に建て替わることを待って誘導していくものですので。","voiceIndex":73,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話を聞きましたら、結局、沿道はできないということですよね。これで、またどうして防災のための道路なのかと改めて思います。住民も強く反対しております、まちを壊す道路計画は、ぜひやめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"１６５ページ、しながわ水族館運営費、１５９ページ、交通安全啓発費、よろしくお願いいたします。ここで注目すべきなのは、アジアの水族館のベスト２５なのですけれども、何としながわ水族館が２０位にランクインしておりました。ここで質問なのですけれども、平成２４年度は、設備改修費等工事は、照明とメンテナンスとお聞きしました。わかりましたら、この２点、よろしくお願いいたします。","respondent":"多並公園課長","answer":"この原因の一つであり得るのは、すみだ水族館が、ちょうど平成２４年のはじめにオープンしたということで、そこで今後の入館者数のアップに向けて、いろいろな改善をしていかなければいけないということで、平成２５年度、運営改善の委託ということで。","voiceIndex":77,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"いろいろさまざま本当にイベントも、さかな君というのもありましたし、取り組んでいらっしゃったんですけれども、今、お話を聞きましたけれども、ここでのランキングは世界なんです、日本の方もそうなんですけれども、世界の方ということで、海外からいらっしゃる方とか、また在住の方とか、今入っていなかったと思うのですが、そういう方へのＰＲが何かありましたら教えてください。","respondent":"多並公園課長","answer":"国際化への対応です。今年度につきましては、まずは国際化への対応ということで、新しく英語、中国語のパンフレットをつくりました。は羽田空港の国際線ターミナルにパンフレットを置いていただいております。","voiceIndex":79,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"外に向けての発信をいろいろお聞きして、すごい努力をなさっているのですけれども、これは口コミですので、これは、いらした方の評価なのですよね。館内の外国の方への、例えば表示とか、そういうことに関してお願いします。","respondent":"多並公園課長","answer":"館内につきましては、現在、パンフレットという形の表記が、国際対応です。今後ですけれども、外国の方が来られたときに、館内を見て、魅力がわかるような形の説明板等、もう少しいろいろな工夫ができないかと考えています。","voiceIndex":81,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"この口コミが全てではないのですけれども、やはり学ぶべきものは学んでいってはどうかと思います。情報によりますと、日本の方の評価はとても厳しかったそうです。２０２０年のオリンピック・パラリンピックに向けて、これは品川区の目玉施設になるのではないかと、今後とても期待したいと思いますので、このような評価を受けてのご見解、または最後に今後の方向性などを、もう１度お願いいたします。","respondent":"多並公園課長","answer":"特に、今ご指摘もございましたような国際化への対応が、まだまだもう少しやれることがあるのではないかということで、ただ多言語化というのは、それをどのようにするかなかなか難しいところですけれども、何とかそれを実現しながら。","voiceIndex":83,"id":"exchange-037"},{"speaker":"吉田委員","kind":"意見","question":"時間がなくなってしまって、交通安全の啓発費なのですけれども、一つだけ聞きたいのですけれども、区では啓発に関していろいろやっているのですけれども、やはり学校の生徒たちのマナーがとてもできていないと思うのです。それは、いろいろな教育もなさっていると思うのですけれども、その１点、お願いします。","respondent":"田口交通安全担当課長","answer":"学生に対しましては、スタントマンを使いましたスケアード・ストレートという安全教育、実際に事故現場を再現する、危険を直視するという意味で、非常にインパクトのある教育、その他各種安全教育を行っております。","voiceIndex":85,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"すみません、時間がないので、また詳しく教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-039"},{"speaker":"松澤委員","kind":"質問・要望","question":"何点か、お聞きしたいと思います。１５９ページ、１項土木管理費、１目土木総務費の中で、駅周辺等放置自転車対策事業に関連しまして。そんな状態で、たびたび各委員から質問があったのですけれども、あそこの不法駐輪自転車がなくなったのです。これはどうしたのか、現状はわかっていると思いますので、現状認識をお知らせいただきたいと思います。","respondent":"田口交通安全担当課長","answer":"委員ご指摘のとおり、戸越銀座は、いっときひどい状態でございました。ただ、ここも商店の方々のご協力もいただいて、バリケードといったものをつけたり、また、我々のほうで計画的に撤去活動を行った成果だと認識しております。","voiceIndex":89,"id":"exchange-040"},{"speaker":"松澤委員","kind":"質問・要望","question":"バリケード、目立つ形でできていて、あれはなかなかいいですよね。商店街に聞きましたら、「私たち役員会で諮って自費でつくったんですよ」というお話を伺いました。こういういい事例を、品川区のほかに広げていくべきだと思うのですが、ほかでの対策に、これが使えそうなところはあるのでしょうか、その辺をお聞きしたいと思います。","respondent":"田口交通安全担当課長","answer":"やはりその場所ごとにケース・バイ・ケースという形にはなると思いますけれども、いい施策というのは、今後ほかの場所にも広げていきたいと考えておりますので、各駅周辺等を、もう一度よく確認をしながら、もし生かせる場所があれば生かしていきたいと考えております。","voiceIndex":91,"id":"exchange-041"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは大ヒットだと思いました。２点目にいきます。１６５ページ、４項都市計画費、１目都市計画総務費、特定整備路線沿道まちづくり推進費、補助２９号線の問題を少し聞きたいと思います。１２月２日には、近隣説明会が開かれるということですけれども、平成３２年度完成目途ですから、残りの区間の事業認可というのは、今はどのような形になっているのか、お知らせいただきたいと思います。","respondent":"中村都市計画課長","answer":"残りの２区間の事業認可につきましては、東京都では、今年度中に取得をする方向で、今、動いているです。","voiceIndex":93,"id":"exchange-042"},{"speaker":"松澤委員","kind":"質問","question":"残り２区間のうち、特に大原交番から補助２６号線までは戸越公園の駅の高架化の問題が含まれているので、今年中に事業認可を取るということは、戸越公園の駅が高架化されるという意識でよろしいのでしょうか、それを聞きたいと思います。","respondent":"中村都市計画課長","answer":"委員ご指摘の踏切につきましては、高架化は補助２９号線の事業認可とはまた別になりますので、今回の事業認可は、補助２９号線の道路の事業認可です。","voiceIndex":95,"id":"exchange-043"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうすると、事業認可になったその認可の過程では、線路が道路の上を通るということでの認可なのでしょうか。それとも、将来的には、ここは高架になるけれども、今は道路を先に認可するということなのでしょうか。その辺、大事なことなので、しっかり答えていただきたいと思います。","respondent":"中村都市計画課長","answer":"踏切の高架につきましては、道路整備に伴って、地元の熱い意向ですので、区としても、都と連携してこれから協議を引き続き進めていきたいと考えております。","voiceIndex":97,"id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。そうしますと、今年中には、一本の線になる事業認可ができるということですけれども、あと６年の間につくらなくてはいけない。そうすると、もうそろそろ事業認可を取った先行２区間では、用地買収の話、あるいはもうそういうことに入っているのでしょうか。その辺のところをお知らせください。","respondent":"中村都市計画課長","answer":"委員ご指摘のとおり、用地買収の交渉に入っております。もう既に、事業認可が通った後に、用地説明会という用地買収のための説明会を行っておりますので、その後、速やかに入っているです。ただ、その買収率については、情報が入ってきておりません。","voiceIndex":99,"id":"exchange-045"},{"speaker":"松澤委員","kind":"質問・要望","question":"補助２９号線は、やはり防災道路としては必要な路線だと思いますので、しっかりと整備をしていただきたいと思います。ただ、区民の方はどうしてもそこに残りたいという方もいらっしゃいますので、その辺は、品川区はしっかりと東京都と連携しながら、まちづくりを進めていただきたい。決意をひとつ聞きたいと思います。","respondent":"中村都市計画課長","answer":"この特定整備路線補助２９号は、東京都が進める事業ではありますけれども、やはりこれは区のまちづくりに関して非常に重要なことだと認識しております。引き続き、商店街、あるいはこの沿道の町並みのにぎわいを保っていけるように、区としても努力をしていきたいと考えています。","voiceIndex":101,"id":"exchange-046"},{"speaker":"松澤委員","kind":"確認","question":"次にまいります。５項建築費、１目建築行政費、建築確認申請６０件という数字が出ています。民間は１,１０４件でしょうか、大分民間のほうが多くなってきました。確認申請そのものが、なぜ民間のほうが多くなっているのか。何回か同じような質問が過去にもあったと思うのですが、お聞きしたいと思います。","respondent":"鈴木建築課長","answer":"確認申請の、民間の推移、増加ということのご質問です。民間の確認検査機関につきましては、平成１０年の法改正によって、それまで区の建築主事が確認申請をおろしていたものが、民間でも確認が取れるようになった。","voiceIndex":103,"id":"exchange-047"},{"speaker":"松澤委員","kind":"確認","question":"確認申請が減ってきている、大変な権限が付与されてやっているということですけれども、これは専門職ですから、職員をある程度確保していないといけないと思うのですけれども、それを心配しています。それともう一つ、確認申請の前に建築相談がありますよね。これが品川区で２万幾つという数字が出ていますけれども、これに対する職員の対応をどのようにしているのでしょうか。","respondent":"鈴木建築課長","answer":"先ほど民間開放の話の中で、説明し忘れたのですけれども、そもそも民間開放されたわけですので、建築の内容申請につきましては、民間の建築士、適合判定資格者になりますけれども、こちらの方が判断していただければいいわけですが、内容的に非常に高度な判断。","voiceIndex":105,"id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"よくお話をしていただいて、わかりました。同じく建築紛争調整事務、『建築紛争の予防と調整の手引き』というものがあります。これは大変よくできているのですけれども、これはどこで配られているのでしょうか。年間、どれくらい配っているのか、お聞きしたいと思います。","respondent":"中村都市計画課長","answer":"紛争の手引きですけれども、これは都市計画課の窓口にて配布をしています。大体、１年間で相談件数が１５０件くらいかと認識しています。","voiceIndex":107,"id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"これを見ますと、本当にいいことが書いてあるのですね。「建築主は、次のことに留意してください。説明に際しては十分な配慮と誠意を持って行ってください。最近、業者が大変ひどくなっています。このようなことで、住民の方が困って、あっ旋ということにいくと思うのですけれども、このあっ旋は一体、品川区全体でどのくらいあるのでしょうか。ちょっと時間がなくなったので、件数だけで結構です。","respondent":"中村都市計画課長","answer":"あっ旋につきましては、平成２５年度１件、そして平成２６年度今のところの実績で１件です。","voiceIndex":109,"id":"exchange-050"},{"speaker":"塚本委員","kind":"質問","question":"これは今後の見通しも含めた形で、ご見解を伺いたいと思います。それから、こういったもともとの土地建物の所有者がいて、売却をして、業者がそこに建て売りを２棟、３棟と建てて、それで新たな方がそれを購入する、こういうパターンの建築の中で、いわゆる除却工事助成というのは、この三者の中でどなたが受ける対象となるのか、この点についてお伺いしたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"実際に品川区のほうで今進めています、いわゆる除却助成につきましては、主に耐震化支援の側面と不燃化促進の側面と２通りあります。耐震化支援のほうにつきましては、木造の戸建て、アパートが対象になっておりますので、先ほどの店舗や町工場は該当しないです。","voiceIndex":112,"id":"exchange-051"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすれば、そこは基本的に新築ですから、耐震化も、耐火も進むということで、この政策において、除却助成は非常に効果のあるものではないかと思いますし、そういった意味でこの予算は、しっかり増額したものを執行できるように努力いただきたいと思いますけれども、その点についてのご見解を伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"予算の執行につきましては、決算の数字が、ご案内のとおり、残念ながら、必ずしも実績数が多いとは言い難いのですが、こういった事業を進めるにおきまして、例えば年度の後半に入って申請があったら予算がないので受けられないということではなくて。","voiceIndex":114,"id":"exchange-052"},{"speaker":"塚本委員","kind":"質問","question":"少し角度が変わりますけれども、こういった新築にあたって、区内業者がなかなか入りづらい、工事を受けづらいというようなところが一方であって、そこのところで、何かしらご見解、お考えがあれば一言お伺いしたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"ただ、先ほども申し上げましたとおり、除却に関しては、当然、今あるものが、例えば耐震面とか、不燃の関係で除却やむなしという場合につきましては、支援していきたいと考えておりますので、こういった事業展開になっているところです。","voiceIndex":116,"id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"１６０ページの道路下空洞調査委託と、道路下空洞・雨水管修繕というこの２点についてなのですけれども、これは平成２５年度から始まった事業でありますけれども、平成２５年度の結果としては、９カ所小規模な空洞があったということで、この成果報告書に出ております。それについては修繕も行っているということですけれども、どのような形で修繕をなされたのか、お伺いしたいと思います。","respondent":"稲田道路課長","answer":"道路下の空洞調査と、その対象について、お答えいたします。平成２５年度から３カ年計画で予定していますこの事業ですが、平成２５年度、３６kmを調査しまして、委員ご指摘のとおり、９カ所の空洞が発見されました。","voiceIndex":118,"id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"これは３年間通じて実証する事業と伺っておりますけれども、昨年度は９カ所ということだったので、時間がないのですけれども、この事業の評価を、一言だけお伺いしたいと思います。","respondent":"稲田道路課長","answer":"もっと大きなものが出るかと思ったのですが、比較的軽微なもので収まっていると感じております。空洞の対象、それから管理については、各管理者がそれぞれ責任を持って行っているというところで、各管理者のほうにも通知をしたところです。","voiceIndex":120,"id":"exchange-055"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、宅建ですとか、建売屋が改造してくるということになります。そこで質問をしますけれども、まちづくりの観点から、ここにいらっしゃる方は建設会社はよくご存じだと思いますけれども、もっとその下の基礎の部分で、区内にある中小零細の町工場とか製作所、この辺についてのご理解やお考えがありましたら、ご答弁をいただきたいと思います。","respondent":"鈴木建築課長、中村都市計画課長","answer":"品川区の耐震化促進計画、あるいはその上位計画であります耐震改修促進法という法律がございまして、この法律自体は、委員ご指摘のとおり、新耐震基準以前の基準、昭和５６年５月３１日以前に建った建物について。くぎ１本、ボルト１個つくるのも非常に難しい作業で、１,０００分の１mmといった単位で製作をされているご苦労があると思います。くぎも、少しでも曲がっていたらうまく打ち込みができません。","voiceIndex":123,"id":"exchange-056"},{"speaker":"原委員","kind":"意見","question":"１点だけ。この法律については、改正になって１年８カ月になって、この辺についての変更とか、また重点バランスが変わったかどうか、その辺だけお答えいただければと思います。","respondent":"鈴木建築課長","answer":"法律は平成２５年に改正されまして、１年程度たっております。診断の義務づけの対象になった特定建築物について、実情を調査しております。今この場で、実数についてのご提示はできないのですけれども、ほぼ診断が終わっている、あるいは診断の結果、オーケーだったです。","voiceIndex":126,"id":"exchange-057"},{"speaker":"木村委員","kind":"意見","question":"調べますと、大体１５種類以上の樹木がいろいろと植えてあるです。本区の木はシイノキ、そして楓ですけれども、どういう理由で、この１５種類以上もの樹木、本区の木ではないものをあちらこちらに植えてあるのか、それについて、何か選定方法があるのかどうか、お聞かせ願いたいと思います。","respondent":"稲田道路課長","answer":"委員ご指摘のように、現在、区には３,７４３本の街路樹があるところです。","voiceIndex":129,"id":"exchange-058"},{"speaker":"木村委員","kind":"質問","question":"１６１ページの下のほうになりますけれども、道路バリアフリー事業、１億７２７万円余ですけれども、先ほど申しましたけれども、区内には区道が約３２８kmあるということですけれども、これを点検し、主にどういう個所をバリアフリー化しているのでしょうか。そして、約３２８kmあるわけですから、１年や２年でこれができるわけではありませんし、どのくらいのペースで行っているのか。","respondent":"稲田道路課長","answer":"年間、側溝の段差解消は４０カ所、歩道の平坦化は１０カ所、視覚障害者誘導用ブロックの設置等は年間１００ｍ等を目安に行っているものです。側溝の段差解消は、平成５年度からゼロ段差を進めてきまして、そのような目安で大体進めてきているものです。","voiceIndex":131,"id":"exchange-059"},{"speaker":"木村委員","kind":"質問・要望","question":"意思の疎通をしていただきたいと思います。バリアフリーとしては、私たちが考えると、段差、そしてあとは公園内の園道くらいしか考えられませんけれども、実際に公園内で何種類くらいできるのか。それも、我々も一緒に利用することができるのでしょうか。そして、またバリアフリー化の基準は、国や都、そして地方が統一されているのかどうかということも、お教え願いたいと思います。","respondent":"多並公園課長","answer":"公園内のバリアフリー化につきましては、現在、計画的に進めているところです。約２６０カ所の公園の中で、今、約７５％の整備で、まずは公園の入り口を確保しようということで、現在、進めているところです。","voiceIndex":133,"id":"exchange-060"},{"speaker":"木村委員","kind":"意見","question":"これをざっと調べますと、公園の中でやるバリアフリーというのは大体１９カ所くらいということであります。もっと驚いたのが、その中で階段のバリアフリーというのがありました。私たちはふだん、階段そのものがバリアという考えでありますけれども、その階段をどのようにつくりかえればバリアフリーになるのか、そして、どんな方が利用できれば、それがバリアフリーとなるのか、ご説明を願いたいと思います。","respondent":"多並公園課長","answer":"そのようなものを複合的に組み合わせながら、現場の状況に合わせながら、バリアフリー化を、現在、公園の中で進めているところです。","voiceIndex":135,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問・要望","question":"先ほど、階段と言いましたけれども、階段も、高さが１６cmということですよね。区立公園２６０カ所中、平成２１年度から平成２５年度までの５年間で３７カ所、バリアフリー化が進んでいるです。平成２５年度は９カ所が終了したそうですけれども、先ほど、７５％とおっしゃいましたが、全てが完了するまでにはどのくらいの年月がかかるのか、教えていただきたいと思います。","respondent":"多並公園課長","answer":"そのような観点を踏まえる点と、それから現場の状況、いわゆる人が多く集まる部分であったり、そのような部分も含めながら、今後も、東京都の都費、特定財源を踏まえながら、総合的に勘案しながら計画的に進めていきたいと考えているところです。","voiceIndex":137,"id":"exchange-062"},{"speaker":"木村委員","kind":"質問","question":"時間がありませんけれども、せっかくバリアフリー化にしたわけであります、また、２０２０年に東京オリンピック・パラリンピックが来ます。そこで、障害者の方々の競技も行われますけれども、せっかくつくったものでありますから、品川区は障害者の方々のためにもこのようなことをやっているということを強くアピールすべきだと考えていますけれども、また後日、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-063"},{"speaker":"沢田委員","kind":"質問・要望","question":"１５９ページの土木管理費、土木総務費で、道路占用について、それから１６２ページの商店街電線類地中化事業について、お伺いします。道路占用についてなのですけれども、公道上での移動販売、農作物や物品や食べ物等の販売について、そもそもこういったことが許可される場合があるのかということ。それから、どのような場合に許可をされるのか、お聞かせいただきたいと思います。","respondent":"安井土木管理課長","answer":"道路の公道上で果物であるとか、食べ物を売るという場合ですけれども、道路の上で販売することは、交通の妨げになりますので、基本的にはできない形になります。","voiceIndex":141,"id":"exchange-064"},{"speaker":"沢田委員","kind":"質問・要望","question":"最近、大井町駅近辺で農作物、それから果物を移動販売されている方がいて、地域の商店街や量販店からも、しっかりとした取り締まりをしていただきたいというお話が何度もありました。区としても、十分に状況を把握されているかと思いますけれども、今の状況について、どういう状況なのかお聞かせください。","respondent":"安井土木管理課長","answer":"なかなか神出鬼没というか、一定のところでずっとやらないという、そういった業者が幾つかあるということは認識しています。","voiceIndex":143,"id":"exchange-065"},{"speaker":"沢田委員","kind":"意見","question":"改めて、今後、警察との連携も含めて、さらに強化して、取り締まりを強くしていかなくてはいけないのではないかと思うのですけれども、今後、区として強く取り締まるという方向をお聞かせいただければと思います。","respondent":"安井土木管理課長","answer":"警察とは、そういう場合に連絡を取り合って、あるいは区役所通りの都道のほうに出てくる場合もありますので、第二建設事務所の占用係とも協力しながら、そもそも交通の障害になるものですので、そういうものについては厳しく行政指導していくと、こういうような考え方です。","voiceIndex":145,"id":"exchange-066"},{"speaker":"沢田委員","kind":"質問","question":"１６２ページの商店街電線類地中化事業について、お伺いします。改めて、品川区での無電柱化率は、大体何％くらいなのでしょうか。２３区平均は７％ですけれども、品川区の現状。","respondent":"稲田道路課長","answer":"品川区は、区道に対して、無電柱化率が何％かということは出してはおらないのですけれども、我々が実施した無電柱化の路線におきましては、先ほども言われました北品川地区、戸越銀座地区、補助１６３号線、都市計画道路、それから２０５号線、１８号線、それから。","voiceIndex":147,"id":"exchange-067"},{"speaker":"沢田委員","kind":"意見","question":"今年度の予算の中でも、オリンピック・パラリンピック施設の周辺の無電柱化ということで、これは国からということで、事業が載っておりましたけれども、今、さまざまな面で検討されているということでしたけれども、オリンピック・パラリンピック施設周辺の無電柱化ということで、どうしてこういう範囲なのか理解ができなかったのですが、そのあたり、どうしてこうなったのかということも。","respondent":"稲田道路課長","answer":"今回検討しております、オリンピック・パラリンピックに関係する無電柱化の検討なのですけれども、競技場周辺、それから東京都からの指導なのですけれども、そこから主要な交通駅等に接続する路線を選定しなさいということで、国道までの通りを、今、検討している状況です。","voiceIndex":149,"id":"exchange-068"},{"speaker":"こんの委員","kind":"質問","question":"私は、１５９ページの交通安全啓発費、この１点でまいりたいと思います。交通安全啓発費の中で、関連してですけれども、自転車の走行についての交通安全対策をお聞きしたいと思います。この自転車ナビマークの設置についてですけれども、今年の３月の予算特別委員会でも、このことは取り上げさせていただきました。徹底の度合いは、どのように捉えていらっしゃいますでしょうか。","respondent":"田口交通安全担当課長","answer":"実際に現状はどうかといいますと、確かにまだ守られていないのが現状だと思います。これをやればすぐに浸透するというのは、なかなか交通安全というのは難しい部分がありますので、引き続き繰り返し指導啓発を行っていきたいと考えております。","voiceIndex":155,"id":"exchange-069"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのような中で、確かに紙媒体や、あるいはホームページ、あるいは機会を捉えての周知の方法とともに、現状、例えば警察の方が中心になるのでしょうか、交通安全としてパトロールをしている際に、目撃したときに、実は声をかけていらっしゃらない姿を、よく見かけるのです。そうしたやり方については、どのように思われますでしょうか。","respondent":"田口交通安全担当課長","answer":"やはり自転車の利用が多い場所ですとか、そういった場所になるかと思いますが、道路の道幅等も影響している部分、関係してくる部分がありますので、要望がある個所に全て設置ができるかというと、これは少し難しいと思いますが、その辺も。","voiceIndex":157,"id":"exchange-070"},{"speaker":"こんの委員","kind":"質問・要望","question":"力強いご答弁をいただきました。強く申し入れをしていただきながら、安全対策を図っていただきたいと思います。もう１点が、信号について少しお聞きしたいのですけれども、歩行者用の青信号、この信号が各所についているわけですけれども、青信号の点灯と点滅の時間について。となると、これはどういうふうに考えていくのか、いわゆる渡り切れないという問題があります。そこら辺を、どう考えますでしょうか。","respondent":"田口交通安全担当課長","answer":"しかし、ゆとりシグナルという、表示でわかる信号機等もあります。そういったものを取り入れるという考え方もありますので、それはまた警視庁のほうに要請してまいります。","voiceIndex":159,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６７ページ、品川駅南地域周辺まちづくりについて、お伺いします。にもかかわらず、１０月１７日には、太田国土交通大臣は、ＪＲ東海に対して、リニア中央新幹線工事実施計画を認可いたしました。そして、多くの疑問、質問にも、問題なしと予測をしていると、まともに答えていなかった。そして、今後、品川区民に対して、きめ細やかな説明会を求めていただきたいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"説明会は約１３２名が出席されたということで、ＪＲ東海から説明がございました。","voiceIndex":162,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民は、リニア新幹線について、ほとんど知っていない状況であると思います。自分の家の地下４０ｍ下にリニアが走る、こういった内容を知る権利が、もちろん区民にはあります。町会ごとなど、十分な説明を求めていただきたいと思いますが、誠意を持ってということなので、再度、実現に向けて重ねてお願いをいたしますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"委員ご指摘の変電室、こちらは非常口も兼ねるですが、こういったところの説明はもとより、関係する地域に説明することは非常に大切なことだと思います。","voiceIndex":164,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、細やかな説明会を開かれますように、強く求めていただいて、実現をしていただきますように、よろしくお願いいたします。１点目は、品川学園のすぐ横に非常口をつくる、児童・生徒への健康被害が心配されます。こういった状況の中で、健康被害への見解を、ぜひお聞かせいただきたいのが１点です。どこに置かれるのでしょうか。この残土の問題についても、区の見解をお聞きいたします。","respondent":"中村都市計画課長","answer":"こちらのほうが、ＪＲの説明では、既に理論的に、あるいは実験によって、ペースメーカー等に影響するという１ミリテスラという単位があるということですが、この１ミリテスラを下回っているということで、健康には影響はないという説明でございました。","voiceIndex":166,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日本共産党はリニア建設に反対をして、計画の撤回を求めています。理由を述べますけれども、１点目、リニア建設には国民的要望も、必要性もなく、大義がないこと。３点目、東海道新幹線の大震災、地震・津波対策こそ、優先すべきであること。４点目、エネルギーの浪費や安全上の問題があること。以上の問題、区はどういうふうに受けとめていらっしゃるか、ぜひ見解をお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"９兆円につきましては、ＪＲ東海が全額負担をする方針で、今進めているところで、これは今後、注視していかなければいけないと考えています。","voiceIndex":168,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２６年６月に、品川区は品川駅南地域まちづくりビジョンを発表いたしました。都有地というのは、都営住宅のことなのですけれども、再編、活用とはどういうことなのか。品川駅南地域まちづくりビジョンが、このまちに住み続けたい人を追い出す計画になってしまわないように、現在住んでいる区民の意見を尊重するまちづくりへの転換を求めますけれども、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"当然、当地域、特にビジョンの中に示した重点検討地域の中で、今後のまちづくりをどうしていくのか、今後、重点的に検討していく地域、その中に都営住宅の区域があります。","voiceIndex":170,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろん、まちは、将来を見据えたまちづくりが大事ですけれども、今そこに暮らしていらっしゃる方々、生活者の意向が最も大事、そこの住む人の幸せを求めるのがまちづくりであると思います。今の品川区の状況は、本当に大企業のほうばかり向いている、ぜひ区民の側を向いたまちづくりへの転換を、強く求めますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"品川区のまちづくりにおきましては、地域の課題を解決する一つの手法として、拠点地域では再開発事業等を行ってきたものです。これからも、地域の課題を解決するために、しっかりとしたまちづくりを進めていきたいと考えているものです。","voiceIndex":172,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方々はいろいろな方がいらっしゃいますけれども、ぜひ区と直結をしている、いつもつながっている人ではなくて、しっかりと広い目で区民を捉えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問・要望","question":"私は、１６５ページ、４項２目公園管理費について、それから、１６９ページの６項１目住宅総務費について、お伺いしたいと思います。公園整備についてです。ですが、今回、実際にこの餌やり禁止の看板によって、危険な目に遭っている区民がいることへの対策を求めて、質問をいたします。品川区立公園条例の第３条のどこに当たるのか、また、第４条の使用の禁止、または制限に当たるのかお伺いいたします。","respondent":"多並公園課長","answer":"その都度、まずは地元の町会長をはじめ、いろいろなご意見をお聞きして、そこの公園の利用についてはどのような形でしたらいいかとご相談しながら、現在のところは、いろいろな方がいらっしゃるところで、禁止という形にさせていただいているところが現状で。","voiceIndex":176,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"それぞれ苦情があるということは理解しています。だからその周りの方たちの市民とともに協議をする場を設けようとしても、どこにあるかということをきちんと把握をされてはいるのでしょうけれども、個数がわからないということなのか、ただ声が挙がってつけているからわからないということなのか、その辺はどういうことなのでしょうか。","respondent":"多並公園課長","answer":"地域のほうには、少なくとも猫のフンの被害があるという実態がある中で、どういう形で対処していけばいいかというところで、大変苦労する中ですけれども、禁止という形の看板でお知らせして、現在のところは、対処しています。","voiceIndex":178,"id":"exchange-080"},{"speaker":"井上委員","kind":"提案","question":"２００９年に検討調査委託として５００万円、決算額が４９９万３,０６５円で、そのときの調査委託がどんな目的で、どういう調査を行ったのかということと、現在、運営を区から委託されている方、これは協働提案事業で応募をして、１社しかなく、現在の事業者が採択されたということなのですが、どうして協働提案事業という形になってしまったのか、その辺をお伺いしたいと思います。","respondent":"矢木住宅担当課長","answer":"協働提案事業になった経過ですが、こちらにつきましては、住み替えの意向調査を受けまして、地域の中での、まず住み替えの意識を高めることが必要だということで、住民主導ということで、この事業を進めたいという趣旨から、協働提案事業になった経過があります。","voiceIndex":180,"id":"exchange-081"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６５ページ、都市計画総務費の中で、地域交通検討会経費のところで聞いていきたいと思います。決算が３５８万９,４４０円ということなのですけれども、これが何に使われたお金なのか、教えていただきたい。本年度の第２回の会議に入られて、次に第３回の会議になると思いますが、まずそこの部分を教えてください。","respondent":"中村都市計画課長","answer":"経費の内訳ですけれども、こちらの地域交通検討会を開催するにありまして、基礎調査、あるいは資料の作成、そして議事録の作成などの運営費全般です。これは年度共通です。","voiceIndex":184,"id":"exchange-082"},{"speaker":"渡部委員","kind":"質問・要望","question":"１回目が行われた内容を確認して、議事録を見た中で、学識経験者の先生方２名にご参加いただいている中で、本当にまさにそのとおりだなというようなご意見があります。とりあえず、さまざまな要望に沿ったルートを走らせてみたら、非常に不便なルートになってしまい、見直したくても、既に利用している人から苦情が出るという厄介な問題があって、にっちもさっちもいかないようなことがある」と。","respondent":"中村都市計画課長","answer":"その中ではやはり、逆走するにあたりまして、バス停が新たにできるところにつきましては、そのお店なりにも影響があるといった、そういった影響が非常に大きいだろうということと、また最終的には、路線の皆さんの同意が必要だということで、非常に困難であるということで。","voiceIndex":188,"id":"exchange-083"},{"speaker":"渡部委員","kind":"確認","question":"わかりました。でも、見たときに、そこまで抜本的なといいますか、発想を転換して考えていかないと解決できない問題もあるのかと思いました。これを、これから高齢者の方々が、どういうふうに利用しやすくするかと考えたときに、バス停は３００ｍ、駅に関しては５００ｍくらいが妥当であろうというような記載があって、それをシミュレーションしたマップが確認されました。","respondent":"中村都市計画課長","answer":"約９５％が網羅されているから、それでいいかというと、そうでもないと思いますので、これについてはまた別途さらに検討していく必要があると考えております。","voiceIndex":190,"id":"exchange-084"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり高齢者は増えてまいりますし、検討する際には、そちらのほうの数値を使ったうえで、またさまざまな施策を打っていただきたいと思います。話は戻るのですけれども、単純にコミュニティバスを走らせるかどうかといった調査は、現段階では、時期尚早ですと、学識経験者がしっかりと言っておられますので、しっかり公共交通を活用していっていただければと思います、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-085"},{"speaker":"藤原委員","kind":"質問・要望","question":"下水道の耐震化ですけれども、避難所の周辺と区内全般では、率はどうなのか、お伺いします。それから、１７０ページの区民住宅の借り上げなのですけれども、毎回伺っています特定優良賃貸住宅、もう２０年で期間が切れて、今、返していると思うのですけれども、数などの答弁は要らないですから、区としての特別優良賃貸住宅の考え方として、粛々と返還していただきたいという思いで、お伺いします。","respondent":"田口交通安全担当課長、稲田道路課長、奥田河川下水道課長、中村都市計画課長、矢木住宅担当課長","answer":"私の抱負なのですが、やはり１件でも事故を減らす、特に重大事故、死亡事故で亡くなるのは１名かもわかりませんが、そこには家族もおります。現在、２路線、戸越銀座と北品川を進めてきたところですが、電線類地中化が可能な路線を、区が各商店街に照会しまして。都では、平成２４年に工事を予定しておりましたが、地下埋設物が障害で、ＪＲの新幹線と横須賀線の基礎が支障となりまして。ホームドアですけれども、今後の計画といたしましては、ＪＲの大井町駅が来年度工事の予定ということです。","voiceIndex":194,"id":"exchange-086"},{"speaker":"藤原委員","kind":"質問","question":"区民住宅について伺いますけれども、今、区民住宅の建設型に関しても、空いている部屋がありますよね。そこでまず目的は何ですかと伺いますと、中堅ファミリー層の定住だということなのですけれども、区としては、どこが中堅ファミリー層なのか、どういうふうに考えているのか、教えていただけますか。","respondent":"矢木住宅担当課長","answer":"基本的には、年収額７００万から８００万円以下の方々で、区営住宅の対象者以上の方々と捉えております。","voiceIndex":200,"id":"exchange-087"},{"speaker":"藤原委員","kind":"質問","question":"ファミーユ大井の一番高い家賃は１８万円ですよね。私も考えたのですけれども、税金が引かれてなくて７００万から８００万円の家庭で、１８万円も払えるのかと思っていました。だから今、空いていますよね。だから、そこの線引きというか、バランスは、区としては、どのように考えているのでしょうか。","respondent":"矢木住宅担当課長","answer":"ですので、数字的には、その都度の状況によりまして変わってまいりますが、区民住宅を施策的なものに使うために、多少は空き室にしておく必要性もあると認識しております。","voiceIndex":202,"id":"exchange-088"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、１６５ページのしながわお休み石設置事業、そして時間があれば、その下の公園・児童遊園維持管理費の中の清掃、除草等委託について、お伺いいたします。今年は、新規４基、また維持補修費を含めて２８３万円が計上されております。もう一つは、一つつくったことで、耐久性というのですが、何年くらいもつのか、それを教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"お休み石の総数ですけれども、委員ご指摘のとおり、平成８年から設置を始めまして、現在までに２８３基設置してまいりました。今は、年間大体２基から８基くらいの割合で設置してきているところです。","voiceIndex":205,"id":"exchange-089"},{"speaker":"山元委員","kind":"質問・要望","question":"設置場所なのですけれども、公共の場所、またはその近辺ということでありますけれども、今までに２８３基設置されているということなのですが、どのように決めていらっしゃるのか、その辺を教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"当初、平成８年に始めましたころは、区のほうで、こういった場所に必要であろうという検討のもとに設置してまいりました。","voiceIndex":207,"id":"exchange-090"},{"speaker":"山元委員","kind":"質問","question":"お休み石、３種類あると聞いております。バス停の近辺に設置しているところもあるのですけれども、一つはまずサイコロ型というのでしょうか、先ほど、都市計画課長も、表面の板を替えるとおっしゃっていました。この３種類以外は、いろいろアイデアをいただいてつくったのでしょうけれども、何か違うものは考えていらっしゃるのかどうか、教えてください。","respondent":"中村都市計画課長","answer":"サイコロ型、ベンチ型、椅子のような１脚ずつのような形がありますが、概ね基本的には、このパターンで大体設置場所に対応できるかと考えています。","voiceIndex":209,"id":"exchange-091"},{"speaker":"山元委員","kind":"質問","question":"可愛がるように言っておきます。一つ、お休み石なので、みんな座るようなデザインなのですが、実は場所によっては、スペース的に設置できないということで、これもアイデアということになるのでしょうか、座らなくても寄りかかるようなものがあれば助かるというご意見をいただいているのですが、そういうものをつくるというか、アイデアとして参考になるのでしょうか。","respondent":"中村都市計画課長","answer":"ただ、そういったアイデアは、どうしてもここには座る型は設置できないけれども、そういうものなら設置できるということであれば、これも検討させていただければと考えております。","voiceIndex":211,"id":"exchange-092"},{"speaker":"山元委員","kind":"質問・要望","question":"私も何度か利用していますので、ぜひご検討いただきたいと思います。公園管理の清掃、除草等の委託について、お聞きしたいと思います。先ほど、区内には公園が２６０カ所あるというふうに伺っていますけれども、実際に、１日に何カ所くらい、清掃や除草をしていただいているのか。年間を通して、１カ所の公園に何回くらい清掃や除草は行っていただけるのか、教えていただきたいと思います。","respondent":"多並公園課長","answer":"公園の清掃等について、お答えします。清掃につきましては、ふれあい作業所やかもめ工房等福祉団体にお願いしておりまして、公園の汚れ具合によって、週に２回から５回で、その状況に応じた清掃回数としています。","voiceIndex":213,"id":"exchange-093"},{"speaker":"山元委員","kind":"質問・要望","question":"毎日、きれいな公園というのは、そういう裏方さんのご努力があるのかと思います。実際に、清掃等に従事しているメンバー、人数はどのくらいいらっしゃるのか、もしわかれば教えていただきたい。どんな苦情があるのか、教えていただけたいと同時に、どんな対応をしているのか、教えていただきたいと思います。","respondent":"多並公園課長","answer":"落ち葉については、ちょうど今の時期ですけれども、あった際には、現場へ赴いて、現場の状況に応じて、区のほうで造園業者に依頼し、速やかな対応をし、現場で確認しながら、区としてもよりよい環境づくりを行っているところです。","voiceIndex":215,"id":"exchange-094"},{"speaker":"大倉委員","kind":"質問・要望","question":"これはどこに入っているのかわからないので、教えていただきたいのですが、私は土嚢について伺います。土嚢ですが、いつくらいから設置されてきたのか。もう一つが、１５９ページの屋外広告物取締事務です。違反はり紙除去等とありますが、まず確認ですが、これは区の単費で４６１万円なのか。そして、いつくらいからそうした費用があるのか、教えてください。","respondent":"稲田道路課長、安井土木管理課長","answer":"設置についてですが、詳しい記録はないのですけれども、平成元年の大雨で目黒川沿い等に設置した、それから平成１１年の大雨で西品川周辺に設置していったということで、現在、４８カ所設置しております。屋外広告物取締ですけれども、基本的には、屋外広告物については許可で行っておりますので、その許可手数料を充当するという形になろうかと思います。","voiceIndex":218,"id":"exchange-095"},{"speaker":"大倉委員","kind":"質問・要望","question":"今現在、土嚢は４８カ所、１万２,２９０個でありますが、減ったら補充していく、まただめになったら補充していくということだったのですけれども、現在、どういった利用状況になっているのか。そういった意味で、平成２４年度では４６１万７,０００円と、毎年かかってくるのだろうと思うのですが、この辺の費用対効果について、お聞かせください。","respondent":"稲田道路課長、安井土木管理課長","answer":"これが高いかどうかという話にはなるのですが、やはり浸水地域の方の不安や、また軽減をするというところにおきましては、初期対応におきましては非常に効果的であると考えていますので、費用対効果というか。歳入としては、許可手数料が１,６４０万円ほど入っておりますので、そういったものの反面の部分で、許可をすると同時に、許可を得ていないものについては取り締まる、撤去するということで。","voiceIndex":221,"id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"止水板とかはかなり大変だし、費用も高いということでありますので、その辺を少し考えていただいたほうが、より利用しやすいのではないのかという部分で、ちょっとお聞かせいただきたいと思います。その辺、しっかりと区民からも求められていると思うので、どういった対応をしているのか、もう１回お願いします。","respondent":"稲田道路課長、安井土木管理課長","answer":"土嚢ではなくて、もっと安価なもの、使いやすいものを考えたらどうかというご意見なのですけれども、土嚢におきましては、一番基本的には水害対策のものだと思うのです。こういった意味では、過料の金額等についてアップするとか、そういう抑止効果を、東京都のほうにも要請していく必要があるかとは考えているところです。","voiceIndex":224,"id":"exchange-097"},{"speaker":"渡辺委員","kind":"確認","question":"１６６ページ、しながわ区民公園を一部聞いて、主は水族館で伺ってまいります。区民公園は、整備工程で、平成２５年度も中央ゾーンの基本設計が入ったり、クラブハウスの改修をしたと思います。以前も伺いましたが、北側、そして中央、そして南と、南イコール水族館のところでも、ご答弁の中では、一体的な、あるいは連動したというご答弁がキーワードの一つかと思います。","respondent":"多並公園課長","answer":"３カ年進めながら、その後、北側、野球場のあるほうを整備していこうと考えています。南側については、そこの状況を踏まえながら、全体的な工程の中で、今後の整備については考えていきたいと、今のところは、そういうふうに考えているところです。","voiceIndex":228,"id":"exchange-098"},{"speaker":"渡辺委員","kind":"確認","question":"今のご答弁から、それを踏まえて、ということは、ものの順番で言うと、まず北側、中央を見たうえで南側なのか、それとも、最初からある程度一体的なグランドデザインがあっての、ものの順番なのか、その辺をもう一度確認したいと思います。これまでは改善とか、検討という中で、これまでも、あり方もあったと思います。この辺の区切り目、計画のタイムスケジュールを、もう一度教えてください。","respondent":"多並公園課長","answer":"ただ、水族館のある南側でもありますので、そこにつきましては、魅力ある水族館ということで、今年度も入り口の改修を行いながら、さらなる磨きをかけ、今後のおもてなしができる形で進めているところですので、現時点では、そういう形で考えているところです。","voiceIndex":230,"id":"exchange-099"},{"speaker":"渡辺委員","kind":"質問","question":"それで、せっかくだからというので、いろいろ意見してくれ、教えてほしい、感想を言ってほしいと言いました。学生たちも教授もすごく熱心で、まず感想だと。先に改善点を申し上げます。実際のところ、２０周年を経て、老朽化に対応する中で、コストもばかにならないかと思います。そして、そういう大規模リニューアル、手入れの途絶えているわけ、何か課題があるのかどうか、まずそれを教えてください。","respondent":"多並公園課長","answer":"いろいろ見えない部分ではさまざま故障があって、それは緊急対応を行ってきているところがあるのですけれども、ここ最近、確かにおっしゃるように多いところがあるので、コスト的には、以前よりは大分かかりながらやっているところで。","voiceIndex":232,"id":"exchange-100"},{"speaker":"渡辺委員","kind":"質問","question":"この点について、ご見解を伺いたいのが一つ。それから、しながわ水族館は、もう既にやっていらっしゃるのかもしれませんが、近隣や区外の教育機関と連携、あるいは誘致、これについての見解を伺いたい。それから最後に、区内幼稚園、小学生に水族館の絵を描いてもらい、毎年１回大々的に絵のコンクールを、区長賞をはじめ用意をする。このような提言をいただきました。ご見解をいただければと思います。","respondent":"多並公園課長","answer":"ただ一方、今ご指摘のように、大森海岸、大森方面からの利用者が、歩いてきてくださるところが、なかなかわかりにくいというご意見もありますので、そこは、もう少しわかりやすさ等も踏まえながら、おもてなしができるような整備を、国道とも連携して、どのようなことができるか。","voiceIndex":234,"id":"exchange-101"},{"speaker":"渡辺委員","kind":"質問","question":"ここからは議会としてといいますか、私自身の思いも込めて伺います。水族館の評価について、前にも伺ったかもしれませんが、来場者の数は、どうしても前年比で出す仕組みではありますが、中長期的に見て、しながわ水族館は何万人だと合格点なのか。その辺についての数値目標、あるいは評価の基準を教えてください。この辺、これからの未来に向けて、品川区が誇る拠点をどう考えるか、最後にご答弁ください。","respondent":"多並公園課長","answer":"もう一つの床面積の拡充、またスポーツパーク、フードパーク等、全体的なお話ですけれども、先ほど南側の整備の今後の検討というお話をしましたけれども、そういう広い中で、今いただいたご意見を踏まえながら、どのような形になるか。","voiceIndex":236,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"１５９ページ、大森駅自転車等駐輪場、これはいろいろと議論があった駐輪場ではありますが、今は稼働率がどうなっているのか、それから近隣の住民の理解がどうなっているのか、現状をお聞きします。次に、１６５ページの特定整備路線沿道まちづくり推進費、このまちづくりという観点で、どのような状況になっているのでしょうか。１６９ページの除却助成。","respondent":"田口交通安全担当課長、中村都市計画課長、寺嶋木密整備担当課長","answer":"大森駅の利用率です。現在、定期利用の自転車は１００％です。定期利用のバイクが９２.３％。それから当日利用の自転車が１０５.５％となっております。もう一つは、商店街のにぎわいを、どのように継続していくかということについて。密集事業の先行実施、それから、前倒し地区の違いということですけれども、木密地域不燃化１０年プロジェクトの実施が。","voiceIndex":239,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう意味では、やはり地域の住民たちにしっかりと説明をしていただいて、理解を求めていく。それに対しまして、区としては、どういう支援があるのか。非常に進む内容だと思います。その条件を少し緩和することによって、またさらに品川区の中で進むのではないかと思うのですが、もう少し網かけを緩やかにするとか、広げるとかということを、ぜひ検討していただきたいと思いますが、いかがでしょうか。","respondent":"田口交通安全担当課長、中村都市計画課長、寺嶋木密整備担当課長","answer":"そういった意見を聞きながら進めていきたいと考えています。区も、その勉強会等に参加して、いろいろと説明をしたりして支援をしています。連携して、これからも進めていかなければいけないと考えています。達成時の見込みですけれども、１０年プロジェクトという名称から、１０年間で、年間１割ずつ進めばこれに越したことはないのですが。","voiceIndex":243,"id":"exchange-104"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１６５ページの地域交通検討会について伺いたいと思います。ここの地域の対応については、バス事業者等に路線バスの充実として、路線の延長や増便などを要望してきていると。これも、具体的に教えていただきたいのですけれども、どの路線を、どのバス事業者に求めているのか。東急、京急、都営バスとありますけれども、どこに求めているのか、そしてそれで不便地域は解消されるのか。","respondent":"中村都市計画課長","answer":"バス事業者についての協力ということですけれども、こちらにつきましては、今現在、交通不便地域について、バス事業者については路線の延長、あるいは増便などの対応について、それから、あとはタクシー事業者については、これから何かいいアイデアがないか。","voiceIndex":248,"id":"exchange-105"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も一般質問でさせていただいたのですけれども、そこの答弁でも、交通不便地域の対応については、バス事業者等にもう求めていると、路線の延長や増便を要望してきているのです、というふうに答えているのです。ですので、もう要望されているということですよね。なので、どこのバス事業者に、どの路線を要望しているのか、具体的に教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"地域交通検討会の中では、バス事業者の代表者に出席していただいているということで、まずは区内全体的に見て、路線の延長や増便の可能性が、今あるかどうかというところを、意見としてお伺いしたところです。","voiceIndex":250,"id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"具体的な事業者も、路線も出てこないということは、具体的には求めていないということでいいですかね。これを確認させていただきたいと思います、お願いします。","respondent":"中村都市計画課長","answer":"ですので、さらに具体的な検討につきましては、今後、どういった路線が可能かどうか、こういったものを実際にバス事業者との話し合いをしていかなければならないと考えています。","voiceIndex":252,"id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、交通不便地域の対応については、このように求めてきていると、答弁されているのですけれども、今何回聞いても、何も出てこないということは、不便地域の対応は考えていないということなのでしょうか、もう１回、お願いします。","respondent":"藤田都市環境事業部長","answer":"そのときには、もともとそこのエリアの近所に、例えば東急バスが走っている、あるいは都営のバスが走っているということであれば、そのバス会社のほうに、具体的にそちらのほうまで延伸できないのかとか、そういうようなお願いをしてきているところです。","voiceIndex":254,"id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このニーズの把握ですよね、私たちはアンケートも求めてきましたけれども、必要か必要でないかというところでは、必要だと１００％答えるということでしたけれども、そういう単純なアンケートでなく、何で必要なのか、どこに困られているのか、日ごろ、不便地域の方はどういったところに頻繁に行かれているのかと、そういったニーズ把握が必要だと思うのです。","respondent":"中村都市計画課長","answer":"ニーズの把握についてですけれども、この地域交通検討会の中でも、いろいろ検討してきた中で、やはり区民の方からのニーズもあるところ、それから、地域交通検討会の中では、メンバーとしまして、障害者の代表の方にも入っていただいています。","voiceIndex":256,"id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"専門家の派遣をはじめ、さまざまな手だてが講じられておりますけれども、建築物耐震化支援の全体の予算が２０億円に対して、決算が５億円というふうに、事業の進捗の困難さが伺える状況です。実績の確認をします。平成２３年度の基礎調査で、旧耐震マンションが３２０棟あるですが、アドバイザーを派遣したマンションの棟数や耐震改修の棟数実績を教えていただきたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"同じく、耐震改修につきましても、２件です。それから、耐震化アドハイザーの派遣ですけれども、棟数としては５５棟が派遣を受けておりまして、一つの棟で複数回の派遣が可能なので、回数としては６４回という累計になっております。","voiceIndex":259,"id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"同じく１６９ページの分譲マンションの管理支援について、お聞きしておきたいと思います。予算が１５１万円に対して、決算が８４万円でした。この差についてのご説明をいただきたいと思います。マンション管理支援の中では、派遣事業が二つあります。改めて耐震化アドバイザー、またマンション管理士に対する区の評価、区民の相談に対する評価をお聞きしておきたいと思います。","respondent":"矢木住宅担当課長、寺嶋木密整備担当課長","answer":"そしてまた、建替えにつきまして、一級建築士とマンション管理士の違いですが、どちらも大規模修繕に係わるものですが、一級建築士は、主に技術的なアドバイス、すなわち工事内容等に助言を与えるというものでございまして。そういう意味では、耐震補強に向けた取組みについての支援をさせていただいているという事業になります。","voiceIndex":261,"id":"exchange-111"},{"speaker":"若林委員","kind":"提案","question":"今後も十分に力を発揮していただいて、耐震化や適正な管理が進むように区も支援をしてほしいと思いますけれども、こういった方たちのご協力も得ながら、今後のマンションの耐震化、また建替えの実績の向上への取組み、またご決意を聞いておきたいと思います。その中で、ご答弁をいただきながら、私のほうから二、三提案ということで投げかけします。","respondent":"寺嶋木密整備担当課長、鈴木建築課長","answer":"２月、３月に二度目の実施を予定されておりまして、直接的にお話をして、マンションの耐震化等の啓発に努めるという事業が、今進んでいるところです。ご案内のとおり、マンション円滑化法が平成２６年６月１８日に法改正になりました。施行予定も１２月２４日を目指して決まっておりますので、その中で、要件等の緩和を整備しまして、しっかりと相談体制を整えていきたいと考えています。","voiceIndex":264,"id":"exchange-112"},{"speaker":"若林委員","kind":"提案","question":"私のほうからは、特に障害のある子どもたち、またその家族に有意義に使っていただきたいという観点から、ひとつ要望というか、ご提案をさせていただきたいと思います。イベントブースの出展、その企業の販売促進品などにしながわ水族館名とかロゴを乗せて、広くアピールしていただけるという、こういうすばらしい事業があると聞いておりますけれども、品川区のほうでは、この事業についてご存じでしょうか。","respondent":"多並公園課長","answer":"ドリームナイト・アット・ザ・ズーという形で、世界的な取組みを行っている事業です。葛西臨海水族園をはじめ公共の水族館が行っている事業です。こちらにつきましても、協賛企業等からも話がございまして、今、障害者福祉部門と取組みについて検討を進めている最中です。","voiceIndex":267,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問・要望","question":"これが平成８年につくられて、今は平成２６年ですから、もう１８年たっています。バス停にはお休み石はある程度あるのですけれども、この事務事業概要、冊子の裏に部長の似顔絵が書いてあるのですけれども、ここの事務事業概要によると、平成２１年から、商店街についてはゼロになっていますけれども、これは何か置かれないような理由、原因があったら、教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"場所については、特に制限を定めたということはございませんので、たまたまそういったところに要望がなかった、あるいは設置してほしいという意見がなかったということかと思います。","voiceIndex":270,"id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"となると、この用途や使いたい方の対象も自ずと変化してくると思いますけれども、この構想について、平成８年にこれを練られて、その後、見直しをされながら、利用者について分析をされていますでしょうか。","respondent":"中村都市計画課長","answer":"今、品川区内、こういったところにあったらいいなというご要望に応じて設置をしています。ただ、その利用については、現在、把握はしてございません。","voiceIndex":274,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"もちろんここにいる委員はみんな、まちを歩いているわけですけれども、最近、私がよく見かけるのは、高齢者のみならず、若い女性も座っている。リュックを背負った、定年退職をされて、まち歩きをされている人も座っている。商店街の中も、往来が激しい。さっき言ったように、公道である以上、個店からお休み石的なものは出すことができないですよね、そこのところを教えてください。","respondent":"中村都市計画課長","answer":"商店街ですけれども、通行に支障がないというのはなかなか難しいところではありますけれども、ただそういった協力が得られれば、そういったことも考えていきたいと考えております。","voiceIndex":276,"id":"exchange-116"},{"speaker":"大沢委員","kind":"提案","question":"そこで提案なのですけれども、石となると、これはもう不動のもので動かないので、比較的往来の激しい場所で、移動可能なお休み石に代わる何かというのは考えることはできないのでしょうか、教えてください。","respondent":"中村都市計画課長","answer":"と申しますのは、やはり転倒の危険性ですとか、あるいは盗難だとか、そういったことがありますので、十分に管理していけるというところであれば、そういったことも可能ですけれども、これは今後の検討課題とさせていただきたいと思います。","voiceIndex":278,"id":"exchange-117"},{"speaker":"大沢委員","kind":"質問・要望","question":"お客様のニーズは、ちょっと休んでまた買い物をするというのは非常に大事な行動だと思いますので、考えていただきたいと思います。よろしくお願いします。次に、武蔵小山について、まず、駅前ロータリーの道路の管理者は誰か教えてください。","respondent":"稲田道路課長","answer":"品川区です。","voiceIndex":280,"id":"exchange-118"},{"speaker":"大沢委員","kind":"質問","question":"東京都に聞きましたら、品川区だと言われて、玉突きで、私はどこに行って、どちらに話をしたらいいのかわからなくなりましたけれども、では、ガードを含めたところは、品川区と理解していいのでしょうか。","respondent":"稲田道路課長","answer":"委員のおっしゃる、トイレ周辺のガードですれば、品川区であります。","voiceIndex":282,"id":"exchange-119"},{"speaker":"大沢委員","kind":"質問","question":"何のために、あそこをきれいにしたかわからないような感じで、トイレの前にずっとガードがありますが、あそこのところを、人の往来と車ということで、危険だということで申し受けてありますけれども、あそこら辺は一部開放して、開けることはできないのでしょうか。そこのところのお考えを聞かせてください。","respondent":"稲田道路課長","answer":"バス停のところから、２６号線に抜けるところの直線のガードではないでしょうか。","voiceIndex":284,"id":"exchange-120"},{"speaker":"大沢委員","kind":"質問","question":"ここでお話するのは、私もよく調査しているわけです。何のためにあれをつくったかというと、あそこの新しくつくったバス停のところ、あそこの道路はすごくきれいですよ。片方の車道のほうを、いっぱいみんな歩いているのですけれども、歩車分離をしたのは何の意味があったのか、その意味合いを教えてください。","respondent":"稲田道路課長","answer":"歩行者は歩道を通って、車は車道を通るということで、駅から２６号線に行く方は歩道を通ってもらう。人が車道を渡ると危険だということで、あのガードパイプを設置したものです。","voiceIndex":288,"id":"exchange-121"},{"speaker":"大沢委員","kind":"質問・要望","question":"危険かもしれないけれども、利便性等いろいろなことを考えていただきたいと思います、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-122"},{"speaker":"あべ委員","kind":"質問","question":"私からは１６６ページの大崎駅周辺地区再開発事業ならびに１６７ページの百反ずい道、百反歩道橋、その後、時間があれば１６０ページの道路安全施設の視覚障害者用誘導タイル、それから、１６５ページの区民公園についても、簡単にお伺いできればと考えています。それから、百反ずい道については、歩道橋が開通いたしまして便利になったと、地域の方々からいろいろ喜んでいるお声をいただいております。","respondent":"溝口都市開発課長、稲田道路課長","answer":"業務棟につきましては、入る業態によって変わってきますので、一概にm2数がわかったからといって、どのくらい増えるかという形までの推計はしていませんが、かなり大型の再開発ビルになりますので、全部埋まるようになれば。百反ずい道の歩道設置については、道路課が担当でやっております。この歩道の工事なのですけれども、１０月３日に契約予定で発注したのですが、入札辞退が発生しました。","voiceIndex":293,"id":"exchange-123"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字は出てこなくて、オフィスなど、事実上は決まっているのかと思うのですが、いいです。その中で、今後、動線について、どう考えていらっしゃるのか。特に駅と新しいビルの間を結ぶ橋の設置について難航しているというお話を聞いていますけれども、これはどういったことが原因で、竣工までに間に合う見通しであるかどうかということを教えていただきたい。","respondent":"溝口都市開発課長","answer":"ただ、委員ご指摘のとおり、平成２７年５月の竣工時期には、工期的にも、現在無理な状況になりますが、一つ目標といたしましては、先ほど言いました両ビルは、実際に平成２７年５月にそれぞれの権利者に引き渡し、それから、テナントといいますか。","voiceIndex":296,"id":"exchange-124"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ夏の入居には間に合わせていただきたいと考えています。ニューシティ側でも、反対しているところは、もう約１社程度になっていると聞いておりますが、ここについては強い態度で交渉していただきたいと考えています。このずい道については、できるだけ早くやっていただきたいのですけれども、土木関係も、やはり最近不調が多いのかということを、一応確認させていただきたいと思います。","respondent":"溝口都市開発課長、稲田道路課長","answer":"区といたしましても、これは地元提案ではありますが、都市計画で定めた要件でありますので、接続に向けて組合とともに協議に入っていきたいと考えているものです。不調ですが、今年度、４件目です。昨年度は、ちなみに３件でございました。","voiceIndex":298,"id":"exchange-125"},{"speaker":"あべ委員","kind":"質問・要望","question":"橋のほうのご答弁なのですけれども、もう一度、区の役割というのを明確に説明していただきたいと思います。一義的には民民かとは思いますけれども、区にもそれなりの役割があると思いますので、そこを踏まえてご答弁をお願いいたします。それから、今、土木関係の不調等の数を伺いました。これは原因はどのように考えていらっしゃいますでしょうか。","respondent":"溝口都市開発課長、稲田道路課長","answer":"そういった意味でいきますと、目黒川デッキの接続は絶対条件になりますので、それに向けた協議は一緒になってやっていきたいと考えているものです。不調の原因ですが、要するに技術者、作業する者等の人数不足というところでの金額への跳ね返り、それから、百反ずい道に関しましては、ＪＲと交差するところであって、ちょっと難しいのではないかということがあるということです。","voiceIndex":301,"id":"exchange-126"},{"speaker":"高橋委員","kind":"質問・要望","question":"１５９ページですが、国道１５号線、いわゆる第一京浜の大井第一地域センター前の交差点について、地域センターのほうに南大井四丁目から渡る区道から第一京浜に出るときに、非常に見通しが悪い、両側に壁と住居がありまして、以前、区民の方からご要望があって、区のほうでも、巻き看板というんでしょうか、電柱に巻いていただいて、啓発していただいたのですが、まだ非常に危険な状態。","respondent":"田口交通安全担当課長、奥田河川下水道課長","answer":"その際には看板等を設置しているという状況ですが、申し訳ございません、再度私のほうで現場実査をさせていただいて、信号の状況を確認したうえで対応させていただきたいと考えております。それから次に、津波・高潮対策として、立会川河口部の水門に向けた検討を、都と連携して進めておりまして、水門等の整備については、２０２０年オリンピック・パラリンピックに完了させる予定なのですけれども。","voiceIndex":305,"id":"exchange-127"},{"speaker":"高橋委員","kind":"質問・要望","question":"交差点のほうは、その隣の交差点でも、今年８月に死亡事故があり、そして平成２４年からは５件も起きております。周辺もそういう事故が起きているので、ここで起きないように、先ほど、交通安全担当課長が１件でも事故を減らしたいという決意があるとおっしゃったので、ぜひとも、今お話があったように検討していただきたいと思います。","respondent":"奥田河川下水道課長","answer":"水門等の整備状況についてですが、東京都の建設局、下水道局と区のほうで、まさに検討しておりまして、例えばしながわ花海道から立会川を横断いたしまして、競馬場通りからしながわ区民公園への動線確保を進めてもらうような形で、現在、まさに調整を行っている最中です。","voiceIndex":308,"id":"exchange-128"},{"speaker":"高橋委員","kind":"確認","question":"３点目の建築確認費のほうで、勝島に公務員住宅が３５０戸、民間のマンションが二つあって、合わせると８００戸以上、合わせると１,２００戸の民間のマンションが建設される予定、あるいはもう入居という話を伺っています。このようなマンション建設で人口が増えるような情報というのは、区のほうはどのようにして把握するのでしょうか。","respondent":"中村都市計画課長","answer":"特にその中でも、さらに敷地面積が５,０００m2を超えるような大規模建築物につきましては、庁内の関係部署に対して事業主からの説明を義務づけるなどをしております。そういった形で、庁内で建築物の件数、それから集合住宅等の戸数の状況について、情報共有をしております。","voiceIndex":310,"id":"exchange-129"},{"speaker":"高橋委員","kind":"質問","question":"先ほど、他の委員からもありましたが、マンション建設によって人口の増加、それに伴う区民サービスの準備の状況、また難しいところもあると思います。例えば東京都が認可するそういったマンション等の情報は、どのようにして取れるのでしょうか。逆に、そういうのを知る方法はなかなかないのでしょうか。","respondent":"中村都市計画課長","answer":"東京都で確認をいたします、延べ面積１万m2以上の建物につきましても、区のほうでは事前の相談ですとか、建築確認申請のときに区を経由するといった、そういった方法もありますので、情報については１００％把握できているものです。","voiceIndex":312,"id":"exchange-130"},{"speaker":"高橋委員","kind":"質問","question":"前の款でありましたけれども、人口の動静調査などは、数字で出てきてしまう、つまり、もう移ってきてからのお話になると思うので、その前に、これだけの方が移られてくるといった状況を、今お話がありましたけれども、区で情報を共有して各政策を立てていかれると思うのですが、それを全庁で横断的な、例えば人口急増対策プロジェクトのようなものを立ち上げて。","respondent":"柏原行財政改革担当課長","answer":"そういったことに関しまして、我々企画部門といたしましても、そういった情報を積極的に取りながら、プロジェクトチームということではないのですけれども、関係ある部署と情報を共有しながら、どういった施策を打てるかという参考にしている状況です。","voiceIndex":314,"id":"exchange-131"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、ご答弁いただいたのですが、ぜひ、先手を打っていくためにも情報を集約し、そして政策を発信していくという政策的なプロジェクトチームを、ぜひ設立していっていただきたいと思います。この件については、また別の機会にご質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":316,"id":"exchange-132"},{"speaker":"浅野委員","kind":"質問","question":"最初に私道整備事業ですけれども、私道整備の相談の件数についてお伺いしたいのですが、全額助成対象となる件数と、１割負担が発生する件数、こちらについては全てお伺いします。そして、それぞれの件数につきまして、土地の所有者の承諾が得られて、私道整備ができるというのでしょうか、できたでもいいのですけれども、そのように至った件数について、それぞれ教えてください。","respondent":"鈴木建築課長","answer":"私道整備の相談件数ですが、平成２５年度、５１件の相談がございました。うち費用の発生しないものについては４６件、費用負担ありが５件です。","voiceIndex":318,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問・要望","question":"相談件数は５１件ありまして、できた件数が、全額助成のほうだけということでしょうか、７件ということで、負担があるとどうしてもできにくいというのは、私も何件か経験をしたことがあります。実際に品川区内で減免申請している件数がどのくらいあるのか、もし数字がわかれば教えてください。","respondent":"鈴木建築課長","answer":"しかしながら、基本的には、私道といえども、一定の交通、あるいは利用がある場合は、申請をすれば非課税扱いになるものと考えておりまして、実際にそうされている方も大勢いらっしゃると伺っております。","voiceIndex":320,"id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"申請をしておられる方もいるということですけれども、例えば相談を受けたときに、特に１割負担が発生する場合に、区のほうで少し力を尽くしていただいて、どのくらいの減免になるとか、そういうのが概算でもわかれば、例えば１割は負担するけれども、何年かかるかわかりませんけれども、減免によって将来的に少しずつもとが取れるという、このような話をするのもまた一つの手かと思うのですけれども。","respondent":"鈴木建築課長","answer":"通常ですと、非課税を行う申請者が測量等、あるいは図面をつくって都税事務所に申請するわけですけれども、今ご提案いただいた中で思ったのは、私道整備は１割負担になりますけれども、過去５年間の統計を見ますと、１件当たり約１０万円の負担で。","voiceIndex":322,"id":"exchange-135"},{"speaker":"浅野委員","kind":"提案","question":"続きまして、道路維持費の件ですけれども、４年前くらいになるのですけれども、私が一般質問で、区が維持管理している街路灯やカーブミラー、街頭消火器など、このような設置物について異常があった場合に、区民が簡単に携帯電話やメール送信などで区に通報できる取組みを提案したことがあります。このような通報は、年間どのくらい、区民の方からいただいているのか、教えてください。","respondent":"稲田道路課長","answer":"区に寄せられる街路灯や道路の維持関係、標識等におきましての件数ですが、平成２５年度は、年間約１,４００件ほどきております。","voiceIndex":324,"id":"exchange-136"},{"speaker":"浅野委員","kind":"質問・要望","question":"年間１,４００件というと、相当な数だと思いますので、対処するのも大変だと思います。そのような中で、千葉市の件と愛知県半田市の例をいただきましたけれども、千葉市では、スマホでレポートすることによって、ウェブ上で公開できるような形になっていまして、１カ月で１,１００人の方がレポーターに登録をして、３００件のレポートが寄せられている。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこの商店街の街路灯を１回外して、区のほうで新たに設置はしてもらったのですけれども、何か腑に落ちないというか、無駄なお金になってしまうようなことを、どう考えたらいいのかということ。それから、清流復活については、事業概要の中で、これは東京都の全額負担で、目黒区、世田谷区とともに事業実施を継続的に依頼しているというお話の中で、現状がどうなっているのか、その辺を教えてください。","respondent":"稲田道路課長、奥田河川下水道課長","answer":"商店街灯を街路灯に引き継げないかという件です。考え方としましては、商店街灯は道路の占用物ということで許可をして立てていただいているものです。城南河川の清流復活事業についてですが、こちちは、目黒川の水質浄化対策として、平成７年から東京都の事業としてやっているものです。区画線についてですが、区道の区画線におきましては交通管理者と協議して、引くところ、引かないところ、その都度検討しています。","voiceIndex":328,"id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"確認","question":"最近ちょっとついたのですけれども、それを区のほうから言うのか、それとも国が直接気がつかなければできないのか、その辺を確認したかったのです。使い方でいい活用ができれば、ぜひお願いしたいと思います。河川清流は、要するに何を聞きたかったかというと、どういう状況の折衝をしていらっしゃるのか、財源がどこから出ているのか、財源だけ教えてください。","respondent":"奥田河川下水道課長","answer":"東京都の分につきましては、東京都の環境局から出ておりまして、区でやっている分につきましては、区の一般財源です。","voiceIndex":332,"id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"バリアフリーで随分やっていただいて、進めていただく、しかも七十何m2という広い範囲の中でバリアフリーを考えていただいている。１カ所確認したいのは、東大井の保育園のところに入っていくのに、私道があります。それからもう１点、広町のほうは、整備検討等分担金ということで約１,０００万円払っていますが、これはどういう検討に対しての分担ということで払っているのか、それを教えてください。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"こういったところを外れた地域、あるいは私道だとか、広い範囲におきまして、もしそういった危険なところがあれば、これはこのバリアフリー計画の策定にとどまらず、そういった必要な働きかけについて、可能な限り進めていきたい。私のほうからは、広町地区の検討の分担金について、ご説明します。","voiceIndex":334,"id":"exchange-140"},{"speaker":"鈴木（真）委員","kind":"質問","question":"広町の検討はわかるのですけれども、どういう方向で考えているのか、区の考え方をひとつ教えてもらいたいと思います。前にも質問したことがありますが、今、空いている部分をできれば活用してもらいたいと感じています。あそこも私道なのですよね。我々がよく聞くのは、例えば手すりをつけられないかというような話もあるのですけれども、そういうときにどう考えたらいいのか、その点もお答えください。","respondent":"溝口都市開発課長、鈴木建築課長","answer":"委員ご指摘の暫定利用ですが、建物の間、いろいろ駐車場で使っているところもありますが、地域的、期限限定になるかもしれませんが、イベント等といったものを含めてＪＲと検討していきたいと考えているものです。私道について、手すり等の設置についても、品川区の私道整備事業の中にメニューがありますので、そういったものをぜひ活用していただいて、整備のお手伝いをしていきたいと考えております。","voiceIndex":337,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"私は、１６７ページ、都市防災まちづくり事業費、そして、１６２ページの電線類地中化について、お聞きしたいと思います。お聞きしたいのは、密集住宅市街地整備促進事業、住宅建築物等の耐震化支援事業など、品川区ではさまざまな事業をやっております。そして、さらなるこういう対策も必要ではないかというものを考えておられるようでしたら、それについても教えてください。","respondent":"寺嶋木密整備担当課長","answer":"したがいまして、対策としましては、やはり個別の訪問等を、また説明会等を使って粘り強く説明をして、ご理解いただくと、これに尽きると考えています。","voiceIndex":341,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"ですが今、喫緊で、いつ大都市に首都直下型地震が起きるかわからないという状況ならば、やはりそれなりの手だてを、東京都とも考えていただいて進めるべきものもあるかなと考えています。一生懸命いろいろな手だてを考えて、個別訪問もされてやっているのですが、何かそういう手法を取らない限り難しいかと思うのですが、どうでしょうか。それについての見解をお聞かせください。","respondent":"寺嶋木密整備担当課長","answer":"考え方の一つとはして、ご意見としては承っておきたいと思いますけれども、先ほど答弁で一つお伝えし忘れたものがありまして、密集事業が進まないという背景を踏まえまして、これは今日の別の答弁の中で申し上げたところですが、東京都が。","voiceIndex":343,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうならば、現在の電線類の地中化対策は緊急課題だと思います。工事の費用も３分の１、４分の１ということですし、１回埋めて、埋め戻して、また時期がきて順々に、今の手法で、きちんと電線類を守るような方法でまたつくりかえればいいのではないですか。でも今、喫緊の課題ではないですか、何とかしなければいけないと、私は思うのですが、それについてのご見解をお聞かせください。","respondent":"稲田道路課長","answer":"委員おっしゃるように、穴を掘って埋めてしまえばいいのではないかというのは、そうできればやりたいところですけれども、これにはやはり電線管理者のトランス、変圧器の置き場所、細かく言えば、そういうところも問題ですし、確かに地震がいつ来るかわからないというところでは。","voiceIndex":345,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"毎年一生懸命皆さんが電線地中化をやって、いざというときのために、何か防災対策を施さなければいけない。でも、進まないということは、やはり少し問題があるではないですか。私は、何としても、主要な道路だけでも進めるような考え方でやって、多くの区民が逃げる場所だけは確保して、一部でもいいのです、そういうことを考えてやってほしいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":347,"id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"１６９ページの住宅改善工事助成について、そして１５９ページの大森駅自転車等駐車場の増設工事について、伺います。住宅改善工事の助成についてですけれども、この制度内容について、教えていただきたいと思います。それから、大森駅の自転車のほうは、１２月ごろをめどに着工したいと、今年の７月の建設委員会では表明しておられたけれども、今後のスケジュールについて、教えていただきたいと思います。","respondent":"矢木住宅担当課長、田口交通安全担当課長","answer":"こちらは、対象が区民、マンション管理組合、賃貸住宅の個人オーナーということで、この方々がエコないし、バリアフリーの工事をした場合に、工事費用全体の１０％、区民の方は上限２０万円。大森駅の駐輪場の件につきましては、今年８月に２回、住民説明会を実施しています。その中でもいろいろなご意見が出ました。地域の方々からも、いろいろなご意見をいただいております。今、その辺を精査しながら、検討をしています。","voiceIndex":349,"id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"住宅改善工事助成についてですけれども、平成２６年度の内容が、昨年度に比べて変わっていると思うのですけれども、何がどう変わったのか、教えていただきたいと思います。そして、その変えた理由は何なのかも伺います。これについては、大田区は既に持っているし、ＪＲとの関係もできているということで、品川区が声をかければ、すぐにでもできるのではないかと思いますので、その点について伺います。","respondent":"矢木住宅担当課長、田口交通安全担当課長","answer":"平成２４年度から平成２５年度への変更点というふうに承りました。ＪＲ、また大田区との協議会ですが、ＪＲ、または大田区とは、我々も連携を図りながら進めているところです。これからも、駐輪場のあり方など、さまざまな観点から検討を引き続き行っていく予定です。","voiceIndex":352,"id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"協議会のほうは、ぜひしっかりと品川区から声をかけていただきたいと、強く要望しておきたいと思います。住宅改善のほうの関係ですけれども、介護保険による住宅改修、また住宅耐震化、こういう他の助成制度を一緒に併用することができなくなってしまったと聞いているのですけれども、その点についてはどうなのかと、なくした理由について、伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"介護保険および身体障害者・児給付の助成制度との併用をなくした点につきましては、これらのほうも同様に制度がございまして、二重の支給になってしまうために、そちらのほうを優先させていただいて、対象外にしたものです。","voiceIndex":355,"id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"二重に支給ということですけれども、それはきちんとそれぞれのところで対応していくということで、重ならないように、区のほうがきちんと整理をすればいい話で、やっぱり私は仕事を確保させるという点で、一つの窓口でこの住宅改善の助成を使いたいと申し出た区民には、そういう制度もあります、一緒にやったらどうですかとしておいたほうが、いっぱい区民の方たちの要望が出ると思うわけですけれども。","respondent":"矢木住宅担当課長","answer":"介護保険は、先ほど、委員がおっしゃったとおり、ほかの制度ということで、もちろんこの制度を利用してやられたほうがより厚く助成されます、というようなご案内はしておりますし、密接に連携を取っておりますので、そのような不便は、実際上ないと考えております。","voiceIndex":357,"id":"exchange-149"},{"speaker":"南委員","kind":"質問","question":"この助成制度は、平成２３年には、介護等住宅耐震化がついていました。その後、つけたり、外したりという変遷があって、今日に至っているわけですね。平成２３年のときの予算と決算の状況を見ると、予算を上回って申請がたくさんあると、私には見受けられるのです。したがって、外さずに、やっぱりもとに戻すべきだと思っているのですけれども、その点についての見解を伺います。","respondent":"矢木住宅担当課長","answer":"今年度に関しましては、施工業者説明会等を開きまして、平成２６年度の現時点での実績ですが、既に６５件助成しておりまして、申請としても１００件を超えてありますので、区内業者の育成という点では、一定の成果を上げているものと考えております。","voiceIndex":359,"id":"exchange-150"},{"speaker":"南委員","kind":"質問・要望","question":"区内業者のところにも仕事がいっているという説明が、今ありましたけれども、しかし、こういうバリアフリー、エコだけではなくて、もっと対象範囲を広げることによって、仕事をもっと拡大させていくという立場に品川区が立つことが大事だと思うのです。したがって、ぜひ改善を求めていきたいと思っています。強くそのことは求めて、時間がないので終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":361,"id":"exchange-151"},{"speaker":"いながわ委員","kind":"提案","question":"私から、１５９ページ、地籍調査。具体的に提案をしていきたいのですけれども、何回もここは危ないですよと、事故がありますと、いろいろ警告、カラー舗装をしていただいたり、止まれを書いていただいたり、巻き看板をやっていただいたりしているのですが、なかなか減らないのが現状です。それから、１６０ページの道路維持全般でお伺いします。これは何回か質問させていただいていますので、教えてください。","respondent":"安井土木管理課長、稲田道路課長、田口交通安全担当課長、溝口都市開発課長","answer":"私のほうからは、地籍調査について、ご説明申し上げます。カーブミラーや街路灯、現場にあって通報する方が、連絡をすぐにはできないということで、そこに何か表示したらいいのではないかというお話です。現場で、今のスケアード・ストレート方式です。私は大変インパクトのある安全教育ができるのではないかと考えております。今後、まちづくりに合わせた形で、基盤整備と合わせて、どのような形の駅前広場がいいのか、また。","voiceIndex":363,"id":"exchange-152"},{"speaker":"いながわ委員","kind":"質問・要望","question":"カーブミラーとか、そういうものは、あれも安全の確認のためにありますので、しっかりとやっていただきたいと思います。１６８ページの建築費の中で、平成２４年度の執行率が５３.１％で、今回５７.２％で、多少上がっているのですが、これは要は耐震化の支援の部分の上下なのかと思っているのですが、それがどうなのか、教えてください。","respondent":"鈴木建築課長","answer":"リサイクル法につきましても、さまざまな事務費でございまして、執行率については、全体ではほぼ建築構造の耐震化支援費が主な内容で、そちらの執行率が上がっているところだと思います。","voiceIndex":369,"id":"exchange-153"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この実績どうこうという、昔よく私も質問していたのですけれども、これはもう単純にやり続けていただくしかないと思いますので、ぜひ根気よくやっていただきたいと思います。その中でちょっと時間があれですけれども、１点だけ。そのもとになっているのが、例えば密集の定義とか、そういうところになってくると思うのですけれども、密集の定義というのは、前も今も変わっていないのかどうかお願いします。","respondent":"寺嶋木密整備担当課長","answer":"定義という名称でされているものではないのですけれども、東京都のほうは平成９年だと思うのですが、策定した計画の中に木造住宅密集地域整備プログラムというのがありまして、この中で密集市街地というのが明確に位置づけられております。","voiceIndex":371,"id":"exchange-154"},{"speaker":"いながわ委員","kind":"質問","question":"地域危険度測定調査においても、品川区はワースト１０の中に入ってしまった。そうすると、実際何を指標にして、密集は密集なわけですから、そういうものもどんどん積極的にやることが、こういった密集の整備にもつながっていくと思うのですが、その辺はどうお考えか教えてください。","respondent":"寺嶋木密整備担当課長","answer":"例えば１００m2以上でないと国費、都費がもらえないということもありまして、そちらのほうと勘案した事業展開になっております。","voiceIndex":373,"id":"exchange-155"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういうことも含めて、都市計画道路の整備というものは必要だと思いますので、しっかりやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":375,"id":"exchange-156"},{"speaker":"たけうち委員","kind":"質問","question":"私は、１５９ページの交通安全啓発費に関連してと、１６０ページの街路灯管理費で伺いたいと思います。以前に１時間たってどのくらい開くのか計測したら、２０分なかったのです、今はどうなっているかわからないのですけれども。こういう踏切を、例えば苗木原みたいにしていくにあたっては、どのような手順というか、どのようにしていけばなるのかというのを教えてください。","respondent":"稲田道路課長","answer":"委員、先ほどご指摘の、苗木原踏切、下神明１号踏切、大崎広小路２号踏切におきましては、拡幅工事を実施してきたという経緯があります。その他の踏切におきまして実施したところでは、１５カ所、踏切内のカラー化工事を、今までに実施してきておるところです。","voiceIndex":377,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実は、近隣の方からも要望を受けましたので、１回ぜひ見ていただいて、拡幅ができるのか、カラー舗装をもう１回やり直すのかわかりませんけれども、安全対策をしっかりお願いしたいと思いますので、要望したいと思います。そのスピード感ですね、どれくらいのスピード感を持ってやっていくのか、少し漠然とした言い方なのですけれども、教えていただきたいと思います。","respondent":"稲田道路課長","answer":"現在まで、街路灯の建替え事業というのを、実施計画に基づきやってきております。年間５００基を目途に、現在までは省エネ型蛍光灯を使っていたのですが、それを建て替えてきているのが現状です。","voiceIndex":379,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"意見","question":"実施計画でも、大体５００基ずつくらい変えていくというのが出ております。少し私が心配していますのは、昨年１０月、熊本で水銀に関する水俣条約というのが採択されまして、世界的に脱水銀に向けた動きが出たわけです。この条約についての概要と、これについての区の見解をお知らせください。","respondent":"稲田道路課長","answer":"これは、水銀が人の健康や環境に与えるリスクを低減するために国際的な規制を定めていこうという条約ということで認識しております。こちらは、水銀の製造や輸出入というものを、２０２０年までには規制していこうと、具体的に言えば、そういうところと認識しております。","voiceIndex":381,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"意見","question":"今度、輸出入が規制されますので、一番心配しているのは、品川区に１万幾つかある水銀灯を廃棄するにあたって、引き取り手が出てくるのかどうか。仮に引き取ってくれるにしても、今より高額になるのではないか。その中で言えば、今ＬＥＤにシフトしていかないと、スピード感を持ってやっていかないといけないのではないかという危惧を持っているのですけれども、区の見解をお示しください。","respondent":"稲田道路課長","answer":"確かに委員ご指摘のように、この条約では２０２０年度までの製造です。ただまだ国のほうで法整備を、今現在、整理している段階だと聞いております。今後、国の方針等が決められていった中におきまして、また検討等をしていきたいと考えています。","voiceIndex":383,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"提案","question":"２０２０年といいますと、オリンピック・パラリンピックが始まりますけれども、いろいろな形で、水俣条約という名前をつけているのは、ご存じのように、日本が水俣病という、水銀による被害があって、これを日本が提案して、全会一致で採択されて国際条約になったので、やはり廃棄についてしっかりと考えていかないと、一自治体でありますけれども、ＬＥＤの効果等はある程度証明されてきたならば。","respondent":"松代防災まちづくり事業部長","answer":"今後の国の動向等もしっかり見極めてまいりますけれども、先ほど、担当課長がご答弁しましたように、これからは、街路灯のＬＥＤ化という方向で、水銀灯の切り換えも含めて、今後しっかりと数年先の計画も見直しまして対応していきたいと考えているところです。","voiceIndex":385,"id":"exchange-161"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１５９ページ交通安全啓発費に関連して、それから、１６２ページ、私道排水設備工事費に関連して質問します。法律の自転車のことであります。今までの自転車に対するとらえ方を変えていかないといけないということを、私たちは痛感するわけですけれども、改めて、こういうことを取り締まる警視庁としては、この現状をどう踏まえて、また具体的にどう対処していくのかということをお聞かせください。","respondent":"田口交通安全担当課長","answer":"ただ、３.１１の震災以降、自転車の利用者が大変増えて、自転車の事故が多くなったということで、自転車のほうに今シフトをしながら、全体的な交通安全運動を進めているところです。","voiceIndex":388,"id":"exchange-162"},{"speaker":"伊藤委員","kind":"質問・要望","question":"スピードが出るということ、それからやっぱり危ないのは高齢者ですよ。それからやはり、どうしても高齢者の方の交通安全というのは、これから非常に多くなってくるのではないでしょうか。身近な乗り物であるのだけれども、しかも電動であれば、余計に危険性が増すということだから、ある程度焦点を絞って重点的な対応をしていく必要があると思うのですが、いかがでしょうか。","respondent":"田口交通安全担当課長","answer":"高齢者、それから電動自転車ですが、各種安全教育で、実際に例えば電動自転車に乗っていただいて、運転、またいわゆる危険な運転、例えば傘さしだとか、重たいものを持ったりとか、そういったことで、バランスが崩れるという実体験をしていただくというような安全教育というのも。","voiceIndex":390,"id":"exchange-163"},{"speaker":"伊藤委員","kind":"質問・要望","question":"なかなか難しいことではあります。おそらく何十万人の方々が区内でも使っているでしょうから、だけれども、やっぱり今までの自転車に対するとらえ方、それから、電動自転車、高齢者等の新たな問題が出てきているわけであるから、それに対してしっかりとした対処をしていかないと、この問題は解決できないと思うので、それはよろしくお願いいたします。それは北品川三丁目ほか、下水道管再構築等工事です。","respondent":"奥田河川下水道課長","answer":"委員からお話がありましたところは、私道ということで、区といたしましては、間に入ってやらせていただいているのですけれども、地権者同士でまだ話がついていないというところもございまして、区としても積極的にまとまるような形で協力していきたいと考えています。","voiceIndex":392,"id":"exchange-164"},{"speaker":"伊藤委員","kind":"質問","question":"お立場はよくわかります。確かに品川区の立場としては、入ることはできないと、私も思うのだけれども、わざわざ議会まで話がきている以上は、品川区としてもその問題をちゃんと捉えて、どう対処していったらいいのかということを、次に考えるべきだと思うのですが、いかがでしょうか、お答えください。","respondent":"奥田河川下水道課長","answer":"私道ということもございまして、例えば私道助成の窓口を紹介したり、あるいは地権者の立場に立ちましてきめ細かな対応を、これまでもやってきたのですけれども、引き続きやってまいりたいと思いますので、どうぞよろしくお願いいたします。","voiceIndex":394,"id":"exchange-165"},{"speaker":"伊藤委員","kind":"意見","question":"だけれども、こうやって煮詰まってくると、何とかお願いしたいということが出てくるわけであって、そのときに、そちらの部署でできないことはわかるから、品川区の別の部署にその問題をつなげて解決の方策を探ってあげるとか、例えば法律相談の窓口につなげてあげるとか、そういうふうにより前に出た対応をすべきと思うのですが、最後に一言だけ答弁をお願いいたします。","respondent":"松代防災まちづくり事業部長","answer":"こういう案件は本当に難しい問題です。しかし、我々これまでも困っていらっしゃる側に立って、個別にさまざまなご相談に乗り、進めてきた事例もあります。","voiceIndex":396,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":113278,"voices":398}}]);
